pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: heavily reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space avoidance: post_residual in (0, 10) is unusable (min item 1..100 unknown,
    // but tiny gaps rarely reusable). Penalize gaps smaller than a threshold.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 12.0 {
        score += (12.0 - gap) * 15.0; // worst for gap of 1
    }

    // Reward gaps that can fit the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 20.0; // gap blocks next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling existing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Prefer bins tighter than average (well-utilized bins get priority).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when current bin would leave large waste
    // relative to a fresh bin's flexibility. Base new-bin score near capacity residual.
    if bin_residual == bin_capacity {
        score += 40.0 - open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small to ever hold
    // another item are pure waste. Penalize them quadratically.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        // gap in [1,9] is nearly unusable dead space
        score += 60.0 + (10 - post_residual as i32 as f64) * 8.0;
    } else if post_residual < 20 {
        // small-but-usable gap: mild penalty to prefer tighter fits elsewhere
        score += 12.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Open-bins pressure: discourage spreading across many bins when
    // existing bins fit well; encourage opening a new bin when this bin
    // is the only fit (last-chance) and the fit is bad.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last chance: strongly prefer using this bin over a new one
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive when
    // the next item is large relative to this bin's post_residual, or when
    // the fit here would be very loose.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: slightly above a good fit
        score = bin_capacity as f64 * 0.55;
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else if next_item_size > 0 {
        // If the next item can't use this bin's post_residual anyway,
        // loosen the penalty for a loose fit here.
        if next_item_size > post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            // next item could slot into the leftover: reward leaving a usable gap
            let gap_diff = post_residual as i32 - next_item_size as i32;
            if gap_diff <= 5 {
                score -= 15.0;
            }
        }
    }

    // Mean-residual coupling: if average leftover across bins is high,
    // be pickier (penalize loose fits) to consolidate.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score += (mean_residual - 30.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "friendly" classes (multiples of 10, or small enough to be nearly full)
    // are preferred since future items (10..80) can reuse them.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -40.0 // perfect fit is always best
    } else if pr <= 10 {
        -25.0 // leftover smaller than min item => effectively sealed bin
    } else if pr % 10 == 0 {
        -12.0 // decadal class: high chance a future item fits exactly
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward residual class, penalize
    };
    score += class_bonus;

    // Integer-division threshold: residual / capacity fraction bands.
    let fill_frac = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    if fill_frac > 0.8 {
        score -= 15.0; // strongly reward high fill
    } else if fill_frac > 0.5 {
        score -= 5.0;
    } else {
        score += 4.0; // sparse bins waste capacity
    }

    // Dead-space penalty: residual that no plausible item can use.
    if pr > 80 {
        score += 6.0; // only tiny items (<=20) fit; weak reuse
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item exactly matches the post residual
    // (harmonic pairing), reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 3.0;
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
        // modulo harmony: next item and post residual share a decadal class
        if pr > 0 && (pr % 10) == (next_item_size % 10) && next_item_size <= pr {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: prefer existing bins unless this one is
    // nearly full or the stream is early (building a stock of bins is fine).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) * (item_size as f64) / bin_capacity as f64;
        // open a new bin only when existing bins are crowded or residual classes mismatch
        score += 18.0 - 10.0 * pressure - 5.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 10.0; // open bins can't absorb the item well
        }
    }

    // Mild entropy term: spread load when many bins are open and mean residual is high.
    if (mean_residual - post_residual as f64).abs() > 30.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
