pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize dead space in the awkward 11..=20 band (hard to fill later).
    if post_residual >= 11 && post_residual <= 20 {
        score += 25.0;
    }
    if post_residual > 50 {
        score += 8.0;
    }

    // Harmonic class: how well the leftover pairs with typical small items.
    let pr = post_residual as u32;
    if pr > 0 {
        let cls = pr % 10;
        if cls == 0 {
            score -= 10.0; // round leftover, easy to fill
        } else if cls <= 3 {
            score -= 5.0;
        } else {
            score += (cls as f64) * 1.5;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            if nxt_res <= 5 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow here; slight penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor or bins are fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 25 || post_residual > item_size;
        let pressure = (open_bins_count as f64) * 4.0 + mean_residual * 0.3;
        if poor_fit {
            score -= 12.0 + pressure * 0.2;
        } else {
            score += 35.0 + pressure * 0.1;
        }
        // Late in the stream, avoid opening new bins too eagerly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.05;
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize unusable small gaps nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize large leftover gaps only mildly (still usable), scaled by tightness.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Last-chance bonus: only fitting bin, avoid opening new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead coupling: if next item fits post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item nearly fits, slight penalty for leaving a tempting-but-broken gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded/tight.
    if bin_residual == bin_capacity {
        score -= 20.0;
        if open_bins_count as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Late in stream: prefer packing tighter into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual == 0 as u32 as bool) as u32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post_residual exactly matches the next item,
    // creating a perfect fit on the following step.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize leaving dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Prefer tight fits relative to current residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio;

    // Deviation from mean residual: keep residuals balanced.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables
    // a perfect two-item pairing or few bins exist / late stream.
    if bin_residual == bin_capacity {
        let pair = if next_item_size > 0 && post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            bin_capacity as f64
        };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - 0.5 * open_bins_count as f64 - 20.0 * (1.0 - pair / bin_capacity as f64) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item can't fit here; penalize proportionally to wasted space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // lookahead chain: post_residual - next_item_size residual
        let post2 = post_residual as i64 - next_item_size as i64;
        if post2 > 0 && post2 < 10 {
            score -= 40.0; // near-perfect two-item packing
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 80.0;
    }

    // Compare residual against mean residual across open bins
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin bonus: only one bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize leaving small unusable fragments (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Early in stream: mild preference to open new bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 500.0 - slack * 3.0;
        } else {
            // Next item cannot use post residual: penalize small dead space.
            let waste = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 120.0; // tiny unusable sliver
            } else if waste <= 10.0 {
                score += 40.0;
            }
        }
    }

    // Compare post residual against mean residual across open bins.
    // Prefer bins whose post residual deviates toward zero (tight packing).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Brand-new empty bin candidate: penalize moderately so good existing fits win,
    // but keep it attractive when all fits are poor (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        score += 60.0 + (item_size as f64) * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Slight preference for bins with larger residuals used efficiently.
    score -= (bin_residual as f64) * 0.05;

    score
}

