pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward near-perfect two-item packing.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // exact two-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0); // next item still fits afterwards
        } else {
            // next item cannot fit; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0);
        }
    } else {
        // last item: just minimize residual
        score -= 10.0;
    }

    // Relative-to-mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum plausible item size is nearly worthless.
    let dead = (post_residual as f64) * ((post_residual as f64) / bin_capacity as f64);
    score += 0.8 * dead;

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize blocking the next item unless residual is tiny anyway.
            score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for consuming scarce capacity when alternatives exist.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins that are already relatively full
    // (small residual relative to mean residual).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a fresh bin is attractive only
    // when current bins are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowd = open_bins_count as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base cost of a new bin, discounted when many bins are open or
        // the item is big (likely to waste an existing bin's space).
        score = 25.0 - 0.5 * crowd - 20.0 * large_item - 5.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 3.0; // fresh bin can also host the next item
        }
    }

    // Slight early-stream bias toward exploring existing bins less strictly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress.
    // Early in the stream, keep residual space flexible (penalize low post_residual less);
    // late in the stream, tight packing (small post_residual) is rewarded more strongly.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Quadratic-cubic blend: early => mild convex penalty on wasted space,
    // late => strong reward for small residual.
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;

    score += w_early * 0.8 * x * x * cap;
    score -= w_late * 0.6 * (1.0 - x) * (1.0 - x) * cap;

    // Interaction: post_residual vs mean_residual — prefer bins whose post residual
    // aligns with the fleet mean (smooth quadratic divergence penalty).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead coupling: reward residual that can still host the next item,
    // with a smooth saturating (quadratic) term.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= fits_next * (0.5 + 0.5 * gap) * (1.0 - w_early * 0.5);
        // Penalize leaving a residual just barely below the next item (dead zone),
        // smoothly via quadratic proximity.
        let miss = (next_item_size as f64 - pr) / cap;
        let dead = if miss > 0.0 && miss < 0.2 { (0.2 - miss) * (0.2 - miss) } else { 0.0 };
        score += 3.0 * dead * cap;
    }

    // Last-chance bin: smooth reward scaled by fitting scarcity.
    if fitting_bins_count <= 1 {
        score -= 2.0 + 3.0 * progress;
    } else {
        // Mild crowding penalty as many bins compete, quadratic in count.
        score += 0.02 * (fitting_bins_count as f64) * (fitting_bins_count as f64);
    }

    // Open-bin pressure: mildly discourage spreading across many bins early on.
    score += 0.1 * (open_bins_count as f64) * w_early;

    // New-bin candidate: penalize opening a fresh bin unless residual is very large
    // (smooth exponential-style barrier instead of piecewise constant).
    if bin_residual == bin_capacity {
        let tightness = 1.0 - x; // 1 when all other bins are nearly full conceptually
        score += 6.0 * (1.0 - progress) + 4.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10.
    // Residuals that are "harmonic" with typical item sizes (multiples of 10
    // and common residues like 0, 5) are more reusable; odd tiny residues are dead space.
    let residue = post_residual % 10;
    match residue {
        0 => score -= 12.0,                 // perfectly harmonic residual
        5 => score -= 6.0,                  // half-class, still useful
        2 | 8 => score -= 2.0,
        1 | 9 => score += 6.0,              // nearly dead space
        _ => score += 3.0,                  // 3,4,6,7 : mediocre reusability
    }

    // Integer-division thresholds: classify post_residual into usable size bands.
    let band = post_residual / 10; // 0..10
    match band {
        0 => score += 40.0,                 // <10: unusable dead space
        1 => score += 15.0,                 // 10-19: only fits tiny items
        2 => score += 5.0,
        3 | 4 => score -= 4.0,              // sweet spot for mid items
        5 | 6 => score -= 6.0,
        _ => {}
    }

    // Tight fit reward: how exactly the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0;                      // perfect closure
    } else if post_residual <= 5 {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;                  // perfect chain fit
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack as f64 / 50.0).max(0.0);
        } else {
            // next item cannot fit here: post residual becomes a gamble
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln() * 3.0;
    score -= mean_residual * 0.05 * progress;

    // New-bin candidate handling: an empty bin should only win when the current
    // bin would leave bad dead space or the item is huge (needs fresh space).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = 55.0;
        if item_size >= 60 {
            new_bin_score -= 30.0;          // huge items deserve fresh bins
        }
        if post_residual <= 10 && post_residual > 0 {
            new_bin_score -= 45.0;          // placing here creates dead space
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;         // no alternative
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small but potentially usable gaps are mildly penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Lookahead: if next item could use the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit the leftover, penalize leaving an awkward gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score += 20.0 * progress;
    }

    // Prefer bins with below-average residual (more filled) to balance load.
    score += 0.15 * ((bin_residual as f64) - mean_residual).max(-50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect match: next item exactly fills the post residual.
        if (pr - nxt).abs() < 0.5 {
            score -= 60.0;
        } else if nxt <= pr {
            // Next item fits: reward proportional tightness of the 2-step chain.
            let tightness = 1.0 - (pr - nxt) / bin_capacity as f64;
            score -= 8.0 + 30.0 * tightness;
        } else {
            // Next item does NOT fit this bin after placement: penalize,
            // scaled by how badly it misses (wasted lookahead opportunity).
            let miss = (nxt - pr).min(bin_capacity as f64);
            score += 2.0 + 0.25 * miss;
        }

        // Compare chain quality against mean residual across open bins.
        if mean_residual > 0.0 {
            let chain = pr + nxt;
            if (chain - bin_capacity as f64).abs() <= mean_residual * 0.5 {
                score -= 10.0; // chain nearly closes a bin better than average
            }
        }
    } else {
        // Last item: just minimize dead space aggressively.
        score += 0.5 * post_residual as f64;
    }

    // --- Dead-space penalty for tiny unusable residuals ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // --- Last-chance bin: strongly prefer using it before opening new ones ---
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // --- Prefer fuller bins relative to mean residual ---
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // --- Late in the stream: consolidate, avoid opening new bins ---
    if open_bins_count > 0 {
        score += 5.0 * progress;
    }

    // --- New-bin candidate: only attractive when no open bin fits well ---
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual > 0);
        if poor_fit {
            score -= 25.0;
        } else {
            score += 30.0; // keep using existing bins when they fit decently
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post_residual that is too small to matter is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item can fit into post_residual exactly / well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 30.0 * next_fit; // chain-friendly residual
        } else {
            // residual can't host next item: penalize more if residual is large-ish (trapped space)
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening new bins, more when many bins are open or late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // But if current bin fit is terrible (item barely fits / huge dead space),
        // relax the penalty so new bin can win.
        if fit_ratio > 0.95 || post_residual < 10 {
            score -= 50.0;
        }
        // If next item is large and this bin would be nearly emptied, new bin is attractive.
        if next_item_size > 0 && next_item_size >= post_residual && post_residual < 15 {
            score -= 25.0;
        }
    }

    // Global state coupling: if mean residual is low (bins nearly full), favor
    // filling existing bins aggressively; if mean residual is high, be pickier.
    let mean_r = mean_residual.max(0.0);
    score += 0.10 * (mean_r - post_residual as f64);

    // Slight preference to use more-opened bins early (keep bin count down).
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = pr + 40.0 * prn * prn * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate larger leftovers; late in the stream penalize them harder.
    let coupling = prn * prn * (1.0 - progress) + prn * progress * progress * 3.0;
    score += coupling * cap * 0.8;

    // Smooth fill-rate reward: high fill ratio gets subtracted non-linearly.
    let fill = 1.0 - prn;
    score -= 60.0 * fill * fill * fill;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * fill;
    }

    // Penalize bins whose post-residual becomes dead space relative to future need.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            // Smooth quadratic penalty for missing the next item.
            score += 0.35 * gap * gap / cap * 10.0;
        } else {
            // Reward bins that can also host the next item, smoothly by tightness.
            score -= 12.0 * (1.0 + (-gap / cap)) * fill;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.4 * pressure * prn;

    // Mean-residual alignment: bins far from mean residual are slightly penalized.
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make empty bins attractive only for large items or early stream.
    if bin_residual == bin_capacity {
        let emptiness_bias = 18.0 - 30.0 * (item_size as f64 / cap) - 10.0 * (1.0 - progress);
        score += emptiness_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a "good" residue
    // (divisible by small common sizes) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post_residuals that are multiples of small item sizes (1..=10 classes)
    let mut harmonic_bonus = 0.0;
    for m in 1..=10u32 {
        if post_residual % m == 0 && post_residual > 0 {
            harmonic_bonus += 8.0 / m as f64;
        }
    }
    score -= harmonic_bonus;

    // Penalize dead space in the awkward band (1..10 after large harmonics fail):
    // tiny unusable slivers are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Capacity fraction thresholds: fill fraction of the bin.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac > 0.9 {
        score -= 20.0; // nearly full bin: excellent
    } else if fill_frac > 0.7 {
        score -= 10.0;
    } else if fill_frac < 0.5 {
        score += 8.0; // leaving bin half empty is wasteful
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; leftover becomes dead weight
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer opening a new bin early in the stream or when many bins are open
        // and mean residual is low (existing bins are fragmented).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        score += 12.0; // base cost of a fresh bin
        score -= progress * 6.0;
        score -= (1.0 - pressure) * 5.0;
        if post_residual == bin_capacity {
            score += 0.0; // empty bin keeps full flexibility
        }
    } else {
        // Slight preference for tighter bins relative to the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Exact fit is always perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are unusable for
