    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 12.0;
    }

    // Reward snug fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: with many open bins, discourage spreading;
    // strongly discourage opening a new bin when other bins can fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 35.0;
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.5 * open_bins_count as f64;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 10.0;
    }

    // Progress: late in the stream, slightly prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

