}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover after that pairing
            score -= 50.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize leaving a dead-space gap
            score += 0.3 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Prefer bins tighter than average (relative to mean residual).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Mild penalty for opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, prefer tighter fits (waste less).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 0.5 + 1.5 * progress;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
        // Perfect chain: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        let waste = post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs();
        score += 0.1 * (post_residual as f64).powf(1.3);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many alternatives: slight penalty to keep options open.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Global state coupling: if mean residual is low, conserve tight bins;
    // if mean residual is high, prefer filling the emptiest-feeling bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += desperation + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, opening fresh bins is more acceptable for large items.
        if item_size > 50 {
            score -= 8.0 * progress;
        }
    }

    // Mild penalty for very small post residuals that become dead space,
    // unless they are exactly zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, but its value is modulated smoothly by stream progress.
    // Early on, prefer tight fits (low post_residual); late, dead space hurts more.
    let progress_weight = 1.0 + progress * progress * 2.0;
    let mut score = pr * progress_weight;

    // Non-linear quadratic coupling: small post_residuals are rewarded more
    // as the stream progresses (quadratic decay term).
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // Penalize large post_residual relative to mean residual (creating outliers).
    let dev = norm_pr - mean_residual / cap;
    score += dev * dev * 20.0;

    // Lookahead: reward bins whose post-residual can fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 8.0 + 6.0 * progress;
        } else {
            // Smooth penalty for wasted capacity near the next item's size.
            let gap = (nx - pr as f64) / cap;
            score += gap * gap * 40.0;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for proliferating bins early (encourage consolidation).
    score += (open_bins_count as f64) * progress * 0.5;

    // New-bin candidate: make it attractive only when item is large relative
    // to typical residuals, smoothly interpolated.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score = 60.0 - 50.0 * size_frac * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: post_residual modulo capacity fractions (C/8 = 12.5 -> use 13 / 25 / 50)
    let pr = post_residual as u32;
    let mod25 = pr % 25;
    let mod13 = pr % 13;
    let mod50 = pr % 50;

    // Reward post-residuals that are "usable" harmonic classes (multiples of 25, 13, 50)
    if mod25 == 0 { score -= 8.0; }
    if mod50 == 0 { score -= 6.0; }
    if mod13 == 0 { score -= 3.0; }

    // Penalize awkward dead-space classes (small but nonzero remainders)
    if pr > 0 && pr <= 9 { score += 12.0 * (10 - pr) as f64; }
    if pr >= 10 && pr <= 12 { score += 4.0; }

    // Lookahead coupling: does next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Bonus scaled by how well the next item fills the post-residual
            let fill = next_item_size as f64 / pr as f64;
            score -= 10.0 * fill;
            // Harmonic match: next item leaves again a nice class
            let pr2 = pr - next_item_size;
            if pr2 % 25 == 0 || pr2 % 13 == 0 || pr2 == 0 { score -= 5.0; }
        } else {
            // Next item won't fit here: penalize proportionally to the waste
            let waste = next_item_size as f64 - pr as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized unless current fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 - 3.0 * progress;
        // Opening a new bin is attractive if mean residual is small (all bins nearly full)
        score -= 0.05 * (cap - mean_residual);
    }

    // Mild penalty for leaving residual far from any harmonic class center
    let frac = pr as f64 / cap;
    let nearest_quarter = (frac * 4.0).round() / 4.0;
    score += 6.0 * (frac - nearest_quarter).abs();

    // Small tie-breaker: prefer tighter fits overall
    score += 0.01 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is nearly worthless
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Penalize residual that no plausible item (1..=100) can use well:
    // gaps just above small-item sizes are dead weight.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 50.0 {
        // quadratic dead-space penalty concentrated on small gaps
        score += (50.0 - gap) * (50.0 - gap) / 50.0;
    }

    // Reward filling bins deeply (high utilization of the chosen bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few bins, new-bin opening is cheaper.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // is large and no tight alternative exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 60 {
            score -= 30.0; // large items are fine in a fresh bin
        }
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // reward leaving that gap; otherwise penalize gaps that block it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 18.0; // post residual chains perfectly to next item
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // gap too small for the next item: dead space risk
        }
    }

    // Mild phase pressure: late in the stream, avoid spawning bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Slight preference for bins below mean residual (balance residuals,
    // keeping mid-size gaps usable across the fleet).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.82;
