pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is very small.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 12.0;
    } else {
        // penalize dead space that is too small to be useful for typical items
        score += (post_residual as f64).powf(1.3) * 0.05;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; slight penalty proportional to overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.05 * overflow;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base cost for opening a new bin; discount early when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 30.0 - 10.0 * progress;
        // If the item fits poorly everywhere (high mean residual mismatch), new bin is fine.
        if post_residual as f64 > mean_residual {
            new_bin_cost -= 5.0;
        }
        if fragmentation > 20.0 {
            new_bin_cost -= 5.0;
        }
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            new_bin_cost -= 6.0;
        }
        score += new_bin_cost.max(0.0);
    } else {
        // Prefer bins with larger residual among open bins (fill fuller bins first).
        score -= 0.02 * bin_residual as f64;
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits mildly; late: penalize wasted residual strongly.
    let poly = pr * pr / cap; // quadratic dead-space pressure
    let coupling = poly * (0.5 + progress * progress);
    score += 0.6 * coupling;

    // Reward high fill ratio smoothly (cubic in fit_ratio), stronger as stream progresses.
    score -= (fit_ratio * fit_ratio * fit_ratio) * (20.0 + 30.0 * progress);

    // Exact fit: strong reward, amplified with progress.
    if post_residual == 0 {
        score -= 40.0 + 40.0 * progress;
    }

    // Last chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 15.0 * progress;
    }

    // Lookahead synergy: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 + 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // Next item won't fit here: mild penalty scaled by overshoot.
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Penalize bins deviating from mean residual (prefer balanced residual profile),
    // with smooth quadratic term.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Many open bins: prefer consolidating into existing ones (penalize new-bin tendency).
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_residual;
    if is_new_bin {
        score += 10.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    } else {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Tight fit reward: post_residual near zero is prime packing ---
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // --- Harmonic classes: post_residual divisible by 10 keeps future
    //     alignment with integer item sizes (dead-space modularity) ---
    let pr = post_residual as u32;
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0; // harmonic residual, reusable by decile-sized items
    } else if pr > 0 && pr % 5 == 0 {
        score -= 3.0;
    } else if pr < 10 {
        // sub-10 dead space is unusable for items >= 10: penalize hard
        score += 25.0;
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward proportionally to how well next item consumes remainder
            let consumed = pr - next_item_size;
            score -= 15.0 - (consumed as f64) * 0.3;
        } else {
            // next item cannot use this bin's remainder: mild penalty scaled
            // by how much would be wasted relative to capacity
            score += (pr as f64) * 0.15;
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, prefer using it
    //     over opening a new bin unless the fit is terrible ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // --- New-bin candidate handling: neutral-ish baseline so it only wins
    //     when open bins offer poor fits ---
    if bin_residual == bin_capacity {
        // fresh bin: score = capacity (100) minus a discount; competing bins
        // with tight fits easily beat this, fragmented bins lose to it
        score = (bin_capacity as f64) - 10.0
            + (item_size as f64) * 0.05
            - (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only fitting open bin
        }
        return score;
    }

    // --- Fill-ratio coupling: reward bins whose residual is being driven low
    //     relative to mean residual across open bins ---
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 20.0;

    // --- Congestion: many open bins -> prefer consolidating into existing
    //     residual mass (mean_residual high means bins are fragmented) ---
    if mean_residual > (bin_capacity as f64) * 0.5 && open_bins_count > 2 {
        score -= 5.0; // encourage using up scattered space
    }

    // --- Stream progression: late in stream, close bins aggressively ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bins pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus pressure from open bins.
        score += 30.0 + (open_bins_count as f64) * 6.0;
        // If next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual * 0.5 {
            score -= 15.0;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure slightly.
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Next item fits in the leftover: mild reward.
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Leftover likely dead space for the next item: penalty scaled by gap.
        let gap = (next_item_size - post_residual) as f64;
        if gap < 15.0 {
            score += 20.0 - gap;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Late-stream consolidation: favor filling existing bins harder near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match leaves room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Reward leaving a usable chunk for the next item,
            // scaled by how snugly the next item will nest.
            let slack = post_residual - next_item_size;
            score -= 60.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit in the leftover: penalize dead space.
            score += 50.0 + 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Dead space shaping: tiny non-zero leftovers are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere
    // (large item, high mean residual, many open bins).
    if bin_residual == bin_capacity {
        score = 1000.0
            - 3.0 * item_size as f64
            + 1.5 * mean_residual
            + 10.0 * open_bins_count as f64
            - 200.0 * (fitting_bins_count as f64).min(1.0);
    }

    // Slight stream-progression nudge: late in the stream, consolidate more.
    score += 20.0 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: post_residual that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 15.0 * next_fit;
        } else if next_item_size <= bin_residual {
