            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current fit is bad
    // or when open bins are already fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin base penalty, relaxed late in the stream when fragmentation matters more.
        score += 20.0 + 30.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, a fresh bin is fine.
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 25.0;
        }
        // If the item would leave a huge gap in an existing bin anyway, allow a new bin.
        if post_residual as f64 > bin_capacity as f64 * 0.6 {
            score -= 20.0;
        }
    } else {
        // Prefer using existing bins, scaled by how many are already open (fragmentation control).
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Reward bins whose residual is close to the mean (balance residual spread).
        score -= 3.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64)).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_pr * norm_pr * (1.0 + p2) - 8.0 * norm_pr * p3;

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Penalize bins deviating from mean residual (keep residuals homogeneous)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead: favor leaving space usable by the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let waste = (pr - n) / cap;
            score -= 10.0 * (1.0 - waste * waste);
        } else {
            score += 8.0 * (n - pr) / cap;
        }
    }

    // Mild penalty for many open bins, scaled by progress
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * p2);

    // Penalize new-bin opening unless item is large relative to capacity
    if bin_residual as u32 == bin_capacity {
        score += 25.0 - 15.0 * (item_size as f64 / cap) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it partitions the capacity
    let post = post_residual as u32;
    let class = post % 20; // harmonic sub-class modulo 20
    let quarter = bin_capacity / 4;

    // Reward post-residuals that fall into "usable" harmonic classes.
    // Residuals near multiples of 25 (quarter-capacity) are prime slots for
    // typical item sizes; residuals in dead zones (1..10) are wasted.
    if post == 0 {
        score -= 40.0; // perfect closure
    } else if post < 10 {
        score += 35.0; // dead space penalty
    } else if post % 25 == 0 {
        score -= 25.0; // quarter-capacity harmonic slot
    } else if post % 10 == 0 {
        score -= 12.0; // decade harmonic slot
    } else if class <= 5 {
        score += 8.0; // awkward small class
    }

    // Integer-division thresholds: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        let fits_next = post >= next_item_size;
        // also check if post + next would close a bin nicely after pairing
        let pair_sum = item_size as u64 + next_item_size as u64;
        if fits_next {
            // how harmonically does post divide into next-sized chunks?
            let chunks = post / next_item_size.max(1);
            let leftover = post % next_item_size.max(1);
            if leftover == 0 {
                score -= 20.0 + 5.0 * chunks as f64; // perfect tiling
            } else if leftover <= 10 {
                score -= 5.0;
            } else {
                score += 6.0;
            }
        } else {
            // next item won't fit here; prefer bins that at least closed well
            if pair_sum == bin_capacity as u64 {
                score -= 15.0;
            }
            score += 10.0 * (next_item_size as f64 - post as f64).max(0.0) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // penalize new bins mildly; allow when current bins are nearly full
        // or item is huge relative to mean residual
        let crowded = mean_residual / cap < 0.25;
        let big_item = item_size as f64 > 0.7 * cap;
        if crowded || big_item {
            score -= 18.0;
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Progress-aware tightening: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Small nudge toward bins tighter than the mean (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: classify post_residual gaps.
    // Gaps that are "unusable" (too small for typical items) are heavily penalized.
    let gap = post_residual;
    if gap == 0 {
        // Perfect fit: reward strongly.
        score -= 50.0;
    } else if gap < 10 {
        // Dead space: too small for any item (min size 1..100 unknown, but tiny gaps waste).
        score += 30.0;
    } else if gap <= 20 {
        // Marginal gap: only usable by very small items; penalize moderately.
        score += 12.0;
    } else if gap <= 40 {
        // Semi-usable gap.
        score += 4.0;
    }

    // Tightness reward: fraction of the bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Reward filling a large fraction of the residual (efficient use of the bin).
    let residual_use = item_size as f64 / bin_residual as f64;
    score -= 15.0 * residual_use;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // opening a new bin is cheap so slightly favor consolidation anyway.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin is a blank slate. Prefer it
    // only when the current placement would leave a nasty dead gap.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; make it attractive over bad fits
        // but unattractive over good fits.
        score -= 5.0;
        // If the current item would leave dead space in any existing bin,
        // a fresh bin scores relatively better already via the penalties above.
    }

    // Lookahead coupling: if the next item fits into the post_residual gap,
    // this placement is valuable; reward it.
    if next_item_size > 0 && next_item_size as f64 <= gap as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && gap > 0 {
        // Next item won't use the gap: the gap becomes likely dead space.
        score += 6.0 * (gap as f64 / bin_capacity as f64);
    }

    // Mean-residual coupling: if this bin is far below the mean residual,
    // it's a "ragged" bin; consolidating into it is good.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Late-stream consolidation: near the end, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: heavily reward leaving zero dead space.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item exactly matches post_residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 300.0;
        } else if diff <= 5 {
            score -= 120.0 - 20.0 * diff as f64;
        } else if diff <= 15 {
            score -= 20.0;
        } else {
            // Post-residual too small for next item: dead space risk.
            score += (diff as f64).min(40.0) * 0.5;
        }

        // If next item cannot fit anywhere else after this placement,
        // and it would fit here only if we skip it, penalize waste.
        if (post_residual as u32) < next_item_size && next_item_size > 0 {
            // unusable remainder for the lookahead item
            score += 10.0;
        }
    }

    // Compare against mean residual: bins with residual near the mean
    // are "typical"; prefer using bins with smaller residual (tight fits).
    let residual_f = bin_residual as f64;
    let tightness = (residual_f - mean_residual) / bin_capacity as f64;
    score += tightness * 30.0; // penalize bins with larger-than-average residual

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin
    // would leave very awkward residual. Empty-bin call has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; only attractive when item is large
        // relative to capacity (poor fit anywhere else) or few open bins.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 80.0;
        score += 150.0 - large_item_bonus - (open_bins_count as f64 * 5.0);
        // If the item fits perfectly into a fresh bin, opening is cheap.
        if (bin_capacity - item_size) as f64 == next_item_size as f64 && next_item_size > 0 {
            score -= 100.0;
        }
    }

    // Slight preference to fill earlier bins as stream progresses (stability).
    score += (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize if placing here blocks the next item from fitting.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
        // Reward if next item also fits here (chaining).
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 8.0;
        }
    }

    // Prefer fuller bins when many bins are open (contain fragmentation).
    if open_bins_count > 4 {
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill_ratio;
    }

    // Mild bias toward bins below mean residual (leveling) early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += (1.0 - progress) * 6.0 * dev;

    // New-bin candidate: attractive early when existing fits are poor,
    // but discouraged late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64)
        } else { 1.0 };
        score -= 14.0 * (1.0 - progress) * poor_fit;
        score += 5.0 * progress + 0.6 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let p2 = progress * progress;

    // Smooth non-linear coupling of post_residual with progress:
    // late in the stream, tight fills (small post_residual) matter more.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    score += pr_norm * pr_norm * (p2 * 40.0 + 5.0);

    // Reward near-perfect fits, smoothly amplified over time
    let fit_quality = 1.0 - pr_norm;
    score -= fit_quality * fit_quality * (1.0 + p2 * 30.0);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dead = (pr - mean_residual).abs();
    score += dead * dead / (cap * cap) * (1.0 + p2 * 10.0);

    // Last-chance bin: smooth bonus stronger mid/late stream
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * p2;
    }

    // Lookahead: penalize blocking the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (gap / cap) * (1.0 - p2);
        } else {
            score += (-gap / cap) * (4.0 + 8.0 * p2);
        }
    }

    // Slight penalty for many open bins, smoothed by progress
    score += open_bins_count as f64 * (0.3 + 0.7 * p2);

    // Prefer filling existing bins over opening new ones, especially late
    if bin_residual == bin_capacity {
        score += 3.0 + 15.0 * p2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo common item sizes
    // Residuals that are multiples of small harmonic classes (e.g. divisible by 10)
    // are more likely to be filled by future items -> reward them.
    let post = post_residual;
    if post == 0 {
        score -= 40.0; // perfect fit
    } else {
        // Divisibility rewards: harmonic classes mod 10, mod 5
        if post % 10 == 0 {
            score -= 8.0;
        } else if post % 5 == 0 {
            score -= 4.0;
        }
        // Dead-space penalty grows if residual falls in awkward class (1..9 residue)
        let residue = post % 10;
        score += residue as f64 * 0.6;
    }

    // Lookahead coupling: does the next item's harmonic class match post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0; // exact next fit
        } else if post >= next_item_size && (post - next_item_size) % 10 == 0 {
            score -= 12.0; // leaves harmonic residue after next item
        } else if post < next_item_size {
            // bin dies after this placement; penalize proportional to waste
            score += post as f64 * 0.4;
        }
    }

    // Integer-division threshold on post_residual: small fragments are dead space
    if post > 0 && post / 10 == 0 {
        score += 15.0; // residual < 10 is nearly unusable (min item size 10)
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin
    // would leave a large, non-harmonic residual.
    if bin_residual == bin_capacity {
        // baseline competition score
        score = 55.0;
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size == item_size {
            score -= 5.0; // homogeneous stream: fresh bin fine
        }
    }

    // Late-stream tightening: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: avoid bins far below mean (fragmented state)
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: heavily reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space avoidance: post_residual in (0, 10) is unusable (min item 1..100 unknown,
    // but tiny gaps rarely reusable). Penalize gaps smaller than a threshold.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 12.0 {
        score += (12.0 - gap) * 15.0; // worst for gap of 1
    }

    // Reward gaps that can fit the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 20.0; // gap blocks next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling existing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Prefer bins tighter than average (well-utilized bins get priority).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when current bin would leave large waste
    // relative to a fresh bin's flexibility. Base new-bin score near capacity residual.
    if bin_residual == bin_capacity {
        score += 40.0 - open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if post_residual as u32 > next_item_size {
            // Next item fits with slack left; mild reward proportional to tightness.
            let slack = (post_residual as u32 - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportional to wasted potential.
            let gap = (next_item_size - post_residual as u32) as f64;
            score += 10.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer; favor using them.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless existing residuals are large (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host a clean pair
        }
        if mean_residual < item_size as f64 {
            score -= 35.0; // open bins too full to matter
        }
    }

    // Early stream: keep bins open loosely; late stream: tighten.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to wasted fraction.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 3.0;
        }
        // Perfect two-item packing bonus.
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Encourage consolidation when many bins are open.
    score -= 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time horizon: early stream -> be picky (favor big fills); late stream -> just fill bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);
    score -= progress * 2.0;

    // Global residual pressure: if mean residual is low, avoid wasting space further.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: make it moderately attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        if poor_fit {
            score -= 5.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize large post residual, with progress-dependent curvature
    let curvature = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    let mut score = norm_pr * (1.0 + curvature * norm_pr) * cap * 0.01;

    // Smooth interaction: residual vs mean residual coupling
    let mean_gap = (pr - mean_residual) / cap;
    score += 2.0 * mean_gap * mean_gap * cap * 0.01;

    // Last-chance bonus: strongly reward using a lone fitting bin
    if fitting_bins_count == 1 {
        score -= 1.0 + 3.0 * (1.0 - norm_pr);
    }

    // Lookahead: penalize if post residual can't fit next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let tight = (nxt / cap - norm_pr).abs();
        score += (1.0 - fits_next) * (1.0 + norm_pr * 3.0);
        score -= fits_next * 0.5 * (1.0 - tight);
    }

    // Penalize opening new bins when many open bins could fit
    if bin_residual == bin_capacity {
        score += 2.0 + 0.5 * open_bins_count as f64 + 2.0 * progress;
    } else {
        score -= 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // ---- Harmonic class of the leftover space (mod-20 bands on post_residual) ----
    let harmonic = post_residual % 20;
    // Leftovers in [1..5] are near-dead space: penalize; [0] perfect: big reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if harmonic >= 1 && harmonic <= 5 {
        score += 12.0 * (6.0 - harmonic as f64);
    } else if harmonic >= 6 && harmonic <= 12 {
        // mid-band leftover: mildly awkward
        score += 3.0;
    }

    // Fractional fill ratio: reward high utilization of this bin
    let fill = 1.0 - post / cap;
    score -= 25.0 * fill * fill;

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item chains into this bin: strong reward, scaled by chain tightness
            let chain_tight = 1.0 - (post - nxt) / cap;
            score -= 18.0 + 10.0 * chain_tight;
            // harmonic match: next item divides leftover into a clean class
            if (post_residual - next_item_size) % 20 == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: if leftover is small, dead space is acceptable
            if post_residual < next_item_size && post_residual <= 10 {
                score += 4.0;
            }
        }
    } else {
        // last item: perfect fit is free
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // ---- Pressure from the fleet: many open bins -> consolidate, avoid sprawl ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 {
        score += 2.0 * (open_bins_count as f64).ln() * (0.5 + progress);
    }
    // Prefer bins whose residual is below the fleet mean (tighten the loosest useful bin)
    if post < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        // Default: opening a bin is expensive
        let mut nb = 45.0 + 10.0 * progress;
        // But if this bin is the only fitting option, opening is mandatory/cheap
        if fitting_bins_count <= 1 {
            nb -= 100.0;
        }
        // If the item perfectly halves capacity (harmonic class 50), new bin is attractive
        if item_size * 2 == bin_capacity {
            nb -= 20.0;
        }
        // Late in stream with large mean residual, reuse instead of opening
        if mean_residual > item_size as f64 * 1.5 {
            nb += 15.0;
        }
        score = nb.max(0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residual that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item.
        score += 10.0;
    }

    // Open-bins pressure: discourage spreading across many bins,
    // but keep pressure mild so tight fits still win.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
    }

    // Slight preference for bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.14;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 0.10 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened when many items remain.
        let horizon = (step_index as f64 / total_items.max(1) as f64).max(0.0).min(1.0);
        score += 55.0 - 25.0 * horizon;
        // If no open bin fits well, opening a new bin becomes relatively better.
        if post_residual as f64 > mean_residual {
            score -= 8.0;
        }
    } else {
        // Slight preference for bins below the mean residual (consolidate waste).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        } else {
            score -= 2.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score -= progress_weight * (cap - post) * 0.01;

    // Polynomial penalty on wasted residual, scaled by mean residual context.
    let dead = post_norm * post_norm;
    score += 40.0 * dead * (1.0 - progress) * (mean_residual / cap).abs();

    // Scarcity bonus: last fitting bin gets strong smooth reward.
    let scarcity = 1.0 / (fit * fit);
    score -= 30.0 * scarcity * (1.0 - post_norm);

    // Lookahead: reward if next item fits into post residual (smooth quadratic).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (post - nxt).max(0.0);
        let fit_quality = 1.0 - (post - nxt).abs() / cap;
        score -= 20.0 * fit_quality * fits / cap;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.5 * open * post_norm * (1.0 - progress);

    // Slight preference for keeping residual near multiples of typical sizes:
    // smooth sinusoidal-free polynomial bump around small residuals.
    score += 10.0 * (post_norm - 0.25) * (post_norm - 0.25);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Reward tight fits (small post_residual), especially exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= tenth {
        score -= 35.0;
    } else if post_residual <= quarter {
        score -= 18.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 6.0;
    } else {
        score += 10.0; // large leftover: dead space penalty
    }

    // Modulo-10 harmonic class of post_residual: multiples of 10 are "usable slots".
    let pr_mod = post_residual % 10;
    if pr_mod == 0 && post_residual > 0 {
        score -= 8.0; // clean slot likely to fit future items exactly
    } else {
        score += pr_mod as f64 * 0.7; // ragged remainders are less reusable
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item won't fit here: penalize small post_residuals (waste)
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
        // Harmonic pairing: next_item divisible-by-10 classes
        let n_class = next_item_size / 10;
        let p_class = post_residual / 10;
        if n_class == p_class && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are large
    // (fragmented state) — otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.35 {
            score -= 15.0 * (0.35 - fragmentation) * 10.0;
        } else {
            score += 12.0 + fragmentation * 20.0;
        }
        // late in stream, keep open bin count manageable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += open_bins_count as f64 * 0.4 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance avoidance of extremes).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Integer-division threshold: post_residual in (quarter, half) is a "half-class" slot,
    // decent; in (half, 3/4) is poor.
    if post_residual > bin_capacity / 2 && post_residual <= 3 * quarter {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score = 100.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but add penalty for tiny dead space
    // that is likely unusable (< smallest plausible item, say 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: worse than a slightly looser but usable fit
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / 100.0).max(0.0); // exact match strongly rewarded
        // Perfect chain: this bin will be exactly filled by the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // If next item cannot fit anywhere else, keep room for it
        if next_item_size <= post_residual && next_item_size > bin_residual {
            score -= 15.0;
        }
        // Penalize leaving residual that is just barely too small for next item
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good fits)
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless current bins are nearly full
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fullness > 0.7 {
            score -= 10.0; // fine to open a fresh bin when others are mostly full
        } else {
            score += 35.0; // discourage wasting a fresh bin
        }
    }

    // Late in the stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward dead space that can only hold tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 10.0 + 8.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty if we waste residual.
        score += 2.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bonus: only one bin can fit the item; strongly prefer it over opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item (poor fits everywhere).
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - item_size as f64;
        if avg_waste > 0.0 {
            // Existing bins would waste a lot; new bin is reasonable.
            score -= avg_waste * 0.6;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // Many open bins already: discourage another.
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    // Prefer bins below mean residual (keeps residual distribution balanced,
    // preserving mid-size gaps for future items).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Slight preference for fuller bins early (best-fit bias), stronger as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / bin_capacity as f64) * (2.0 + 4.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (penalize large post_residual quadratically);
    // later, dead space matters more, so the penalty grows smoothly.
    let post_norm = post / cap;
    let poly = post_norm * post_norm * (1.0 + 3.0 * progress) + post_norm * (1.0 - progress);
    score += 60.0 * poly;

    // Reward filling the bin well: smooth reward on utilization ratio.
    let util = item / cap;
    score -= 40.0 * util * util * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Next-item lookahead: reward leaving space that fits the next item,
    // penalize residual that is too small to be useful (dead space).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= 15.0 * (next / cap) * (1.0 - post_norm);
        } else {
            score += 12.0 * (1.0 - post / cap) * (next / cap);
        }
    }

    // Mild penalty when bin residual deviates far from mean residual,
    // encouraging balanced residual distribution (smooth, non-linear).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a bin unless current bin is very full,
    // with the penalty easing as the stream progresses.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) * (1.0 - item / cap) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are gold
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Dead-space classes: residuals below the minimum item size are worthless
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual <= 25 {
            score += 15.0; // hard to fill
        } else if post_residual <= 50 {
            score -= 5.0;
        } else {
            score -= 20.0; // roomy remainder, still useful
        }

        // Modulo-10 harmonic class: residuals that are multiples of 10 pair
        // naturally with typical item granularities
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does this bin remain usable for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or with small slack -> reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 0.3 * slack;
            if post_residual == next_item_size {
                score -= 40.0; // chain of perfect fits
            }
        } else if next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            // big item coming; keeping a large residual open elsewhere matters
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only when all open
    // bins would leave bad residuals and mean residual is already low
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_open = (mean_residual < 25.0) as i32 as f64;
        score = 55.0 - bad_open * 30.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0; // fresh bin can host the big next item
        }
    }

    // Mild preference for tighter (already partially filled) bins
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space avoidance: residuals too small for typical items are wasted.
    // Penalize small unusable gaps super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward bins whose residual can still fit the next item (lookahead synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + next_item_size as f64 * 0.15;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 30.0 + open_bins_count as f64 * 6.0;
        // If only one bin fits and it's tight, opening a bin is less bad.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        // Mild bonus for filling existing bins as stream progresses.
        score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // If post_residual is too small for the next item, it's dead space -> penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward leaving residual near mean (keeps bins balanced) mildly.
    score -= 0.2 * (post_residual as f64 - mean_residual).abs().signum() * -1.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 5.0;
        // If the current item leaves a huge residual anyway, opening new bin is fine.
        if post_residual >= 60 {
            score -= 10.0;
        }
    }

    // Late in stream, tighten packing: prioritize tight fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically: small post_residuals are good.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward tight fits, especially when this is the last fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1.0 {
            score -= 30.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving awkward small gaps.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < nr {
                score += (nr - gap) * 0.5;
            }
        }
    }

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, allow more aggressive new-bin opening for better packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount later.
        let new_bin_penalty = 40.0 * (1.0 - 0.5 * progress);
        score += new_bin_penalty;
        // Opening a new bin is more attractive when many bins are open and mean residual is low.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        score += mean_residual * 0.3;
    } else {
        // Existing bin: reward when its residual is below the mean (tight bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Reward filling bins that are already mostly full.
        let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= fullness * 10.0;
    }

    // Small global-load coupling: many open bins -> prefer reusing existing bins.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth polynomial couplings with progress
    let x = post / cap;                       // 0..1 fraction of space left after placement
    let x2 = x * x;
    let x3 = x2 * x;

    // Base: waste minimization, but late in the stream small residuals matter less
    let mut score = post as f64 * (1.0 - 0.35 * progress);

    // Non-linear polynomial coupling: penalize medium dead space, reward very tight fits
    // Smooth valley around x ~ 0.15 (sweet spot residual)
    let sweet = (x - 0.15) * (x - 0.15);
    score += 180.0 * sweet * (0.6 + 0.4 * progress);

    // Cubic term: strongly punish large leftover space early, less late
    score += 60.0 * x3 * (1.0 - 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, reward using it strongly
    if fitting_bins_count == 1 {
        score -= 120.0 + 80.0 * (1.0 - x);
    }

    // Lookahead coupling: does the next item still fit in the post-residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            // Next item fits: reward proportionally to how well it uses remaining space
            let usage = nx / post.max(1.0);
            score -= 40.0 * usage * (1.0 - progress * 0.5);
        } else {
            // Next item won't fit: penalize based on how much dead space is stranded
            score += 50.0 * (1.0 - nx / cap) * (1.0 - progress * 0.3);
        }
    }

    // Spread-aware term: prefer bins whose residual deviates smoothly from the mean
    let dev = (post - mean_residual) / cap;
    score += 25.0 * dev * dev;

    // New-bin candidate: empty bin gets a mild handicap that shrinks with progress
    // and with how poor the best fit would be (many fitting bins => prefer existing bins)
    if bin_residual == bin_capacity {
        let crowd = (fitting_bins_count as f64).ln().max(0.0);
        score = cap as f64 * (1.05 - 0.25 * progress) + 30.0 * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space avoidance).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic class of post_residual: small residue classes modulo capacity
    // fractions signal future usable gaps.
    let cap_quarter = bin_capacity / 4;
    let cap_half = bin_capacity / 2;
    let pr = post_residual;
    if pr % cap_quarter == 0 && pr > 0 {
        score -= 8.0; // gap aligns with quarter-capacity classes
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0; // decadal class gaps are reusable
    }
    // Penalize awkward mid-range gaps (just above half, awkward classes)
    if pr > cap_half && pr < cap_half + 10 {
        score += 10.0;
    }

    // Lookahead: reward if next item fits exactly into the post-residual class.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits; the tighter, the better
            score -= (pr - next_item_size) as f64 * 0.6;
        } else {
            // next item cannot use this bin's gap; penalize proportional waste
            score += (next_item_size - pr).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge
    // relative to capacity or many bins are open and mean residual is tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 45.0;
        if item_size >= cap_half {
            penalty -= 20.0; // big items deserve fresh space
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            penalty -= 10.0; // pairing impossible anyway
        }
        if open_bins_count > 8 && mean_residual < 15.0 {
            penalty -= 15.0; // all open bins nearly full
        }
        penalty *= 0.5 + 0.5 * (1.0 - progress);
        score += penalty;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a plausible item are heavily penalized dead space.
    // Items range 1..100; a gap below ~10 is nearly unusable, gaps below
    // the next item's size are unusable for the lookahead horizon.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }
        // Gap unusable by the next item: dead space for this horizon step.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward gaps that exactly accommodate the next item (perfect chaining).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Perfect closure of the bin is ideal.
        score -= 20.0;
    }

    // Reward tightness relative to the item placed (ratio coupling).
    score += 0.3 * (item_size as f64 / bin_capacity as f64) * (post_residual as f64);

    // Open-bin pressure: discourage spreading across many bins when
    // open_bins_count grows; encourage consolidating into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Coupling with mean residual: if this bin's post-fit residual deviates
    // far below the mean, we are creating fragmented small gaps -> penalize.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.08 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when the current item is
    // large (would leave little dead space anyway) or no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening new bins by default.
        score += 35.0;
        // But a fresh bin is good for large items leaving a useful remainder.
        if post_residual >= 20 {
            score -= 10.0;
        }
        // If the next item is huge and current item leaves an awkward gap,
        // a fresh bin chains better: reward when post_residual >= next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Early in the stream, allow more liberal bin opening.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space quadratically.
    let post = post_residual as f64;
    score += 0.35 * post * post / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post - nx).abs();
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            // next item can still fit here after this placement
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize if the
            // leftover dead space is small-but-unusable
            if post_residual < 10 {
                score -= 5.0; // tiny dead space is fine
            } else {
                score += 0.5 * (post - nx) / 10.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins that bring residual
    // closer to the mean residual across open bins (load balancing),
    // unless a tight fit exists (tight fit overrides balancing).
    let mean = mean_residual;
    if mean > 0.0 {
        let balance = (post - mean).abs();
        score += 0.15 * balance;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits
    // well; penalize slightly so existing bins are preferred by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items
        // to distribute), so soften the penalty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Slight preference for using more-occupied bins when many bins open.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64) / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small post_residual that can never host typical items is bad,
    // but a post_residual that exactly fits the lookahead item is excellent.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead fits exactly into the leftover space: big bonus.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // Leftover too small for the next item: penalize proportionally to wasted space.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 15.0 * (1.0 - waste / 10.0);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins; few bins -> new bin is cheaper.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let consolidation_bonus = mean_residual / cap * (open_bins_count as f64).ln().max(1.0);
    score -= 5.0 * consolidation_bonus * (0.5 + progress);

    // New-bin candidate handling: an empty bin scores moderately; it should win
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream (sunk bins matter less).
        score += 45.0 - 15.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If mean residual is high, existing bins have room; discourage a new bin.
        score += 10.0 * (mean_residual / cap);
    } else {
        // Existing-bin mild preference to keep bin count down.
        score -= 3.0;
        // Penalize leaving huge residuals in a bin when other bins could take the item
        // (encourage spreading load evenly across open bins).
        if post_residual as f64 > mean_residual * 1.5 {
            score += 4.0;
        }
    }

    // Late-stream tightening: as the stream ends, squeeze residual space harder.
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: quadratic penalty on post-residual (dead space), smoothed.
    let mut score = pr * pr / c;

    // Smooth non-linear coupling: dead space hurts more as the stream progresses.
    score += pr * (0.5 + progress) * (pr / c);

    // Reward tight fits (small post_residual) more strongly later in the stream.
    let tightness = 1.0 - pr / c;
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 10.0;

    // Cubic interaction: penalize mid-range leftover space (unusable gaps)
    // with a bump centered around pr = c/3, growing with progress.
    let x = pr / c;
    score += 15.0 * progress * (x - 1.0/3.0) * (x - 1.0/3.0) * (x - 1.0/3.0).abs().sqrt().min(1.0) * 4.0 * (1.0 - x);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into resulting post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - (pr - nx) / c) * (0.5 + progress);
        } else {
            // Penalize post-residuals that waste space relative to next item.
            score += 5.0 * progress * (nx - pr) / c;
        }
    }

    // Mild global pressure: when many bins are open, prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / c) * 2.0;

    // Deviation from mean residual: prefer bins that bring residuals toward balance.
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "usable" classes (divisible by common small item sizes) are preferred.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill
    } else if pr <= 10 {
        20.0 // dead space: unusable for min-size items
    } else if pr % 10 == 0 {
        -25.0 // harmonic class: exactly fits small items
    } else if pr % 5 == 0 {
        -15.0
    } else if pr <= 20 {
        10.0
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold on post_residual vs next item lookahead.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strong reward, scaled by tightness.
            score -= 18.0 + 0.35 * (next_item_size as f64);
            if next_item_size == pr {
                score -= 25.0; // chain-perfect fit
            }
        } else {
            // Post residual cannot host next item: penalize wasted capacity.
            let waste = (pr - next_item_size.min(pr)) as f64;
            score += 0.08 * waste;
        }
    }

    // Last-chance bin: strongly prefer to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if item is large and no tight fit exists, opening is fine.
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Tight-fit reward: small post residual relative to item size.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (pr as f64 / 100.0);

    // Prefer bins below mean residual (keeps spread tight, large gaps free).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Many open bins: reward using emptier ones, penalize fragmentation.
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64) * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are pure waste -> heavy penalty.
    if post_residual > 0 {
        let min_useful = 1u32; // any positive residual can technically fit an item
        if post_residual < min_useful + 9 {
            // Very small gap (1..=9): almost certainly dead space.
            score += 120.0;
        } else if post_residual < 20 {
            // Gap too small for most items (sizes >= 10 typically).
            score += 60.0;
        } else if post_residual < 30 {
            score += 15.0;
        }
    }

    // Reward tight fits: small post_residual relative to capacity is good,
    // but only when it's not a dead gap (already penalized above).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins harder (especially new-bin candidate).
    let pressure = (open_bins_count as f64) * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += pressure;
        // But if next item would fit better in a fresh bin, soften slightly.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving a gap
        // that blocks the lookahead item.
        score += 8.0;
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // (i.e., consuming a large bin) is slightly favored when mean residual is high.
    score += 0.3 * (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Core: reward exact 2-step lookahead match — post_residual ≈ next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        // Perfect match: next item exactly fills this bin afterwards
        if gap < 0.5 {
            score -= 60.0;
        } else {
            // Reward closeness, penalize overshoot (dead space) more than undershoot
            if post >= nxt {
                score += gap * 0.9;      // dead space after two placements
            } else {
                score += gap * 0.35;     // next item won't fit here either
            }
        }
        // If next item can't fit anywhere else, prefer keeping a big-enough residual
        if post < nxt && nxt <= bin_residual as f64 {
            score += 12.0;
        }
    } else {
        // Last item: minimize leftover directly
        score += post * 0.5;
    }

    // Dead-space penalty: very small unusable remainders
    if post > 0 && post < 10.0 {
        score += 25.0;
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when item fits poorly elsewhere
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        if next_item_size > 0 && (next_item_size as f64) >= item_size as f64 {
            score -= 10.0; // fresh bin handles the sequence of large items well
        }
    }

    // Prefer fuller bins relative to fleet mean residual
    score -= (mean_residual - post) * 0.4;

    // Slight preference to consolidate early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0 + post_residual as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can host the next item too.
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened casually.
        score += 60.0 + open_bins_count as f64 * 5.0;
        // If the item is large and likely to fit poorly elsewhere, allow opening.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 20.0;
        }
    }

    // Favor bins with residual far below mean (consolidate waste).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Time-horizon coupling: later in the stream, prefer using existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Penalize very small residuals that are likely wasted anyway.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear penalty on post_residual: wasted space grows super-linearly
    let x = post / cap;
    score += 12.0 * x * x * (1.0 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Lookahead coupling: if the next item can use the post residual, reward leaving it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // smooth reward proportional to how well next item fills leftover
            let fill = nxt / post.max(1.0);
            score -= 10.0 * fill * (1.0 - fill) * 4.0 + 5.0 * fill;
        } else {
            // leftover too small for next item: penalize dead space smoothly
            let dead = (post / nxt).min(1.0);
            score += 6.0 * dead * dead;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild penalty spread over many candidates
        score += 2.0 * ((fitting_bins_count as f64 - 1.0).ln() + 1.0);
    }

    // Prefer bins with below-average residual (concentrate waste in few bins)
    score += 0.05 * (post - mean_residual);

    // New-bin candidate: penalize opening a bin unless current bin would leave unusable space
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 20.0 - 8.0 * urgency - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "awkward" classes modulo common item sizes.
    let pr = post_residual;
    let mut dead_penalty = 0.0;
    for m in [3u32, 5, 7, 10, 20, 25, 50].iter() {
        let r = pr % m;
        // residual exactly divisible by a common class => reusable
        if r == 0 && pr > 0 {
            dead_penalty -= 4.0;
        } else if pr < *m {
            dead_penalty += 2.0;
        }
    }
    score += dead_penalty / 7.0;

    // Perfect fit is ideal
    if pr == 0 {
        score -= 100.0;
    }

    // Fraction-of-capacity classes for post residual
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.1 && pr > 0 {
        score += 25.0; // tiny unusable sliver
    } else if frac < 0.2 {
        score += 8.0;
    } else if frac < 0.35 {
        score += 2.0;
    } else if frac >= 0.5 {
        score -= 6.0; // large residual remains useful
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // harmonic match: post_residual / next_item_size integer division
            if pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        // neutral baseline relative to mean residual
        score = bin_capacity as f64 * 0.5 + (mean_residual - (bin_capacity - item_size) as f64).abs();
        if item_size >= bin_capacity * 3 / 4 {
            score -= 10.0; // big items fine in fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, be pickier about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (pr as f64) * 0.15;

    // Many open bins: prefer consolidating into fuller bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 45.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 18.0 * (20.0 - post_residual as f64) / 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward leaving space that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 20.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.35;

    // New-bin candidate: neutral-ish base, only wins when open bins would waste space.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 25.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count > 0 {
            // Only open a new bin if existing fits would leave bad dead space.
            if post_residual_of(item_size, bin_capacity) <= 12 {
                score += 70.0;
            }
        }
    }

    score
}

#[inline]
fn post_residual_of(item_size: u32, capacity: u32) -> u32 {
    capacity.saturating_sub(item_size)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item fits into resulting residual (soft lookahead reward, scaled by closeness)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.4;
    } else if next_item_size > 0 {
        // next item won't fit here afterwards: penalize wasted potential
        score += 10.0;
    }

    // Penalize dead space relative to smallest plausible item (items >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer bins with below-average residual (tighter bins fill first)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // discourage opening new bins early in stream or when other bins exist and fit
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 25.0 + 50.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        } else {
            score -= 5.0;
        }
    }

    // Mild pressure to keep number of open bins bounded
    score += open_bins_count as f64 * 0.5;

    // Prefer filling larger fraction of the bin now
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
