pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual, but non-linearly (dead space hurts quadratically).
    let mut score = post + 0.9 * (post * post) / cap;

    // Reward tight fits (small post_residual relative to item) with smooth coupling.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Stream-progress coupling: early on, keep flexibility (penalize low residual bins less);
    // late in stream, squeeze bins hard and prefer opening new bins for good fits.
    let flexibility = (bin_residual as f64) / cap;
    score += 8.0 * progress * (1.0 - flexibility).powi(3);

    // Lookahead: reward bins whose post residual can fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - 4.0 * slack).max(0.0) * (1.0 + progress);
        } else {
            // Penalize post residuals that can't fit the next item, scaled by gap.
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to spread load toward best fits.
        score += 1.5 * (fitting_bins_count as f64).ln() * (1.0 - progress);
    }

    // Mean-residual coupling: bins far below mean residual are "fresher"; using them
    // keeps old nearly-full bins consolidated. Smooth interaction with progress.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 5.0 * dev * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bin attractive only when current bins fit poorly
    // (large post_residual) or late in stream with big items.
    if bin_residual == bin_capacity {
        score = 30.0 + post - 10.0 * tightness - 20.0 * progress * (item / cap);
        if next_item_size > 0 && (next_item_size as f64) <= cap - item {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that cannot hold
    // typical small items is worthless. Classify via integer division.
    let class = post_residual / 10;
    match class {
        0 => score -= 30.0,          // near-perfect fit (0-9 dead)
        1 => score += 10.0,          // 10-19: awkward sliver
        2 => score -= 5.0,           // 20-29: usable for small items
        3 => score += 3.0,           // 30-39: mediocre
        4 => score -= 8.0,           // 40-49: good chunk left
        5 => score += 2.0,           // 50-59
        _ => score += 5.0,           // 60+: wasteful placement
    }

    // Reward tight fits proportionally within the best class.
    if post_residual < 10 {
        score -= (10 - post_residual) as f64 * 2.0;
    }

    // Lookahead coupling: prefer bins whose leftover matches the next
    // item's harmonic class (next_item_size / 10 buckets).
    if next_item_size > 0 {
        let next_class = (next_item_size as f64 / 10.0).floor();
        let post_class = class as f64;
        let harmony = (post_class - next_class).abs();
        score -= (10.0 - harmony.min(10.0)) * 3.0;
        // Exact harmonic match is a strong bonus.
        if (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening fresh bins unless the item is
    // huge relative to open-bin residuals.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).max(1.0);
        score += 15.0 + pressure * 0.5;
        if item_size >= 70 {
            score -= 30.0; // big items start fresh bins cheaply
        }
    } else {
        // Prefer denser bins (less residual than average).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Stream progression: early on, keep bins open and flexible;
    // later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Small penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
