        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            // Placing next item here would create dead space; discourage.
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bins pressure: penalize bins when many bins are open, encouraging
    // consolidation into fewer bins; but relax pressure late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 - progress) * 0.5;

    // Prefer bins below mean residual (fill emptier bins first to consolidate).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make empty bin moderately attractive only when the item
    // is large relative to typical residuals or no good fit exists.
    if bin_residual == bin_capacity {
        if item_size > 50 && fitting_bins_count <= 1 {
            score -= 20.0;
        } else {
