        // Prefer opening new bins early-to-mid stream when open bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else { 0.0 };
        score += base_penalty + scarcity_bonus
            - 15.0 * crowding
            - 10.0 * (1.0 - progress);
    }

    // Dead-space penalty: residuals that only tiny items can use are wasteful
    // when the next item is larger than the residual.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            let waste = (next_item_size as f64 - post_residual as f64).min(50.0);
            score += 0.15 * waste;
        } else {
            // Next item fits here too: reward chaining.
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is already below average (consolidating space).
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // Mild preference for bins with larger residual when item is small
    // (save tight bins for tight occasions).
    score += 0.02 * (bin_residual as f64) * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight packing).
    let mut score = post;

    // Non-linear reward for tight fits: quadratic in normalized fill.
    let fill = 1.0 - post / cap;
    score -= 30.0 * fill * fill;

    // Smooth stream-progress coupling: later in the stream, reward tight fits more strongly.
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 20.0 * progress_coupling * fill;

    // Penalize dead space: post_residual too small to ever fit typical items.
    // Smooth penalty growing as post drops below the smallest useful gap (item sizes >= 1..100).
    let min_item = 1.0;
    if post < min_item {
        score -= 0.0; // perfect fit, handled above
    }

    // Lookahead: reward if next item fits into post_residual (smooth, graded by slack).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Penalize leaving a gap that blocks the next item, scaled by how badly it misses.
            let miss = (nxt - post) / cap;
            score += 10.0 * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins already below mean residual (balance load) with smooth coupling.
    score += 0.1 * (post - mean_residual).abs() - 0.05 * (post - mean_residual);

    // New-bin candidate: penalize mildly so it's chosen only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress_coupling;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic classes: residual space bucketed by divisibility classes.
    // Residuals that are multiples of common item sizes are more reusable.
    let res = post_residual;
    if res > 0 {
        let reusable = (res % 10 == 0) || (res % 20 == 0) || (res % 25 == 0) || (res % 50 == 0);
        if reusable {
            score -= 12.0; // residue likely usable by future items
        } else {
            score += 4.0;  // awkward residue (dead space risk)
        }
        // Penalize very small unusable slivers (1..5) less than mid-range waste
        if res >= 1 && res <= 9 && res % 10 != 0 {
            score -= 6.0; // tiny sliver, nearly full bin, acceptable
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the current best
    // fit would leave a large awkward gap and mean residual is already high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward_waste = (mean_residual - item_size as f64).max(0.0);
        // Penalize new bins generally, more early when consolidation is cheap.
        let mut new_bin_penalty = 25.0 + 20.0 * (1.0 - progress);
        // But if every open bin would leave big dead space, allow opening.
        if awkward_waste > 30.0 && fitting_bins_count >= 1 {
            new_bin_penalty -= 35.0;
        }
        // If next item is large, keep mean residual high (hoard space).
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty.max(-5.0);
    }

    // Lookahead coupling: if this placement leaves room exactly (or nearly)
    // matching the next item, reward it (harmonic alignment).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residue smaller than next item is likely dead space unless tiny
        if post_residual > 10 {
            score += 6.0;
        }
    }

    // Mild pressure to prefer filling bins with larger residuals when many bins open.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Reward filling a bin whose residual closely matches the item
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Open-bins pressure: penalize spreading across many open bins
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for the next item: penalize
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are numerous
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        score += 15.0 + 10.0 * pressure;
    }

    // Mild late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Near-perfect fit (small dead space)
    if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // next item fits here too; reward closeness of match
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover space; penalize dead space
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins tighter than the current mean residual
    if bin_residual < bin_capacity {
        let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 20.0 * tightness;
    }

    // Early stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize so it only wins on poor fits elsewhere
        score += 100.0 + 60.0 * (1.0 - progress);
    }

    // Reward placing large items into tighter bins
    score -= 10.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used as a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a mild convexity
    // so that very small slivers are disproportionately attractive.
    score = post_residual as f64 + 0.35 * (post_residual as f64).sqrt();

    // Penalize wasted space relative to the mean residual of open bins:
    // a placement that leaves much more room than average is a poor fit.
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this placement (perfect chain). If the next item would
    // be blocked by post_residual but could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // dead space for the next item: penalize proportional to the gap
            score += 0.30 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when the item fits poorly in all
        // existing bins (large post_residual everywhere) or few alternatives.
        // Base cost of opening a bin, discounted as the stream progresses
        // (late in the stream, consolidation matters more).
        score = 55.0 + 45.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            // A fresh bin can host the next item too: soften slightly.
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            // No open bin can host the item at all: new bin is mandatory.
            score -= 100.0;
        }
    }

    // Crowd control: with many open bins, encourage filling existing ones
    // (subtract slightly), keeping fragmentation in check.
    score -= (open_bins_count as f64).ln() * 1.5;

    // Small global tightness nudge: if mean residual is low overall,
    // value every remaining unit of space more.
    score += 0.10 * (mean_residual / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let item = item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let poly = norm_post * norm_post * (1.0 - p) + norm_post * p * p;
    score += 40.0 * poly;

    // Tight fits rewarded more as stream advances (smooth interaction)
    score -= 25.0 * (1.0 - norm_post) * (0.3 + 0.7 * p);

    // Penalize dead space relative to mean residual (non-linear)
    let dead = (post - mean_residual) / cap;
    score += 15.0 * dead * dead.abs();

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 * (next_item_size as f64 / cap) * (1.0 - p);
    } else if next_item_size > 0 {
        score += 8.0 * p;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post) * (0.5 + 0.5 * p);
    }

    // Mild pressure to consolidate when many bins are open
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Prefer larger items into this bin early
    score -= 5.0 * item * (1.0 - p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: residual in tiny dead zone (1..=5) -> nearly perfect, mild reward.
    else if post_residual <= 5 {
        score -= 40.0;
    }
    // Class C: residual that common small items (<=10) can still fill.
    else if post_residual <= 10 {
        score -= 25.0;
    }
    // Class D: residual in "harmonic dead band" (11..=19): too small for most
    // items (min size 1..100 unknown, but small items <= 10 or > 19 typical),
    // penalize moderately to avoid creating unusable slivers.
    else if post_residual <= 19 {
        score += 15.0;
    }
    // Class E: quarter-band residuals are reusable by mid items.
    else if post_residual <= 25 {
        score -= 8.0;
    }
    // Class F: half-capacity residual: excellent landing zone.
    else if post_residual <= 50 {
        score -= 12.0;
    }
    // Class G: large leftover: bin was mostly empty; neutral-to-slight penalty
    // so we prefer filling existing emptier bins first via best-fit on pr.
    else {
        score += 5.0;
    }

    // Modulo arithmetic on residual: residuals that are multiples of 10
    // align with the classic size grid and tend to tile well.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    // Odd slivers (residual % 2 == 1) tile worse with even items.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Lookahead harmony: if the next item fits exactly into the post residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 12.0;
            } else if gap <= 20 {
                score -= 4.0;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // Next item cannot use the leftover: leftover likely dead space.
            score += (post_residual as f64).min(30.0) * 0.2;
        }
    } else {
        // Last item: any residual is wasted; prefer exact fill.
        score += pr * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Opening a new bin is acceptable when many bins are open and mean
    // residual is low (fragmented state); make new bin slightly attractive
    // then, otherwise keep it expensive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 120.0 - 40.0 * progress - (mean_residual / cap).min(1.0) * 30.0;
    if bin_residual == bin_capacity {
        score = new_bin_penalty;
    }

    // Slight tie-break toward denser bin sets: prefer bins below mean residual
    // (fill the emptier ones first when residuals are comparable).
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness * tightness;
    }

    // If the next item fits exactly into the post-residual, big reward (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover: penalize proportionally.
        score += 0.15 * post_residual as f64;
    } else if next_item_size > 0 {
        // Next item fits in the gap: mild reward.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: when many bins are open,
    // prefer filling existing ones over spreading out.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean residual (fill the fullest bins first).
    let mean_res = mean_residual;
    if (bin_residual as f64) < mean_res {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New empty bin candidate: only attractive when it produces a perfect fit
    // (item_size == capacity) or when existing bins would leave very bad dead space.
    if bin_residual == bin_capacity {
        score += 35.0; // default: discourage opening new bins
        if post_residual == 0 {
            score -= 200.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 500.0 - slack * 3.0;
        } else {
            // Next item cannot use post residual: penalize small dead space.
            let waste = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 120.0; // tiny unusable sliver
            } else if waste <= 10.0 {
                score += 40.0;
            }
        }
    }

    // Compare post residual against mean residual across open bins.
    // Prefer bins whose post residual deviates toward zero (tight packing).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Brand-new empty bin candidate: penalize moderately so good existing fits win,
    // but keep it attractive when all fits are poor (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        score += 60.0 + (item_size as f64) * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Slight preference for bins with larger residuals used efficiently.
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // Mid-range leftover is only useful if the lookahead item can use it.
        if next_item_size > 0 && next_item_size as u32 <= post_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    } else {
        // Large leftover: reward if next item fits it exactly-ish.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 10 {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is attractive only early in the stream
    // or when the current bin would be left with awkward residue.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early: opening bins is cheap and gives flexibility.
        // Late: prefer filling existing bins, penalize new bins.
        score += 8.0 * progress;
        // If the current bin would be left with a nicely reusable residue, penalize new bin.
        if post_residual >= 20 || post_residual == 0 {
            score += 5.0;
        }
        // Many open bins with slack: avoid adding more.
        if open_bins_count as f64 > mean_residual / 10.0 {
            score += 4.0;
        }
    }

    // Global slack pressure: when mean residual is high, prefer placements that
    // consolidate (reduce mean residual fastest, i.e., smallest post_residual).
    score += 0.05 * mean_residual * (1.0 - fit_ratio);

    // Lookahead coupling: penalize placements that leave a residue the next item
    // almost fits but not quite (wasted opportunity).
    if next_item_size > 0 && post_residual > 0 && next_item_size as u32 > post_residual
        && next_item_size as u32 - post_residual <= 8 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 40.0 * pr_norm * pr_norm + 60.0 * pr_norm * pr_norm * pr_norm;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fits; late, strongly avoid wasted space
    let progress_coupling = (0.5 - progress) * (1.0 - progress) * pr_norm * 120.0;
    score += progress_coupling;

    // Perfect-fit reward (smooth bump via squared term)
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits remaining space (smooth quadratic overlap)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = pr - next_item_size as f64;
        score -= 10.0 * (1.0 - gap / cap).abs();
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong bonus when only this bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize opening new bins when good open bins exist (smooth in open count)
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64).sqrt() + 10.0 * (1.0 - progress);
        // but allow new bin if item is large relative to mean residual
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    }

    // Mild preference for bins below mean residual (consolidation)
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items of size <= 10 form "dead" class
    let dead = post_residual < 10;
    if dead {
        score -= 500.0; // filling to near-full is great
    }

    // Class bins by residual fraction (harmonic classes of capacity)
    let frac = post_residual as f64 / bin_capacity as f64;
    // penalize residuals in awkward mid-range classes (0.2..0.5)
    if frac > 0.2 && frac < 0.5 {
        score += 25.0 * (0.5 - frac);
    }

    // Lookahead: can next item fit in post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // perfect chain bonus
        if next_item_size == post_residual {
            score -= 200.0;
        } else {
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 {
        // next item won't fit here after placement; penalize proportional to waste
        score += 15.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 400.0 } else {
            60.0 + 30.0 * (open_bins_count as f64).ln().max(0.0)
                - 80.0 * (item_size as f64 / bin_capacity as f64)
        };
        score += pressure;
    }

    // Prefer bins tighter than the mean residual (good packing)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Late in stream, be greedier about filling
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful
    // (below the minimum plausible item size band) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Moderate dead space: scaled penalty, tighter fits favored.
        score += 0.6 * (25.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward using bins that would otherwise waste space (tight fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill * fill;

    // Pressure from number of open bins: discourage opening new bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate: make it less attractive unless existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.8 * open_bins_count as f64;
        // If mean residual is high, existing bins are fragmented -> new bin less bad.
        score -= 0.15 * mean_residual;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward keeping this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: dead space confirmed.
        score += 8.0;
    }

    // Slight preference for filling bins early in the stream (keep flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item can't fit here; penalize proportionally to wasted space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // lookahead chain: post_residual - next_item_size residual
        let post2 = post_residual as i64 - next_item_size as i64;
        if post2 > 0 && post2 < 10 {
            score -= 40.0; // near-perfect two-item packing
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 80.0;
    }

    // Compare residual against mean residual across open bins
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin bonus: only one bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize leaving small unusable fragments (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Early in stream: mild preference to open new bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, mild penalty to encourage exploring better fits.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack == 0 {
                score -= 20.0; // perfect chain fit
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state coupling: prefer using bins when many are open (reduce sprawl).
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score -= 3.0 * open_pressure.min(10.0);

    // Prefer bins with residual below the mean (consolidate small leftovers),
    // but avoid over-packing bins that are nearly full already.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Time horizon: early on, be more willing to open new bins / spread items;
    // later, be conservative and pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress); // new-bin penalty decays over time
    score -= 8.0 * progress * tightness; // tighter packing valued late

    // Brand-new bin candidate: baseline cost of opening a bin, discounted
    // when the item is large or the fit in existing bins is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = 15.0 + 0.5 * item_size as f64 - 20.0 * poor_fit - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Smooth non-linear coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * (1.0 + 2.0 * progress * norm_pr + progress * progress);

    let mut score = pr * (1.0 + poly);

    // Penalize dead space more as stream progresses (smooth exponential coupling).
    score += (norm_pr * norm_pr) * cap * progress * 0.5;

    // Reward near-perfect fits with smooth non-linear term.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * (0.5 + progress);

    // Last-chance bonus (smooth, not piecewise).
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= last_chance * 15.0 * (1.0 + progress);

    // Lookahead coupling: reward residual that still fits next item.
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= fits_next * next_item_size as f64 * 0.3 * (1.0 - progress);
    }

    // New-bin candidate: mild penalty early, decaying smoothly with progress.
    score += if is_new_bin { cap * (1.2 - progress) } else { 0.0 };

    // Mild penalty for deviating from mean residual (smooth quadratic).
    score += ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod 10 (gcd of common item sizes)
    let residue_class = post_residual % 10;
    // Dead space classes that are nearly unusable (residual < 10, or odd small residues)
    if post_residual < 10 {
        score -= 25.0; // perfect fill: excellent, reward strongly
    } else {
        // Usable leftover bonus depends on how well next item fits into the class
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight fit of the lookahead item into this bin
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else if next_item_size > 0 {
            // Next item cannot use this bin's leftover: penalize awkward residue classes
            let class_penalty = match residue_class {
                0 => -2.0,          // round leftover stays flexible
                5 => 0.0,           // half-class, neutral
                9 | 7 | 3 | 1 => 8.0, // odd/large-prime residues waste more
                _ => 4.0,
            };
            score += class_penalty;
        }
    }

    // Capacity-fraction coupling: reward bin being filled to harmonic fractions
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let frac_bonus = if fill_frac >= 0.9 { 20.0 }
        else if fill_frac >= 0.75 { 12.0 }
        else if fill_frac >= 0.5 { 6.0 }
        else if fill_frac >= 0.25 { 0.0 }
        else { -6.0 };
    score -= frac_bonus;

    // Integer-division threshold on post_residual: chunks of 10 are reusable
    let reusable_chunks = post_residual / 10;
    score -= reusable_chunks as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        let avg_badness = (mean_residual - post_residual as f64).abs();
        score += 10.0 + avg_badness * 0.3;
        // Early stream: opening bins is fine; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0 - progress * 8.0;
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Prefer tighter bins overall (below mean residual)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Slight preference for large items into large-residual bins
    score -= (item_size as f64 / 100.0) * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1 but typical items are larger), so penalize them hard.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny gap = wasted space
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 30 {
            score += 8.0;
        } else {
            // Larger residuals are still usable; give a mild bonus.
            score -= 6.0;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size (filling efficiency).
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate handling: only attractive when existing residuals
    // cannot accommodate the next item well or fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // If the next item would fit nicely into the residual this placement
        // would leave, opening a new bin is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Reusing an existing bin: reward keeping mean residual balanced
        // (prefer bins with residual close to the mean, avoiding extremes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        // Perfect match bonus (gap 0) strongly favored; decays quadratically
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).powi(2);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: dead space locked in, penalize
        score += 12.0 + 0.15 * post_residual as f64;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (well-packed bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize creating very small unusable slivers unless next item matches
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 20.0;
    }

    // New bin candidate: only attractive when no open bin is a good fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild penalty so existing bins are preferred unless they fit poorly;
        // lookahead match on the fresh bin can still win
        score += 8.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            let gap = (bin_residual as i64 - next_item_size as i64) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64).powi(2);
        }
    }

    // Early in stream: slightly favor consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // leftover likely wasted relative to next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 - bin_capacity as f64) < 1e-9;
        let threshold = 20.0 + 30.0 * (1.0 - progress);
        let best_gap = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64 // this bin is empty; gap unknown, use residual pressure
        } else {
            0.0
        };
        let _ = best_gap;
        // Base penalty for a fresh bin; relax late in stream or when many bins are open.
        score += threshold + 0.05 * open_bins_count as f64;
        if poor_fit { score += 0.0; }
        // If item is large relative to capacity, opening fresh bin is more acceptable.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Global residual pressure: if mean residual is high, prefer spreading load
    // into already-open bins rather than fragmenting.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild time decay: early on, be conservative (keep bins flexible);
    // late, squeeze harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to next item's fit
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.4 * gap * (0.5 + progress);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Deviation from mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" capacity fractions are more reusable.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize tiny dead space (< 10) — unusable for typical items
    if post_residual < 10 {
        score += 60.0;
    }

    // Reward residuals in reusable harmonic bands: (10,25], (25,50], (50,75]
    if post_residual >= 10 && post_residual <= 25 {
        score -= 25.0;
    } else if post_residual > 25 && post_residual <= 50 {
        score -= 40.0;
    } else if post_residual > 50 {
        score -= 55.0;
    }

    // Modulo arithmetic: residual divisible by common item sizes is more likely reusable
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0; // exact chain fit
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; waste penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score = 30.0 + 120.0 * (1.0 - crowding);
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Slight preference for tighter bins overall
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Nudge toward bins below mean residual (better fits)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // tiny sliver: very heavy penalty
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: small post residual relative to item size
    let item = item_size.max(min_item) as f64;
    score -= 8.0 * (item / (post_residual as f64 + item)) * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        // New-bin candidate: penalize opening a new bin unless current residuals are badly fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 + 5.0 * pressure - fragmentation.min(30.0);
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about dead space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (small post_residual), slightly superlinear.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // 2-step lookahead: reward post_residual that exactly matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match is a big bonus.
        score -= 30.0 * (-gap / 12.0).exp();
        // Penalize post_residual slightly larger than next_item_size (dead space of ~1 item).
        if post_residual >= next_item_size {
            score += 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // post_residual smaller than next item: bin becomes near-useless for lookahead.
            score += 0.20 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: only tightness matters.
        score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: placing in a below-average-residual bin is efficient compaction.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.10 * post_residual as f64;
    }

    // New-bin candidate: neutral baseline with mild penalty so it's chosen only when
    // open bins fit poorly; more attractive early in the stream.
    if bin_residual == bin_capacity {
        score = 55.0 - 25.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // opening a fresh bin would fit the pair nicely anyway
        }
    }

    // Progress-based tie-break: late in stream, squeeze harder into existing bins.
    score -= 3.0 * (step_index as f64 / total_items.max(1) as f64) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that nothing (in 1..100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let nfit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * nfit;
        } else {
            // next item won't fit here; post residual likely wasted
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * fit_ratio;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only open
    // a new bin when fits into existing bins are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If many open bins are already fragmented, opening fresh is less attractive.
        score += open_bins_count as f64 * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // But if mean residual is small (bins nearly full), new bin is fine.
        score -= (100.0 - mean_residual).max(0.0) * 0.3;
    }

    // Mildly prefer bins with below-average residual (balance fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: post_residual weighted by stream progress polynomial
    let progress_poly = 0.5 + 1.5 * progress * progress;
    score *= progress_poly;

    // Reward tight fits: quadratic penalty on normalized dead space
    score += 40.0 * norm_pr * norm_pr * cap;

    // Reward leaving room for the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        score -= 25.0 * (-fit_gap / 15.0) * (pr / nxt.max(1.0)).min(2.0);
    }

    // Last-chance bonus: only one fitting bin — favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from mean residual (smooth)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * cap;

    // Late-stream consolidation: prefer existing bins as stream ends
    score -= 20.0 * progress * (bin_residual as f64 / cap);

    // Penalize opening new bins when many are open (smooth in open_bins_count)
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // ---- Harmonic class of the post residual (integer division thresholds) ----
    // Class the leftover space into capacity fractions: quarters.
    let quarter = (bin_capacity / 4).max(1);
    let half = (bin_capacity / 2).max(1);
    let class: f64 = if post_residual == 0 {
        0.0 // perfect fit: strongly reward
    } else if post_residual < quarter {
        1.0 // tiny dead space
    } else if post_residual < half {
        2.0 // half-class leftover
    } else if post_residual < (3 * bin_capacity) / 4 {
        3.0
    } else {
        4.0 // large leftover: bin was nearly empty
    };
    score += class * 4.0;

    // Modulo-10 arithmetic on post_residual: leftovers divisible by 10 are
    // "harmonious" with typical item sizes (multiples of 10), reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0; // odd residues are hard to fill later
    }

    // ---- Lookahead coupling: does the next item fit into the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: reward proportionally.
            let chain_fit = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 8.0 * chain_fit;
            // Extra reward if the chain leaves another harmonious residue.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this leftover: penalize dead space.
            score += 5.0;
            if next_item_size > bin_residual {
                score += 4.0; // next item forces a new bin anyway
            }
        }
    } else {
        // Last item: only the immediate fit matters.
        score = pr * 1.5;
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; avoid opening a new bin unless the
        // fit is truly awful (huge leftover in a fresh bin would be worse).
        score -= 12.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new empty bin: post_residual = cap - item_size.
        // Prefer it only when the item is large relative to capacity
        // (large items leave little harmonious residue anywhere).
        let frac = item_size as f64 / cap;
        if frac > 0.7 {
            score -= 10.0; // big item: fresh bin is fine
        } else {
            score += 18.0 * (1.0 - frac); // small item into fresh bin: wasteful
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // ---- Congestion awareness: many open bins with high mean residual ----
    if open_bins_count > 0 {
        let mean_frac = mean_residual / cap;
        if mean_frac > 0.5 {
            // Lots of loose space spread around: encourage consolidating.
            score -= 3.0 * mean_frac;
        } else {
            score += 2.0 * (0.5 - mean_frac);
        }
    }

    // Mild tie-breaker toward tighter fits overall.
    score += (pr / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Medium gaps that likely cannot host the next item are mildly penalized.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward a fit that leaves room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: only one open bin fits; prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another bin.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Opening a bin is fine when few bins are open early in the stream.
        if open_bins_count <= 2 {
            score -= 25.0;
        }
    }

    // Prefer bins with below-average residual (tighter bins first).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Late in the stream, compact more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
