        let second_post = post - next_item_size as f64;
        score -= 30.0 - 0.25 * second_post;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to the gap
        let gap = next_item_size as f64 - post;
        score += 0.15 * gap;
    }

    // Penalize dead space too small for typical items (likely unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.3 * (mean_residual - post).max(0.0);
    // Mild penalty for being much looser than mean (wasteful bin)
    score += 0.1 * (post - mean_residual).max(0.0);

    // Slight preference for keeping number of open bins low early on
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins already open or late stream
        score += 8.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
