        score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);
    }

    // Slight preference for larger residual bins when many bins open (balance)
    if open_bins_count > 4 {
        score -= 0.03 * (bin_residual as f64);
    }

    // Avoid leaving residuals in the awkward 20..40 dead zone
    if post_residual >= 20 && post_residual <= 40 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
