    // dead space becomes more costly, so weight the residual more heavily.
    let progress_coupling = 1.0 + 2.0 * progress * progress + 1.5 * progress;
    score *= progress_coupling;

    // Interaction: small post_residual relative to mean residual is great;
    // reward smooth quadratic alignment when bin is tighter than average.
    let mean_gap = (mean_residual - pr) / cap;
    score -= 25.0 * mean_gap * (1.0 - mean_gap * mean_gap).max(0.0);

