    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight_mean = mean_residual / cap as f64;
        // penalize new bin when open bins have plenty of room
        score += 30.0 * (1.0 - scarcity) + 25.0 * tight_mean;
        if scarcity > 0.0 {
            score -= 60.0; // must open a bin anyway
        }
        // early stream: allow more bins; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure toward bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Item-size harmonic bonus: large items prefer low-residual bins
    if item_size >= 50 {
        score += (bin_residual - item_size) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Mid-range gaps that only fit the smallest items are mildly penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    // Penalize leaving a gap that the next item cannot use anyway.
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins below mean residual (tighter bins get priority).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        score += 20.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, opening fresh bins is less wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            // Perfect chain: next item fills bin completely
            if slack == 0.0 {
                score -= 60.0;
            } else {
                // Reward tight two-step fits, penalize large leftover after two steps
                score += slack * 0.35;
                // Bonus if next item leaves a small usable residual (< 10)
                if slack < 10.0 {
                    score -= 12.0;
                }
            }
        } else {
            // Next item cannot use this bin's post-residual: dead space risk
            score += (nxt - pr) * 0.15;
        }
    } else {
        // Last item: prefer minimal final residual
        score += 5.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 4 {
        score += 25.0;
    }

    // Late in the stream, consolidate: favor existing bins over new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate
        score += 15.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Reward filling bins more than half full
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score += (1.0 - usable) * 25.0;
    }

    // Lookahead synergy: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when mean residual across open bins is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 40.0 * (1.0 - progress) + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 20.0; // fresh bin more useful when next item is also large
        }
    }

    // Slight preference for bins with residual below mean (consolidate small leftovers).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Late in stream: be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: later in the stream, tighter fits matter more.
    let coupling = norm_pr * (1.0 - progress) * (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 40.0 * coupling;

    // Penalize residuals that cannot fit the next item (lookahead), scaled by progress.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += waste * (1.0 + progress) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Reward residuals that can still host the lookahead item smoothly.
        let slack = (pr - next_item_size as f64) / cap;
        score -= 8.0 * slack * slack;
    }

    // Last chance bin: strong smooth reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild penalty for spreading across many open bins; smoother late in stream.
    score += open_bins_count as f64 * norm_pr * 0.5 * (0.5 + progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes are more reusable. Reward them by subtracting.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-based reusability bonus: post_residual divisible by 10 (and small)
    // leaves a "clean" harmonic class of space.
    let post_u = post_residual;
    if post_u % 10 == 0 {
        score -= 6.0;
    }
    if post_u % 25 == 0 {
        score -= 3.0;
    }

    // Dead space penalty: post residual too small for the smallest plausible
    // item (<= 10) is wasted space.
    if post_u > 0 && post_u < 10 {
        score += 40.0;
    }

    // Next-item lookahead: if the next item fits exactly in post_residual,
    // strongly favor this bin (perfect harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 25.0;
        } else if next_item_size <= post_u {
            score -= 8.0;
            // harmonic class match: both multiples of the same base
            if post_u % 10 == 0 && next_item_size % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot class
            let overshoot = (next_item_size - post_u) as f64;
            score += overshoot * 0.15;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / cap;
    if fill > 0.8 {
        score -= 10.0 * fill;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_u < 50 {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): only attractive late in the stream or
    // when mean residual across open bins is low; otherwise penalize to
    // prefer packing into existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (mean_residual / cap).max(0.0).min(1.0);
        score -= 30.0 * (1.0 - scarcity) + 20.0 * progress;
        // empty bin leaves full residual; neutral-ish baseline otherwise
        score += 15.0;
    }

    // Mild preference for bins with residual close to the mean (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold: quantize post residual into classes of 20;
    // lower class = tighter packing, slightly favored.
    let class = post_u / 20;
    score -= class as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    } else {
        // Larger residuals scale mildly; very large residual is wasted space.
        score += 0.15 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residual that exactly accommodates the lookahead item (k=2).
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 40.0;
        } else if diff < 0 && diff > -10 {
            score += 15.0; // residual slightly below next item: near-dead space
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    // Progress-aware mild scaling: later in the stream, be more frugal with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Prefer bins tighter than the mean residual (denser bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leave nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Leftover can host next item: mild reward scaled by how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 / (1.0 + slack / 10.0);
        } else {
            // Leftover too small for next item: penalize dead space severity.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Penalize creating small unusable slivers relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Early in stream: encourage keeping bins balanced; late: pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.3;

    // Mild penalty for spreading across many bins.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: strongly reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that no future item can use (min item size 1..100 unknown,
    // so weight by fraction of capacity unusable).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * dead * dead * dead;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 15.0;
        } else {
            score -= 10.0 / (1.0 + gap);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; mild penalty proportional to wasted potential.
        score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin is a fallback; penalize mildly so it's
    // chosen only when open bins fit poorly, but reward it when many bins are open
    // and residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 4.0 * (1.0 - progress);
        // If current bin's post residual would be large and unusable, prefer new bin.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
            score -= 5.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual ->
    // encourage filling existing bins.
    if open_bins_count > 1 {
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 2.0;
        score += open_bins_count as f64 * 0.05;
    }

    // Time horizon: late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer low post-residual, with non-linear polynomial shaping.
    let mut score = r * (1.0 + 0.5 * rn * rn);

    // Smooth quadratic coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them more heavily.
    let coupling = 2.0 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += r * (0.3 + progress * progress) * (1.0 + coupling * 0.1);

    // Penalize residuals that are dead space relative to mean residual of open bins.
    score += (r as f64 - mean_residual).abs() * 0.25;

    // Lookahead: reward residual that can still host the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            let fit_quality = 1.0 - ((r - nx) / cap).powi(2);
            score -= 3.0 * fit_quality * (1.0 + progress);
        } else {
            // Next item cannot fit here: penalize proportionally to shortfall.
            score += 2.0 * (nx - r) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how tight the fit is).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 4.0 * (1.0 - rn);
    }

    // New-bin candidate: make it moderately unattractive unless residual structure
    // of open bins is poor (high mean residual => open bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (0.6 + 0.4 * progress) - 6.0 * fragmentation * (1.0 - progress);
    }

    // Mild regularization to keep scores comparable across bins.
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    // Bands: 0 (perfect), 1 (tiny waste <=5), 2 (small <=15), 3 (medium <=30), 4 (large >30)
    let band = match post_residual {
        0 => 0,
        1..=5 => 1,
        6..=15 => 2,
        16..=30 => 3,
        _ => 4,
    };
    score += band as f64 * 6.0;

    // Integer-division harmonic: post_residual divisible by common class sizes is more reusable
    if post_residual > 0 {
        let div_bonus = (post_residual % 10 == 0) as i32 as f64 * 4.0
            + (post_residual % 5 == 0 && post_residual % 10 != 0) as i32 as f64 * 2.0;
        score -= div_bonus;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: strong reward, scaled by how snug the fit is
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 8.0 + 10.0 * snug;
        } else if next_item_size <= bin_capacity {
            // next item won't fit here: mild penalty proportional to gap
            score += 2.0 + (next_item_size - post_residual) as f64 * 0.1;
        }
    } else {
        // last item: waste matters most, chase perfect fit
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize new-bin candidate when many open bins could fit the item
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * fitting_bins_count as f64;
        // but allow opening a new bin if open bins would leave large dead space
        if post_residual > 40 && fitting_bins_count > 0 {
            score -= 8.0;
        }
    }

    // Progress-based tuning: late in the stream, tighten up (prefer tighter fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin is far below mean residual, it's a good filler
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Modulo harmonic on item size vs capacity: items that pair into capacity get slight preference
    if (item_size % 25 == 0) && post_residual < 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10.0 - post_residual as f64) / 10.0);
    } else if post_residual > 10 && post_residual <= 25 {
        score += 12.0; // mediocre gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Reward bins whose residual matches the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // gap likely wasted for next item
        }
    }

    // New-bin candidate handling: prefer opening a fresh bin when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, moderated by bin pressure.
        score = bin_capacity as f64 * 0.5 + 5.0 * (open_bins_count as f64).sqrt();
        // If current bin is a last chance and fits reasonably, discourage new bin.
        if fitting_bins_count == 1 && post_residual <= 15 {
            score += 30.0;
        }
        return score;
    }

    // Open-bin pressure: when many bins are open, favor filling existing ones.
    score -= 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Reward tighter fits relative to bin residual (best-fit bias).
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    // Late in the stream, prioritize exactness over opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild alignment with mean residual: avoid bins far from average state.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: exact fill is always desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Reward small leftover after hypothetical next placement.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 300.0; // chain of two perfect fits
            }
        } else {
            // Next item cannot follow here: penalize proportionally to dead space.
            score += 25.0 * (1.0 - pr / nxt.max(1.0) as f64).abs();
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let mr = mean_residual;
    if mr > 0.0 {
        score += 0.5 * (pr - mr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave a large unusable remainder or no bin fits well.
    if bin_residual == bin_capacity {
        let is_last_chance_elsewhere = fitting_bins_count == 1;
        if !is_last_chance_elsewhere {
            score += 200.0;
        }
        // Opening a new bin is more acceptable late in the stream? Keep neutral.
    }

    // Small bonus for bins that are already fairly full (low residual).
    score += 0.3 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste (post_residual) is the core cost, but amplify
    // the penalty for large dead space quadratically.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Lookahead: if the next item fits exactly in the post residual, strongly
    // favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for next item: penalize proportional to
        // unusable space unless it's near zero (perfect fill).
        if post_residual > 0 {
            score += 3.0 * (post_residual as f64) / bin_capacity as f64;
        } else {
            score -= 8.0; // bin perfectly closed is great
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.05 * item_size as f64;
    }

    // New-bin candidate handling: empty bin. Prefer it only when existing
    // fits are poor (large post residual among open bins) or when mean
    // residual across open bins is very low (all bins nearly full).
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count > 0 {
            (mean_residual / bin_capacity as f64).max(0.0)
        } else {
            1.0
        };
        // Penalty for opening a new bin when open bins could absorb the item.
        score += 15.0;
        if fitting_bins_count > 0 {
            // If mean residual is large, open bins are fragmented; a new bin
            // is more attractive, so reduce the penalty.
            score -= 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        } else {
            score -= 20.0; // no alternative: must open new bin
        }
        // Early in stream, opening bins is cheap (builds flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        let _ = poor_fit_pressure;
    }

    // Late-stream conservatism: near the end, prefer closing bins tightly
    // rather than spreading items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 4.0 * progress * (open_bins_count as f64).ln_1p();
    }

    // Slight preference for bins whose residual deviates from the mean in a
    // useful direction: bins with residual much larger than the mean are
    // good targets (they'd otherwise stay stranded).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.5 * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += norm_pr * norm_pr * (30.0 + 40.0 * t) * (1.0 - t * 0.5);

    // Penalize large dead space more aggressively as stream advances
    score += (norm_pr - 0.5) * (norm_pr - 0.5) * 25.0 * (0.5 + t);

    // Reward tight fits (small post_residual) with smooth decay
    score -= 20.0 * (-norm_pr * 6.0).exp() * (1.0 + t);

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - norm_pr) * (0.5 + t);
    }

    // Lookahead coupling: reward post_residual that still fits next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= fits_next * 15.0 * (-gap * 4.0).exp();
        score += (1.0 - fits_next) * 10.0 * norm_pr;
    }

    // Mild penalty for spreading across many open bins, smoothed by progress
    score += (open_bins_count as f64).ln() * 3.0 * (0.3 + 0.7 * t);

    // Deviation from mean residual, non-linear
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 12.0 * (1.0 - t * 0.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Leftover divisible by 10 or 25 is more reusable -> subtract bonus.
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        // Dead zone: tiny leftovers 1..=5 are nearly unusable -> penalize.
        if pr <= 5 {
            score += 15.0;
        }
    } else {
        // Perfect fit is ideal.
        score -= 25.0;
    }

    // Fraction-of-capacity classes of the post residual.
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.2 {
        score += 8.0; // thin sliver waste
    } else if frac >= 0.5 {
        score -= 5.0; // half-full leftover still very usable
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after that matters
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 6.0;
            }
            score -= 3.0;
        } else {
            // next item cannot use this leftover: penalize large unusable gaps
            let gap = (next_item_size - pr) as f64;
            if gap < 10.0 {
                score += gap * 0.8;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer tighter bins overall: relative tightness term.
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    // Slight preference for consolidating into fewer bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if open bins are quite full / crowded.
        score += 10.0 + 20.0 * (1.0 - progress) + mean_residual * 0.15;
    } else {
        score -= 2.0 * (mean_residual - post_residual as f64).max(0.0) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that are too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += (20 - item_size.min(20)) as f64 * 2.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 3.0;
    } else {
        // New-bin candidate: penalize opening a new bin, more when bins are open.
        score += 30.0 + open_bins_count as f64 * 8.0;
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use.
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) but not too tight.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty: unusable sliver
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // 2-step lookahead: reward post_residual matching next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 25.0; // exact 2-step match
        }
        if next_item_size > post_residual {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when few bins fit
    // or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 {
            (item_size as f64 + next_item_size as f64) / 2.0
        } else {
            item_size as f64
        };
        if fitting_bins_count <= 1 || pressure > mean_residual + 20.0 {
            score -= 15.0; // allow opening when placement is poor elsewhere
        } else {
            score += 30.0; // discourage opening when good fits exist
        }
    }

    // Late-stream consolidation: close bins down as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio;

    // Penalize dead space: residual too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * chain;
    }
    // If next item cannot use post residual, penalize leaving large gap.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in stream, prefer compacting into open bins;
    // later, allow more tolerance for opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // Global state: many open bins with high mean residual -> favor filling
    // existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
    } else {
        // New-bin candidate: penalize when open bins are plentiful and roomy.
        score += 8.0 + 0.5 * open_bins_count as f64 + 0.1 * mean_residual;
        // But allow new bin late in stream when residual fragmentation is high.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter fits matter more (dead space is costlier)
    let coupling = pr * (progress * progress) * (1.0 - progress) * 4.0;
    score += 0.5 * coupling;

    // Penalize leaving residual that no typical item (>=1) can use; reward
    // near-perfect fits with a smooth saturating term
    let fit_quality = 1.0 - (pr / cap);
    score -= 6.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual would be
    // large and stream is early; smooth interaction with progress
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 8.0;
        score += 15.0 - early_bonus + 5.0 * norm_pr;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Deviation from mean residual: prefer bins whose residual is near mean
    // (harmonic packing) with smooth quadratic penalty
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild pressure to close out many open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but treat dead space non-linearly.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // capacity fraction of leftover

    // Harmonic class of the leftover space: bins whose residual falls into
    // "usable" classes (multiples of small denominators) are more valuable.
    let harmonic_penalty = if post_residual == 0 {
        -50.0 // perfect fill
    } else {
        // integer-division thresholds: leftover <= 10 is nearly perfect
        match post_residual {
            0..=5 => -20.0,
            6..=10 => -12.0,
            11..=20 => 0.0,
            21..=40 => 8.0,
            41..=70 => 15.0,
            _ => 22.0,
        }
    };
    score += harmonic_penalty;

    // Modulo arithmetic on post_residual: leftovers divisible by common item
    // size classes (10, 20, 25, 50) are more likely reusable.
    let reusable = (post_residual % 10 == 0) as f64 * 8.0
        + (post_residual % 20 == 0) as f64 * 4.0
        + (post_residual % 25 == 0) as f64 * 3.0
        + (post_residual % 50 == 0) as f64 * 3.0;
    score -= reusable;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after next placement matters
            let next_left = post_residual - next_item_size;
            score -= 10.0 * (1.0 - next_left as f64 / cap_f);
        } else {
            // next item cannot use this leftover: penalize large leftovers
            score += frac * 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is bad and
    // mean residual across open bins is small (stream is "tight").
    if bin_residual == bin_capacity {
        let tight_stream = mean_residual < 15.0;
        let bad_fit = post_residual > 30;
        if bad_fit && tight_stream {
            score -= 15.0; // fresh bin better than wasting space
        } else {
            score += 20.0; // prefer filling existing bins by default
        }
    }

    // Stream progression: early on, be conservative (keep bins flexible);
    // late in the stream, squeeze harder into any fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_f.max(0.0) * 0.3);

    // Many open bins: encourage consolidation into low-residual bins.
    score += (open_bins_count as f64).ln().max(0.0) * frac * 5.0;

    // Mean residual coupling: if open bins are generally loose, this bin's
    // leftover is less costly; if they are tight, leftover is costly.
    score += frac * (mean_residual / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: post_residual in (0, 10] is dead space
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize creating gaps smaller than the minimum item size (1..=10 range unknown, use conservative 10)
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Open-bin pressure: fewer open bins is cheaper; add pressure proportional to count
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If next item would be wasted by this gap, penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // New-bin candidate: mild penalty so we only open when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if current bin would leave terrible gap, opening new bin is better
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
    }

    // Tightness reward: reward filling a large fraction of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize deviation of post_residual from next item size (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect chain: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Waste if post_residual is smaller than next item AND too small for the smallest plausible item.
        if post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 5.0;
    }

    // Reward bins below mean residual (compact usage), penalize above.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 8.0 + 0.5 * waste;
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > next_item_size {
            score += 10.0; // new bin would leave space that duplicates what open bins already have
        }
    }

    // Late in the stream, be extra frugal with residual space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize dead space: residuals too small for the smallest item (1..=100 range, small items possible).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item can use the post residual, reward; otherwise penalize waste.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 5.0;
        } else {
            score += 4.0;
        }
        // Perfect chain: item + next item exactly fill the bin.
        if (post_residual as u32) == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Slight penalty so we prefer reusing bins with good fits...
        score += 8.0;
        // ...but if existing bins are fragmented (high mean residual spread / many open bins),
        // opening fresh becomes more attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        if fragmentation > 3.0 {
            score -= 10.0 + 5.0 * progress;
        }
        // Large items prefer a fresh bin to avoid stranding space.
        if item_size > 50 {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is close to the item (minimize leftover), beyond raw post_residual.
    let slack = (bin_residual as f64 - item_size as f64);
    score += 0.15 * slack;

    // Mild time-horizon modulation: early in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (using up the emptier bins keeps fuller ones compact).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.10 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress) - 3.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize tight fits less as stream progresses (dead space matters more early)
    let tightness = 1.0 - norm_pr;
    score += 8.0 * tightness * tightness * (1.0 - progress);

    // Reward filling bins nearly completely
    if post_residual == 0 { score -= 15.0; }

    // Last-chance bin bonus
    if fitting_bins_count == 1 { score -= 6.0; }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 + 0.05 * next_item_size as f64;
    }

    // Slight preference for bins below mean residual (balance)
    score += 0.3 * (pr - mean_residual);

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity { score += 5.0 + 10.0 * progress; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fill is perfect,
    // tiny dead space (<10) is nearly worthless, mid leftovers are useful.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if post_residual < 10 {
        score += 25.0; // dead space class
    } else if post_residual <= 20 {
        score -= 20.0; // sweet-spot leftover for small future items
    }

    // Modulo-10 harmonic class: leftovers that are multiples of common
    // item sizes (10,20,...) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or good fit for next item -> strong reward
            let nxt_post = post_residual - next_item_size;
            if nxt_post == 0 {
                score -= 60.0;
            } else if nxt_post < 10 {
                score -= 10.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize slightly less if this
            // bin would otherwise be the only fitting bin (last chance)
            if fitting_bins_count == 1 {
                score -= 5.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid new bin
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave large unusable residue.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are used only when justified
        score += 30.0;
        // but if the current item is large and would leave a bad class
        // leftover in every open bin, a fresh bin becomes attractive
        let would_be_post = bin_capacity - item_size;
        if would_be_post < 10 && open_bins_count > 0 {
            score -= 40.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Prefer packing into bins whose residual is already small
    // (consolidation): reward when bin_residual is far below capacity.
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Coupling with mean residual: if this bin is below average fullness,
    // favor it slightly to drain laggard bins.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold on post_residual: classify leftover
    // into quartiles of capacity; low quartiles are more valuable.
    let quartile = post_residual / (bin_capacity / 4).max(1);
    score -= match quartile {
        0 => 10.0,
        1 => 4.0,
        2 => 0.0,
        _ => -2.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tight fit reward relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins whose residual is already below average (filling down).
    score += 0.25 * ((bin_residual as f64) - mean_residual);

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // Next item cannot fit here; the gap becomes dead space for lookahead.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // New-bin candidate: penalize slightly so it is only chosen when fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    // Early in stream: mild preference to open/keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Penalize leaving post_residual too small for the next item (dead space).
        if (post_residual as u64) < next_item_size as u64 {
            score += 8.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Reward tight fits: small post_residual generally good.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates from the mean (prefer balanced or
    // deliberately skewed extremes; mild pull toward mean).
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or few bins are open (early stream benefits from spreading).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit && open_bins_count > 0 && progress > 0.05 {
            score -= 12.0;
        } else {
            score += 20.0;
        }
    }

    // Mild preference for filling already-open bins as stream progresses.
    score += 2.0 * (step_index as f64 / (total_items.max(1) as f64)) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - t) * (1.0 - t);

    // Penalize dead space that is too small for typical items (1..100 unknown).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward if next item can fit into post-residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Penalize leaving a gap that just barely misses the next item.
            if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual < 15 {
                score += 12.0;
            }
        }
    }

    // Prefer bins with residual below mean residual (fill fuller bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: early in the stream, be more conservative (favor new bins
    // less); late in the stream, squeeze into existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - t);

    // Many open bins: discourage spreading; few open bins: encourage reuse.
    score += 0.5 * open_bins_count as f64 * t;

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., this empty bin call has huge residual) and item is large.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base penalty so new bins are opened only when beneficial.
        score += 45.0;
        // Large items justify fresh bins more (avoid fragmenting open bins).
        score -= 50.0 * large_item;
        // Late in stream, reuse is cheaper than opening bins.
        score += 30.0 * progress;
        // If only one bin fits, opening new is wasteful.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit), smooth polynomial in post_residual
    let mut score = post + 0.15 * (post * post) / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly.
    let prog_coupling = (post / cap).powi(2) * progress * 40.0;
    score += prog_coupling;

    // Reward tight fits more strongly as stream progresses (smooth sigmoid-ish ramp)
    let tightness = 1.0 - post / cap; // 1 = perfect fit
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Last-chance bin: strongly favor using it (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: bonus if the next item can use the post-residual space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let leftover = (post - nxt) / cap;
            // smooth reward decaying with leftover after next-item fit
            score -= 12.0 * (1.0 - leftover) * (1.0 - leftover) * (0.5 + 0.5 * progress);
        } else {
            // post-residual too small for next item: mild penalty, worse late in stream
            score += 6.0 * progress * (1.0 - post / cap);
        }
    }

    // New-bin candidate: prefer it early (diversification) or when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let early = (1.0 - progress).powi(2);
        let open_norm = (open_bins_count as f64).min(20.0) / 20.0;
        score = 30.0 + 20.0 * (1.0 - early) + 25.0 * fragmentation * open_norm;
        // occasionally a fresh bin is genuinely good even late if fragmentation is high
        score -= 15.0 * fragmentation * open_norm * progress;
    }

    // Mild penalty for very large residuals relative to mean (keeps bins balanced)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Class 0: post_residual in {0} -> perfect fit, huge reward.
    // Class 1: post_residual divisible into small standard slots (10/20/25/50).
    // Class 2: awkward leftover -> penalize.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let r = post_residual;
        // integer-division harmonic classes on residual
        let cls = if r % 50 == 0 { 0 }
        else if r % 25 == 0 { 1 }
        else if r % 20 == 0 { 2 }
        else if r % 10 == 0 { 3 }
        else { 4 };
        score -= match cls {
            0 => 25.0,
            1 => 18.0,
            2 => 14.0,
            3 => 10.0,
            _ => 0.0,
        };
        // penalize tiny unusable leftovers
        if r < 10 {
            score += 15.0 + (10 - r) as f64;
        }
    }

    // Lookahead coupling: does post_residual exactly fit next item (harmonic pair)?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 12.0;
            }
            score += slack as f64 * 0.1;
        } else {
            // next item cannot fit here; residual becomes dead space weight
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is huge relative to
    // residual or mean residual is already low (bins nearly full).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 && mean_residual < 15.0 {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln() * 0.5;

    // Prefer tighter fits overall (small waste fraction).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // minimum item (size 1..10) are pure waste -> heavy penalty.
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps (10..20) are risky dead space as well.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tightness relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin -> reward, scaled by how well the item fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * fill_ratio;
    }

    // Lookahead: if the next item fits into the post residual, reward this
    // placement for enabling a chain; otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate: prefer it only when the mean residual of open bins
    // is already very fragmented (lots of unusable space) or no bin fits well.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin normally...
        score += 40.0;
        // ...unless open bins are heavily fragmented.
        score -= 50.0 * fragmentation.max(0.0).min(1.0);
        // Strongly penalize new bin when a last-chance fit exists.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
    }

    // Mild stream-progression bias: late in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-step chain
        }
        // Penalize leaving dead space smaller than the smallest plausible item.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Relative to mean residual: bins with more slack than average are better hosts.
    score -= 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting space in a fresh bin when other bins could fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * open_bins_count as f64;
        // But a new bin is fine if it enables a perfect lookahead chain.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Mild progression pressure: early in stream, keep bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: post_residual that is too small to hold any future item.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Dead-space cliff: residuals below the smallest plausible next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 {
        // Reward bins that can also host the lookahead item (chained fit).
        score -= 30.0;
        if post_residual - next_item_size <= 5 {
            score -= 20.0; // perfect two-item chain
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        // Prefer new bin when open bins are loose on average.
        score -= 40.0 * mean_tight;
        // Early in the stream, opening bins is cheap (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If many bins fit, opening a new one is wasteful.
        score += 15.0 * (fitting_bins_count as f64).min(5.0);
        // Slight inherent reluctance to open new bins.
        score += 10.0;
    }

    // Prefer filling bins that are already mostly full (reduce open-bin count pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio * fill_ratio * fill_ratio;

    // Global balance: mildly prefer bins close to the mean residual (keeps spread even),
    // but only when many bins are open.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Time-horizon coupling: late in the stream, consolidation matters more;
    // penalize leaving any residual that could have been avoided.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Lookahead magnitude: large next items make conserving big residuals valuable.
    if next_item_size > item_size {
        score += 0.4 * (next_item_size - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on wasted post-residual (dead space)
    let mut score = post * post / cap;

    // Non-linear coupling: waste hurts more as the stream progresses
    score += 40.0 * norm_post * norm_post * progress;

    // Tight fits rewarded smoothly (post near 0)
    score -= 30.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_item;

    // Prefer bins whose residual is close to item size (smooth gap term)
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 25.0 * gap * gap;

    // Lookahead: reward leaving room for the next item, smoothly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post - next) / cap;
        score += 15.0 * diff * diff - 10.0 * (1.0 - (post / next.max(1.0)).min(1.0));
    }

    // Last-chance bonus: if few bins fit, strongly favor this one
    if fitting_bins_count <= 1 {
        score -= 50.0;
    } else {
        score += 5.0 / fitting_bins_count as f64;
    }

    // Mild penalty when bin is far below mean residual (keeps bins balanced)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Slight new-bin aversion that grows with stream progress
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 dead-space classification.
    let pr = post_residual as u32;
    let class = pr % 10;
    // Residuals that are small multiples of 10 are "harmonic" — reusable by
    // typical item sizes; odd/prime-ish residuals are dead space. Penalize.
    let harmonic_bonus = match class {
        0 => 6.0,
        5 => 4.0,
        2 | 8 => 2.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Dead space: post_residual too small for the minimum plausible item.
    // Anything in 1..10 is nearly unusable -> strong penalty.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Fractional fill: reward tight fits (post_residual near zero).
    let fill = (bin_residual - post_residual) as f64 / cap; // = item fraction
    score -= 20.0 * fill * fill;

    // Coupling with next item: if the next item fits exactly in post_residual,
    // this placement is excellent; if post_residual can't hold next item but
    // could hold a fraction-classed remainder, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // leftover after hypothetically placing next item
            let r2 = post_residual - next_item_size;
            score -= 4.0 + (r2 % 10) as f64 * 0.5;
            if r2 == 0 { score -= 20.0; }
        } else {
            // next item cannot use this residual: dead-space risk grows
            score += 8.0 * (next_item_size - post_residual) as f64 / 50.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when this bin would
    // otherwise waste a lot, or when it's a perfect fresh fit for big items.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost of one full capacity of slack.
        score += 45.0;
        if item_size >= 50 {
            score -= 40.0; // big items start fresh bins happily
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 15.0; // pairing impossible anyway; fresh bin fine
        }
        if open_bins_count == 0 {
            score -= 100.0; // must have at least one bin
        }
    }

    // Spread-aware term: avoid leaving residuals far from the mean when the
    // mean is large (many half-empty bins) — consolidate instead.
    let prf = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (prf - mean_residual).abs();
    }

    // Late in the stream, prefer tighter packing (minimize final waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (prf / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (too small for typical future items, but nonzero) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit is excellent
    }

    // Pressure from number of open bins: discourage spreading when many bins open,
    // but encourage filling existing bins when few are open.
    let open_pressure = open_bins_count as f64 * 2.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space w.r.t. the known next item
    }

    // Compare residual against the mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Slight preference for keeping new bins closed as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress; // penalize opening new bins, more so later
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize large post-residuals that are hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space below the minimum item size
    } else if post_residual >= 10 {
        // Residual that could fit a typical item is fine; bonus if it fits lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Opening a fresh bin to pair current+next items can be great.
            score -= 20.0;
        }
    }

    // Lookahead coupling: if next item is large, avoid creating awkward residuals.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap > 0 && gap < 10 {
            score += 12.0; // residual just below next item = wasted
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.3 * mean_residual * (1.0 - progress);

    // Prefer bins with smaller residual among equals (tighter bins first).
    score += 0.1 * bin_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let progress = progress.clamp(0.0, 1.0);

    // Base: prefer tight fits (low post residual), normalized
    let mut score = pr / cap;

    // Smooth non-linear coupling: small residuals matter more early than late
    let dead = (pr / cap).powi(3);
    score += dead * (1.0 - 0.5 * progress) * 2.0;

    // Polynomial interaction between residual and progress: waste penalized
    // increasingly as stream progresses (fewer chances to recover space)
    let interact = (pr / cap) * (progress * progress * (3.0 - 2.0 * progress));
    score += 0.8 * interact;

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).abs();
        let kernel = (-(fit_next / cap).powi(2) * 4.0).exp();
        score -= 1.2 * kernel * (1.0 - progress * 0.3);
    }

    // Last-chance bin: strongly favor using it (avoid opening a bin)
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - 0.5 * (pr / cap));
    }

    // Crowding effect: many open bins -> favor filling existing ones
    let crowd = (open_bins_count as f64).ln_1p() / (1.0 + (open_bins_count as f64).ln_1p());
    score -= 0.6 * crowd * (1.0 - pr / cap);

    // Mean residual context: penalize bins far from the mean residual (outliers)
    let dev = ((pr - mean_residual) / cap).abs();
    score += 0.4 * dev * dev;

    // New-bin candidate: smooth bias so empty bins are chosen only when
    // existing fits are poor (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        score += 0.5 + 0.9 * (1.0 - (pr / cap));
        // allow opening a new bin late when remaining waste is small
        score -= 0.7 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes.
    // Small residuals (< 10) are dead space -> penalize strongly.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward residuals that are "harmonic" multiples of common item classes (10,20,25,50).
    let pr = post_residual as f64;
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: prefer small leftover after next placement
            let post2 = post_residual - next_item_size;
            score -= 10.0 + (10 - (post2 % 10)) as f64 * 0.5;
            if post2 < 10 {
                score += 12.0; // but avoid creating tiny dead space after next
            }
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin should lose unless current bin creates dead space or is last chance.
        score += 20.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere else: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin leaves room for the lookahead item
            score -= 10.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    // Prefer bins below mean residual (tighter packing).
    score += (pr - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // A gap is "dead" if it cannot hold even the smallest plausible item (<=10)
        // or cannot hold the lookahead item. Non-linear quadratic penalty on small gaps.
        let dead_threshold = 10u32.max(next_item_size.min(10));
        if post_residual < dead_threshold {
            score += 40.0 + pr * 2.0; // tiny useless gap: heavy penalty
        } else {
            // mild super-linear penalty for leaving moderately small gaps
            let smallness = (20.0f64 - pr.min(20.0)).max(0.0);
            score += smallness * smallness * 0.05;
        }
        // If the lookahead item would fit exactly in the gap, reward heavily.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Perfect fit: zero waste, strongly rewarded.
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (bin_residual - item_size) as f64 * 0.2;
    }

    // Open-bins pressure: prefer compacting into existing bins when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate handling: only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by mean residual of open bins.
        score += 55.0 + mean_residual * 0.3;
        // If many open bins have large mean residual, opening a new bin is less bad
        // (existing bins are fragmented), so reduce penalty slightly.
        if mean_residual > 50.0 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter fits overall (lower post_residual relative to item).
    score += (item_size as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not exactly zero
    // unless unavoidable — a perfect fill is always good.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item size (chain packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Exact chain: next item fills this bin perfectly afterwards.
        if post_residual == next_item_size {
            score -= 35.0;
        }
        // Penalize post_residual that is too small to ever be useful
        // (dead space smaller than the minimum plausible item).
        if post_residual < next_item_size.min(10) {
            score += 15.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Relative-to-mean coupling: a bin with residual well below the mean
    // is already "broken in"; favor packing it down further.
    let rel = post_residual as f64 - mean_residual;
    score += 0.08 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is huge relative to remaining space or many bins exist.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly by default; relax for large items late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 30.0 * tightness - 15.0 * progress;
        // If many bins are open and none fit well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mild preference to consolidate into fewer bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // cheaper to open new bins early in the stream (more future to amortize)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // opening a new bin is more attractive when many bins are already open
        // and their mean residual is fragmented
        score -= 0.3 * open_bins_count as f64;
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 15.0; // existing residuals too small on average
        }
        // if the next item is large, a fresh bin is valuable
        if next_item_size >= item_size && next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit flavor)
        let diff = (bin_residual - item_size) as f64;
        score += 0.1 * diff;
        // Slight preference for bins below mean residual (consolidate fragmented space)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Mild time pressure: late in the stream, avoid opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: post_residual weighted by a smooth polynomial in progress
    let poly = 0.5 + 2.0 * progress * progress + 1.5 * progress * (1.0 - progress);
    score *= poly;

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (0.3 + progress);

    // Penalize large post_residual if lookahead item won't fit in it
    if next_item_size > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        } else {
            score -= 3.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Slight penalty when many bins already open relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead space" classes (mod 10 buckets) are penalized less.
    let pr = post_residual;
    let class = pr % 10;
    let div = pr / 10;
    // Reward tiny leftovers (good packing) with a harmonic-style bonus.
    if pr > 0 {
        score -= 30.0 / (pr as f64).sqrt();
    } else {
        score -= 45.0; // perfect fill
    }
    // Penalize mid-range dead-space classes (11..30) heavily: hard to reuse.
    if pr >= 11 && pr <= 30 {
        score += 25.0 + 5.0 * ((pr % 7) as f64);
    }
    // Large leftovers (div >= 4) are still useful; mild reward.
    if pr >= 40 {
        score -= 8.0;
    }
    // Odd/even class coupling with next item size.
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // Next item fits exactly in this bin's post residual: strong reward.
            score -= 20.0 + (pr - n) as f64 * 0.3;
            if pr == n {
                score -= 15.0; // exact chain fill
            }
        } else {
            // Next item won't fit here; penalize if we also waste class space.
            score += 6.0;
            if n % 10 == class {
                score -= 4.0; // same harmonic class, likely reusable later
            }
        }
    }
    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }
    // New-bin candidate: penalize unless current bin fits poorly.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big upcoming item may warrant fresh bin
        }
    }
    // Prefer tighter bins relative to mean residual.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.25;
    } else {
        score += (resid_f - mean_residual) * 0.15;
    }
    // Fraction-of-capacity threshold: bins less than 1/3 full are low priority.
    if resid_f > cap * 0.66 && bin_residual < bin_capacity {
        score += 10.0;
    }
    // Early stream: be conservative, keep bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item
    // (or the known next item) are nearly worthless.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful {
        score += 45.0;
    } else if post_residual < next_item_size && next_item_size > 0 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - 3.0) * (0.8 + 0.7 * progress);

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    if bin_residual > 0 {
        score -= 30.0 * (item_size as f64 / bin_residual as f64);
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits in the leftover space: strong reward scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.25 * slack;
    }
    // Next item does NOT fit in leftover: penalize wasted space that blocks lookahead.
    else if next_item_size > 0 && post_residual > 0 {
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Reward tightness relative to mean residual across open bins.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving very small unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred...
        score += 25.0;
        // ...but relax it when many bins are open and mean residual is large
        // (fragmentation is high; a fresh bin may be cleaner).
        if open_bins_count > 2 {
            score -= (open_bins_count as f64).min(10.0) * 1.5;
        }
        if mean_residual > 60.0 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear penalty
    // on very small post_residuals that become unusable dead space.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // dead-space penalty: residuals below ~10 are likely wasted
        if pr < 10.0 {
            score += (10.0 - pr) * 0.8;
        }
        // mild convex reward for medium residuals that can host future items
        score -= (pr / bin_capacity as f64).powf(1.5) * 6.0;
    } else {
        // perfect fit: strong reward
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 + 6.0 * tightness;
        } else {
            // next item won't fit here; penalize slightly if it leaves big gap
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // Global state: many open bins with large mean residual -> encourage
    // consolidating into existing bins rather than opening more.
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score += 2.0 - consolidation.min(4.0);
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline so it
    // only wins when existing bins are poor fits (large post_residual there).
    if bin_residual == bin_capacity {
        score += 4.0;
        // early stream: new bins are cheaper to open
        score -= (1.0 - progress) * 3.0;
        // if next item is large and no open bin can host it well, new bin ok
        if next_item_size > 50 && post_residual == bin_capacity {
            score -= 2.0;
        }
    }

    // Slight preference for bins whose residual is closest above item size
    // (best-fit flavor beyond raw post_residual).
    let gap = (bin_residual as i64 - item_size as i64).max(0) as f64;
    score += gap * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = norm_pr * norm_pr * cap;

    // Non-linear coupling with stream progress: early on tolerate waste, later penalize heavily
    let progress_coupling = norm_pr * (1.0 + 2.0 * progress * progress);
    score += 8.0 * progress_coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins far below mean residual (bad fragmentation relative to fleet)
    score += 0.05 * (mean_residual - pr).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space usable by the next item, penalize dead space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (pr - nxt) / cap * (1.0 - progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for many open bins, smoothed
    score += 0.01 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep it moderately expensive so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let class = pr % 10; // decade class
    // Dead-space classes: residuals that few item sizes can fill are penalized.
    let usable = if pr == 0 { 10.0 }
        else if pr >= 80 { 8.0 }
        else if pr >= 50 { 5.0 }
        else if pr >= 20 { 4.0 }
        else { 2.0 };
    score -= usable * 3.0;

    // Reward exact fills and near-exact fills strongly.
    if pr == 0 { score -= 60.0; }
    else if pr <= 5 { score -= 25.0; }
    else if pr <= 10 { score -= 12.0; }

    // Integer-division harmonic: residual divisible by common item sizes is good.
    if pr > 0 {
        let mut div_bonus = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 { div_bonus += 4.0; }
        }
        score -= div_bonus;
    }

    // Lookahead: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > pr {
            score += 15.0; // next item won't fit here
        } else {
            // harmonic coupling: next item leaves another clean residual
            let post2 = pr - next_item_size;
            if post2 == 0 { score -= 30.0; }
            else if post2 % 10 == 0 { score -= 10.0; }
            else if post2 < 10 { score += 8.0; }
        }
    } else {
        // Last item: prefer exact fill aggressively.
        if pr == 0 { score -= 40.0; }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild pressure against opening new bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by open bins and progress.
        score = cap * 0.55 + open_bins_count as f64 * 3.0 + progress * 20.0;
        // If item exactly fits and no other bin is great, still allow new bin rarely.
        if fitting_bins_count == 0 { score -= 10.0; }
    }

    // Slight preference for tighter bins overall (below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps (1..=12) are nearly unusable
    // for items >= 10; penalize them hard, non-linearly.
    if post_residual >= 1 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 6.0;
    }
    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward bins whose residual after placement can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // creates a gap the next item cannot use
        }
    }

    // Pressure on number of open bins: slightly favor consolidating into
    // existing bins rather than spreading out.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: normally penalized so we reuse open bins,
    // but if the item leaves a dead gap in every fitting bin the fresh
    // bin (large post_residual) becomes attractive via its clean residual.
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 0.5;
    }

    // Mild preference for tighter bins (small residual relative to mean).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    // Late in the stream, prioritize closing bins out (perfect fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item,
    // especially when the chain is near-perfect (post_residual == next_item_size).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.8;
        // Perfect chaining: post_residual exactly matches next item.
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize dead space more when
        // the dead space is tiny (wasted potential).
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 15.0;
        }
    }

    // Compare against mean residual: placing into a bin far below mean residual
    // balances the bin pool, which helps future fits.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has a huge residual, so its base
    // score is high. Only let it win when current fits are poor (large post_residual
    // waste) or the item is large and a fresh bin preserves flexibility.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin, discounted early in the stream and
        // when many bins are already open (consolidation pressure).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 + 40.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 15.0; // large items benefit from fresh bins
        }
    }

    // Slight preference to fill bins that are already quite full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strong quadratic discount for small post_residual.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to hold a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // awkward gap
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate logic: only attractive when the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin early in the stream or when many bins are open.
        score += 15.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        score += 0.3 * open_bins_count as f64;
        // But reward if this bin's fit would leave a huge awkward gap.
        if post_residual == 0 {
            score += 1e9; // never open a new bin for a perfect fit elsewhere
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 22.0 - gap; // near-perfect chain
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: slightly penalize leaving residual it could have used.
        score += 4.0;
    }

    // Global state coupling: when mean residual is high, prefer consolidating into fuller bins.
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev; // prefer below-average-residual (fuller) bins
    }

    // Mild entropy term: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_post * (0.55 + 0.9 * p2 + 0.6 * p3);

    let mut score = post;

    // Reward tight fits more strongly as the stream progresses.
    score -= coupling * cap * 0.35;

    // Penalize dead space quadratically (small unusable slivers).
    if norm_post > 0.0 {
        score += norm_post * norm_post * cap * 0.18;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (0.5 + progress);
        // Strong reward when next item fits exactly in the post residual.
        if post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Slight preference for bins with residual above the mean (balance).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction slot it lands in.
    // Classes: 0 (perfect fit), tiny (<=10), small (<=25), medium (<=50), large (>50).
    let class = if post_residual == 0 {
        0.0
    } else if post_residual <= 10 {
        1.0
    } else if post_residual <= 25 {
        2.0
    } else if post_residual <= 50 {
        3.0
    } else {
        4.0
    };
    score += class * 6.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: post_residual too small for any item (min size 1,
    // but items 10..80 in classic mode; treat < 10 as dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // Harmonic residue of the pair: (post_residual % next_item_size)
            let residue = post_residual % next_item_size.max(1);
            score += residue as f64 * 0.8 + slack as f64 * 0.15;
        } else {
            // Next item cannot follow here: mild penalty scaled by overflow.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Integer-division thresholds on bin_residual (harmonic tiers of fullness).
    let tier = bin_residual / 25; // 0..4
    score += tier as f64 * 2.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly so we
    // only open new bins when no open bin gives an acceptable fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if current item is large relative to mean residual, opening fresh
        // may be better: reduce penalty when mean residual is small.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Modulo-arithmetic harmonic class on item_size (classes of 10).
    let item_class = item_size % 10;
    if item_class == 0 {
        score -= 3.0; // round sizes pack predictably
    }

    // Stream progression: later in stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 8.0;
    }

    // Prefer tighter bins generally: coupling with mean residual.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Small tie-break noise-free deterministic term on open bin count.
    score += (open_bins_count % 3) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1) are fine,
    // but residuals in the "awkward" band (just above item sizes likely to arrive) are dead space.
    // Penalize small non-zero post_residuals that can't fit the next item.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        }
        // General dead-space curve: worst for residuals in [1..20] band
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 0.8;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Reward filling a bin nearly completely
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    let open_pressure = open_bins_count as f64 / 10.0;
    if bin_residual != bin_capacity {
        score -= open_pressure * 2.0;
    } else {
        // New-bin candidate: penalize proportionally to open bins, plus base cost
        score += 6.0 + open_pressure * 3.0;
    }

    // Prefer bins tighter than the mean residual (good packing)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Late in stream: consolidate harder, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post == nxt {
            score -= 60.0; // perfect 2-chain: item + next item fill bin exactly
        } else if post > nxt {
            // still fits next item: reward proportionally to tightness
            score -= 25.0 * (1.0 - (post - nxt) / 100.0);
        } else {
            // next item won't fit: penalize dead space beyond what's needed
            score += (nxt - post) * 0.6;
        }
    }

    // Reward tight fits overall
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New empty bin candidate: make it unattractive unless lookahead is hopeless
    if bin_residual == bin_capacity {
        let hopeless = next_item_size > 0
            && post_residual == bin_capacity
            && item_size > 0
            && fitting_bins_count == 0;
        score += if hopeless { 0.0 } else { 45.0 };
        // opening fresh bin is fine early in stream (plenty of room to plan chains)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Slight preference to fill bins more densely as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the leftover relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect pairing bonus: next item exactly consumes the leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Dead-space risk: leftover likely unusable for the next item.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 15.0 * waste * waste;
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin, more so for
    // small items or when many bins are already open and reasonably full.
    if bin_residual == bin_capacity {
        let item_frac = (item_size as f64) / (bin_capacity as f64);
        let open_pressure = (open_bins_count as f64) / (1.0 + (mean_residual / (bin_capacity as f64)).max(0.01));
        score += 25.0 + 40.0 * (1.0 - item_frac) + 2.0 * open_pressure.min(10.0);
        // Late in the stream, opening new bins is even less attractive.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
    }

    // Mild global pressure: when mean residual across open bins is small,
    // bins are nearly full, so prefer placements that minimize post_residual.
    if mean_residual < (item_size as f64) * 1.5 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, with quadratic sharpening over the stream.
    let mut score = pr * (1.0 + 1.5 * fill * fill) * (0.6 + 0.8 * progress);

    // Reward bins whose leftover can still host the next item (smooth lookahead coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack_fit = 1.0 - ((pr - nx) / cap).powi(2);
            score -= 6.0 * slack_fit * (0.5 + 0.5 * progress);
        } else {
            // Penalize leftovers too small for the lookahead item (dead space).
            score += 4.0 * (nx - pr) / cap * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // with the penalty decaying as many bins exist and fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 8.0 * (1.0 - 0.5 * progress) * scarcity + 0.05 * open_bins_count as f64;
    }

    // Mild alignment with mean residual: prefer bins deviating below the mean.
    score += 0.3 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes define "usable" residual tiers.
    let pr = post_residual;
    let class = pr % 10;
    // Perfect-fill class gets the strongest reward.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows for residuals that cannot host typical items.
        // Classes 0 (exact tens) are most reusable; large odd remainders least reusable.
        let class_bonus: f64 = match class {
            0 => 12.0,
            1 | 9 => -6.0,
            2 | 8 => 2.0,
            3 | 7 => -3.0,
            4 | 6 => 4.0,
            _ => -4.0,
        };
        score -= class_bonus;

        // Harmonic tier via integer division: residual in [0,10) tiny, [10,20) small, etc.
        let tier = pr / 10;
        score -= (tier as f64) * 1.5;

        // Reward residuals that can host the lookahead item (coupling via modulo).
        if next_item_size > 0 && pr >= next_item_size {
            score -= 8.0;
            // Extra harmony if lookahead also lands on a good class boundary.
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else if next_item_size > 0 {
            score += 5.0; // dead space relative to lookahead
        }

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Penalize wasting a nearly-empty bin's potential when many bins are open.
        if pr > 60 {
            score += (pr - 60) as f64 * 0.3;
        }

        // Slight preference for tighter bins as stream progresses (first-fit-decreasing flavor).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 3.0 - (mean_residual - pr as f64) * 0.05;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big lookahead: fresh bin is attractive
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // tiny dead space: worse than leaving a moderately large gap
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 3.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits generally (post_residual small relative to item size)
    score -= (item_size as f64) * 0.15;

    // Lookahead: if the next item fits exactly into the post residual, reward heavily
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the gap -> the residual becomes dead space
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, growing with number of open bins
        score = bin_capacity as f64 * 0.8 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            // forced: no alternative
            score -= 100.0;
        } else if fitting_bins_count == 1 && item_size >= 60 {
            // large item with only one fitting bin: prefer that bin over new bin
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            // big next item: a fresh bin is valuable
            score -= 35.0;
        }
    }

    // Mild alignment with mean residual: prefer bins below the mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit relative to mean residual across open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item, or can host it afterwards.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: item + next item exactly fill the bin.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: good chaining, closer match is better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.3 * slack;
        } else {
            // Next item cannot fit: penalize leaving awkward dead space,
            // worse when the leftover is small (unusable).
            let leftover = next_item_size - post_residual;
            if leftover < 10 {
                score += 25.0; // tiny unusable gap
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize near-full leftovers that are small and hard to reuse,
    // scaled by how full the stream already is.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (0.5 + progress);
    }

    // Mild preference to keep the fleet of open bins consolidated
    // when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when nothing reasonable exists.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += post_frac * post_frac * 40.0;

    // Strongly reward near-perfect packing (post_residual small).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize leaving large dead space (unusable gap) more than linearly.
    if post_residual > 0 && post_residual < 10 {
        // small dead space is fine
    } else if post_residual >= 10 {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward;
    // if next item can't fit in post residual but would fit a fresh bin, penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 20.0;
        } else if (next_item_size as u32) <= bin_capacity {
            let waste_next = post_residual as f64;
            score += 0.05 * waste_next;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large for future items); late in stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 25.0 + 35.0 * progress;
        // But if no open bin fits at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early stream: fresh bin attractive if mean residual of open bins is low.
        score -= (1.0 - progress) * 15.0 * (mean_residual / bin_capacity as f64);
    } else {
        // Existing bin: slight preference for bins below mean residual (consolidate emptier bins).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Penalize many open bins slightly to encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = norm_pr.powi(2) * 40.0 + norm_pr * 60.0;

    // Smooth stream-progress coupling: later in stream, penalize large residuals more
    score += (1.0 + progress * 3.0) * norm_pr.powi(2) * 50.0;

    // Interaction: post_residual vs mean residual — avoid outliers far from mean
    let dev = (pr - mean_residual) / cap;
    score += dev.abs().powi(2) * 30.0;

    // Perfect fit reward (smooth, non-linear)
    if post_residual == 0 {
        score -= 100.0;
    } else {
        score -= 100.0 * (-((cap - pr) as f64) / 10.0f64).exp() * 0.0;
    }

    // Reward tight fits: small post residual relative to capacity
    score -= (1.0 - norm_pr).powi(4) * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening a new bin when existing bins fit well (smooth)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = cap - item_size as f64;
        score += 25.0 + waste * 0.5 + progress * 30.0;
        // If next item could use remaining space of new bin, soften penalty
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + (next_item_size as f64 / cap) * 20.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual bucketed by capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Perfect fit reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead-space penalties by harmonic class
    if pr > 0 && pr < 10 {
        score += 60.0; // unusable sliver
    } else if pr >= 10 && pr < quarter {
        score += 15.0;
    } else if pr >= quarter && pr < half {
        score -= 5.0;
    } else if pr >= half {
        score -= 20.0; // roomy bin still valuable
    }

    // Modulo-10 harmonic classes of post_residual (item sizes often multiples of 10)
    let m10 = (pr % 10) as f64;
    score -= (10 - m10) / 10.0 * 8.0; // prefer residuals that align with 10-grid

    // Lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or well
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 - slack * 0.3;
            if pr == next_item_size {
                score -= 200.0; // chain exact fit
            }
        } else {
            // next item won't fit here: penalize less if residual still useful generally
            score += 10.0;
            if pr < 10 {
                score += 40.0;
            }
        }
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; cheaper late when many bins already open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 120.0 - 40.0 * progress;
        // prefer new bin if existing residuals are all small/dead
        if mean_residual < 12.0 {
            new_bin_score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 20.0; // fresh bin helps bigger upcoming item
        }
        score = new_bin_score;
    }

    // Mild pressure to consolidate when many bins open
    score -= (open_bins_count as f64).ln() * 2.0 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 120.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 60.0;
    } else {
        // Moderate residual: mild reward for tighter fits.
        score -= (post_residual as f64) * 0.15;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // lookahead can still fit here
        } else if post_residual > 0 {
            score += 25.0; // dead space relative to next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Brand-new empty bin candidate: penalize opening unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is acceptable if mean residual is small (bins nearly full).
        score -= mean_residual * 0.8;
    } else {
        // Slight preference for bins below average fill (balance avoidance of
        // many half-empty bins) but keep dead-space rule dominant.
        let diff = (bin_residual as f64) - mean_residual;
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 20.0;

    // 2-step lookahead: reward bins where the next item also fits the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact 2-step match is ideal: leftover after next item is minimal.
        let second_leftover = post_residual - next_item_size;
        score -= 15.0 - (second_leftover as f64) * 0.1;
        if second_leftover == 0 {
            score -= 10.0; // perfect 2-item packing
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leftover that is dead space
        // (too small for typical items, min size 1..100 unknown, use mid guess).
        if post_residual < 10 {
            score += 8.0; // unusable sliver
        } else {
            score += 4.0;
        }
    }

    // Compare against mean residual: bins already below-mean residual are
    // "nearly full" -> good to fill them further.
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer reusing open
    // bins unless the fit is poor; allow opening when post_residual is large
    // (item barely fits / would leave big usable space elsewhere).
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if placing here leaves a big flexible residual and no open bin
        // fits well, opening can win via the lookahead bonus.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate: fewer open bins preferred.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever fit another item (min size 1,
    // but small leftovers are unlikely to be useful in unknown distributions).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Bonus proportional to how well next item nests in leftover space.
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nest * nest;
        } else {
            // Next item cannot fit here; slight penalty proportional to gap.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer fuller bins among many open bins (best-fit style pressure).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fullness;

    // Global state coupling: when mean residual across bins is high, encourage
    // consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > item_size as f64 {
        score -= 2.0 * (mean_residual / bin_capacity as f64);
    } else {
        score += 3.0 * (1.0 - progress);
    }

    // New-bin candidate handling: an empty bin should only win when the item fits
    // poorly everywhere else. Penalize the empty bin moderately, scaled by progress.
    if bin_residual == bin_capacity {
        score += 14.0 + 10.0 * (1.0 - progress);
        // Exception: very large items relative to capacity prefer fresh bins early.
        if item_size as f64 > 0.7 * bin_capacity as f64 && progress < 0.5 {
            score -= 18.0;
        }
    }

    // Mild time pressure: as stream progresses, favor closing out bins tightly.
    score -= 3.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: as stream progresses, weight tightness more strongly
    score -= 25.0 * (1.0 - norm_pr) * progress;

    // Penalize dead space that is too small to be useful (non-linear valley)
    let deadness = norm_pr;
    score += 30.0 * deadness * (1.0 - deadness) * deadness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving space for the next item (smooth coupling)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            score -= 15.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 5.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins below mean residual (consolidation), smooth term
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and modulo 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: small nonzero residues are hard to fill later
    if post_residual > 0 {
        if r10 != 0 {
            score += 6.0;
        }
        if r25 != 0 {
            score += 3.0;
        }
        // Perfect harmonic classes: residuals divisible by 10 or 25 pair well
        if r10 == 0 {
            score -= 8.0;
        }
        if r25 == 0 {
            score -= 5.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin cleanly
        score -= 40.0;
    }

    // Exact-fill potential with lookahead item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // guaranteed perfect fit next step
        } else if next_item_size <= post_residual {
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 10.0; // lookahead keeps harmonic alignment
            }
            score += (nr as f64) * 0.2;
        } else {
            // lookahead cannot fit here: penalize wasting this bin's class
            score += 4.0;
        }
    }

    // Fraction-of-capacity thresholds via integer division on residual
    let q = post_residual / 25; // 0..4 quarter classes
    match q {
        0 => score += 12.0,  // tiny residual: likely dead space
        1 => score += 4.0,   // small residual
        2 => score -= 2.0,   // half-full: good class
        _ => score -= 6.0,   // roomy bin: keep flexible
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap_f);
        let bad_fit = if post_residual < bin_residual { 0.0 } else { 1.0 };
        score = cap_f - 20.0 * bad_fit - pressure * 4.0
            + (mean_residual - post_residual as f64).abs() * 0.1;
        if fitting_bins_count <= 1 {
            score -= 10.0; // no good alternative: opening fresh is fine
        }
    }

    // Mild stream-progression tilt: late in the stream, prefer tighter packs
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= t * 3.0 * (post_residual as f64 / cap_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the smallest
    // item are pure waste -> heavy quadratic penalty.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += (10.0 - post_residual as f64) * 8.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use the leftover; dead space likely.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing ones; opening new bins becomes more costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 2.0;

    // New-bin candidate handling: an empty bin should only win when the
    // item fits terribly everywhere else. Give it a mild handicap so it
    // loses against decent fits, but wins when open bins leave big gaps.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If mean residual of open bins is large, existing bins likely
        // absorb the item fine -> penalize new bin more.
        score += mean_residual * 0.3;
    } else {
        // Existing bin with residual close to mean is a "typical" choice;
        // slight preference to keep residual distribution homogeneous.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // If next item still fits after this placement, mild reward scaled by tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the upcoming item: penalize proportionally
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.35;
    }

    // Penalize post_residual far below mean residual (creating unusable small hole)
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.15;
    } else {
        score -= (post_residual as f64 - mean_residual) * 0.05;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0; // still allow new bin if it enables perfect next fit
        }
    }

    // Late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.10 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize large post_residual nonlinearly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * (post * post) / cap;

    // Reward near-perfect packing (small waste).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * nxt;
        } else {
            // Dead space penalty scaled by how much next item misses fitting.
            let miss = nxt - post;
            if miss > 0.0 && miss <= 20.0 {
                score += 0.4 * miss;
            } else {
                score += 8.0;
            }
        }
    } else {
        // Last item: maximize fill, minimize leftover.
        score -= 10.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let mean_r = mean_residual;
    if bin_residual < bin_capacity {
        // Existing bin: reward when mean residual is high (spread usage).
        score -= 0.05 * mean_r;
        // Penalize opening new bins when many bins already exist.
        score += 0.15 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize unless existing bins are badly fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_r / cap;
        score += 20.0 - 30.0 * fragmentation - 10.0 * progress;
        // Never open a new bin if a decent fit exists elsewhere.
        if fitting_bins_count > 0 && (item_size as f64) / cap > 0.7 {
            score += 15.0;
        }
    }

    // Time horizon: early in stream, be more willing to open bins / keep options;
    // late in stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * (1.0 - progress);

    // Small tie-breaker favoring bins with residuals close to item_size multiples.
    let ratio = (bin_residual as f64) / (item_size as f64).max(1.0);
    if (ratio - ratio.round()).abs() < 0.05 && ratio >= 1.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual, with non-linear growth (dead space grows superlinearly in cost)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: early on, tolerate waste; late, punish it harder
    score *= 0.6 + 0.8 * progress * progress;

    // Reward tight fits via smooth saturation (avoid hard thresholds)
    let tight = 1.0 - norm_pr;
    score -= 12.0 * tight * tight * tight;

    // Last-chance bonus: strongly favor using the only bin that fits (smooth)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in the post-residual, reward; else mild penalty (smooth)
    if next_item_size > 0 {
        let fits_next = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= 6.0 * (fits_next / cap);
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 8.0 * gap * gap;
    }

    // Crowd penalty: many open bins -> prefer consolidation (smooth in open_bins_count)
    score += 0.35 * (open_bins_count as f64).ln().max(0.0) * pr / cap;

    // Deviation from mean residual: smooth penalty for leaving outliers
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: make it attractive only when residuals are poor
    if bin_residual == bin_capacity {
        let waste_pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score = pr - 15.0 * waste_pressure * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 5ths
    let fifth = bin_capacity / 5; // 20
    let post_class = post_residual / fifth; // 0..=5
    score -= (5 - post_class.min(5)) as f64 * 3.0; // reward fuller bins

    // Dead-space penalty: tiny post_residual that is unusable (< 10 typical min)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item coupling: if next item fits perfectly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 60.0;
        } else if slack < 10 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - slack as f64 / post_residual as f64);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize moderately so lookahead bins win
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless current bins are quite full
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_fullness > 0.75 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 30.0 * (1.0 - mean_fullness);
        }
    }

    // Modulo-10 harmonic refinement of post_residual
    let m = post_residual % 10;
    if m >= 5 {
        score -= 2.0; // half-class residual is more reusable
    } else if m > 0 {
        score += 3.0; // awkward remainder
    }

    // Slight penalty for bin proliferation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Dead-space ratio penalty (nonlinear)
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    score += dead_ratio * dead_ratio * 40.0;

    // Pressure from number of open bins: prefer filling existing bins when many are open
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it unattractive unless open-bin options are terrible
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64) * 0.5;
        // but allow new bin if all open residuals are poor fits
        if fitting_bins_count >= 1 {
            let waste = (bin_residual - item_size) as f64;
            if waste > 50.0 {
                score -= 20.0;
            }
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit post-residual and post-residual is small, penalize
    if next_item_size > post_residual && post_residual < 10 {
        score += 25.0;
    }

    // Mean residual coupling: if this bin is tighter than average, prefer it
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild stream progression effect: later in stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: waste nothing
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0; // near-perfect fit, unusable sliver
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here afterwards: strong reward, scaled by tightness
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 150.0 + 100.0 * tightness;
        } else if post_residual >= next_item_size / 2 {
            // partial compatibility: mild reward
            score -= 30.0;
        } else {
            // post_residual too small for next item: penalize dead space
            score += 40.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Relative to mean residual: prefer bins tighter (less residual) than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when decent fitting bins exist,
    // but allow it early in the stream or when few bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = 250.0 * (1.0 - progress);
        score += waste_penalty;
        if fitting_bins_count > 0 {
            // an open bin fits: only open new bin if that fit would be very wasteful
            score += 120.0;
        }
    }

    // Slight preference for consolidating into fewer bins
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item exactly fits the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to leftover
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / (bin_capacity as f64);
        // If mean residual across open bins is small (bins are full-ish), opening is fine.
        score = 55.0 + 50.0 * avg_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin keeps flexibility; reduce slightly.
            score -= 10.0 * (1.0 - (next_item_size as f64) / (bin_capacity as f64));
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    // Time horizon: early in stream, prefer consolidating (penalize many open bins);
    // late in stream, pack greedily into any residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Dampen preference for bins far from mean residual (keep a balanced portfolio),
    // unless it's a very tight fit which we already rewarded.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
