pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 as capacity-fraction buckets
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    let class = (pr / 10) as f64; // integer division threshold tier

    // Reward post-residuals that form "harmonic" usable chunks (multiples of 10/20/25/50)
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 50 == 0 {
        score -= 35.0;
    } else if pr % 25 == 0 {
        score -= 22.0;
    } else if pr % 20 == 0 {
        score -= 18.0;
    } else if pr % 10 == 0 {
        score -= 10.0;
    } else {
        // penalize non-harmonic dead space proportional to residue
        score += residue * 0.6;
    }

    // Dead-space penalty scaled by tier: small tiers are less exploitable
    if pr > 0 && pr < 10 {
        score += 45.0; // unusable sliver
    } else if pr < 20 {
        score += 18.0;
    }

    // Lookahead coupling: does next item fit harmonically into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nx = next_item_size as f64;
            let nres = (pr - next_item_size) % 10;
            if nres == 0 {
                score -= 30.0; // next item chains perfectly
            } else {
                score -= 12.0 * (nx / cap);
            }
        } else {
            // next item won't fit here; penalize less if post_residual is still large
            score += 8.0 * (1.0 - (pr as f64) / cap);
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation into tight fits
    if open_bins_count > 4 {
        score += 0.15 * (open_bins_count as f64) * ((post_residual as f64) / cap);
    }

    // Mean-residual drift: if this bin's residual is far above mean, mildly discourage
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.05 * diff;

    // Early stream: slight preference for spreading (keep big residuals for big items)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * (post_residual as f64);

    // New-bin candidate: only attractive if no open bin yields a tight fit
    if bin_residual == bin_capacity {
        let tightness_penalty = if fitting_bins_count == 0 { -10.0 } else { 40.0 + 30.0 * (1.0 - progress) };
        score += tightness_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the smallest possible item (1) can't be "unusable" per se,
    // but empirically small residuals (< 20) are hard to fill.
    if post_residual < 20 && post_residual > 0 {
        score += 40.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = (open_bins_count as f64) / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins exist and fit is decent.
        let fit_quality = if next_item_size > 0 {
            // If next item fits in the new bin's residual alongside this item, it's more attractive.
            if next_item_size as f64 + item_size as f64 <= bin_capacity as f64 { 15.0 } else { 0.0 }
        } else { 0.0 };
        score += 30.0 + bin_pressure - fit_quality;
    } else {
        // Reward using existing bins when mean residual is high (bins are fragmented).
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
        // Lookahead: if next item fits into post_residual, bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // Penalize if post_residual is nonzero but smaller than next item (dead space for lookahead).
        if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0; // perfect 2-item closure
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            // Prefer placements leaving post2 small but usable
            if post2 <= 10 {
                score -= 400.0;
            } else {
                score -= 150.0 * (1.0 - post2 as f64 / post_residual as f64);
            }
        } else {
            // next item cannot use this residual: penalize dead space
            score += 80.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize very small unusable residuals (dead space), especially if no lookahead match
    if post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit style)
    score -= 0.6 * (mean_residual - bin_residual as f64);

    // Slight preference for filling nearly-full bins
    let fill_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fill_frac;

    // Late in stream: be more aggressive about closing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * fill_frac;

    // New-bin candidate (empty bin): penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && post_residual > 0 && next_item_size as f64 / post_residual as f64 > 0.9 {
            score -= 100.0; // opening fresh bin enables a near-perfect follow-up
        } else {
            score += 120.0 - 80.0 * big_item;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: prefer bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is generally bad unless
    // the current fit is poor. The base post_residual already penalizes it
    // heavily; add a mild extra penalty that grows with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * progress;
        // But if the item is large relative to capacity and mean residuals are low,
        // a fresh bin may be the right call — soften the penalty.
        let size_ratio = item_size as f64 / bin_capacity as f64;
        if size_ratio > 0.7 && mean_residual < size_ratio * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is especially valuable (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        }
        // Avoid leaving exactly a space that the next item can't use at all.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; favor consolidating into fuller bins.
    let mean_load = (bin_capacity as f64) - mean_residual;
    let bin_load = (bin_capacity as f64) - bin_residual as f64;
    if mean_load > 0.0 {
        score -= 10.0 * (bin_load / mean_load - 1.0).clamp(-1.0, 1.0);
    }

    // Mild time horizon effect: early in the stream, keep bins flexible
    // (prefer larger post_residual slightly); late in the stream, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear coupling to stream progress.
    // Early in the stream, keep bins flexible (larger residuals OK); late, pack tightly.
    let mut score = norm_pr * (1.0 + 0.6 * (1.0 - progress) * (1.0 - progress));

    // Non-linear penalty on very small post-residuals (dead space) weighted by progress.
    score += 0.35 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Smooth interaction: post_residual vs mean residual deviation.
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev - 0.1 * dev;

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 0.4 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - ((pr - ns) / cap).abs();
            score -= 0.25 * fit_quality * fit_quality;
        } else {
            score += 0.1 * progress;
        }
    }

    // Mild pressure against hoarding many open bins early.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin when it wastes capacity,
    // but reward it late in the stream if the item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        score += 0.5 - 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes capture typical size granularity.
    let post_class = post_residual % 10;
    // Dead-space penalty: residuals in awkward classes (1..9 non-zero small remainders) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_class == 1 || post_class == 2 {
        score += 8.0;
    }

    // Perfect fit reward via integer division thresholds.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: exact class match gets strong bonus.
            if next_item_size == post_residual {
                score -= 45.0;
            } else {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize more if we're wasting a scarce fitting bin.
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Capacity-fraction logic: bins below half full are valuable; keep large residuals cheap.
    let half = bin_capacity / 2;
    if bin_residual > half {
        score -= 5.0;
    }

    // Progress-aware new-bin handling: opening a fresh bin (residual == capacity) is
    // attractive when mean residual across open bins is small (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 && open_bins_count > 2 {
            score -= 12.0 * (1.0 - progress);
        } else {
            score += 10.0;
        }
    }

    // Mild pressure toward consolidating into already-open bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Small tie-breaker on tight fits (item nearly fills residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Medium dead space (10..30) is risky but partially usable; mild penalty.
    else if post_residual >= 10 && post_residual < 30 {
        score += 6.0;
    }

    // Reward very tight fits (post_residual small but zero is best).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Perfect-fill of a bin's residual is ideal.
    if post_residual == bin_residual.saturating_sub(item_size) && item_size == bin_residual {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new bins,
    // prefer filling existing ones (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = 8.0 + (open_bins_count as f64) * 2.5;
        score += pressure;
        // If this bin is the only fitting option, opening new bin is less bad.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // Early stream: allow some new bins to build a portfolio.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.15 {
            score -= 4.0;
        }
    } else {
        // Reward using bins that are already quite full (small residual before placement).
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor placing here to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the resulting post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by leaving a gap just below its size, penalize.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 5.0;
    }

    // Slight preference for bins with residual below the mean (tighter bins first).
    score += ((mean_residual - bin_residual as f64) * 0.1).max(-5.0).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual can still host next item: mild reward scaled by fit tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to wasted potential
        score += 5.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (resid - mean_residual);
    }

    // Last-chance bin bonus: avoid opening new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when decent fits exist, unless it enables a perfect lookahead chain
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0 && item_size + next_item_size == bin_capacity;
        if perfect_chain {
            score -= 30.0;
        } else {
            score += 12.0;
        }
    }

    // Penalize very small dead space (hard to reuse) but not zero
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Late in stream: consolidate, prefer tight fits even more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - resid) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
