            // reward leaving room exactly for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - (slack / (bin_capacity as f64)).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so open bins with decent fit win
        score += 10.0;
        // if item is large relative to mean residual, new bin becomes appealing
        let mean_gap = (item_size as f64) - mean_residual;
        if mean_gap > 0.0 {
            score -= 1.5 * mean_gap;
        }
        // early stream: encourage fewer bins? late stream: allow opening
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Prefer bins with residuals below mean (consolidate small leftovers)
    let dev = (bin_residual as f64 - mean_residual);
    score += 0.15 * dev;

    // Slight penalty for spreading across too many open bins when residual is large
    if post_residual > bin_capacity / 2 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling: quadratic in post_residual modulated by stream progress.
    // Early in the stream, large residuals are less costly (more items remain to fill them);
    // late in the stream, dead space is penalized more heavily.
    let dead_weight = 1.0 + 2.0 * progress * progress;
    score += dead_weight * 40.0 * pr_norm * pr_norm;

    // Cubic interaction: very large residuals late in the stream are strongly penalized.
    score += 30.0 * progress * pr_norm * pr_norm * pr_norm;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = (-pr_norm * 4.0).exp();
    score -= 12.0 * tightness * (1.0 + progress);

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gap_norm = gap / cap;
        score -= 8.0 * (-gap_norm * 6.0).exp();
        // Penalize if next item cannot fit in residual (bin becomes dead end for lookahead)
        if pr < nxt {
            score += 6.0 * progress * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to keep flexibility
        score += 2.0 * (fitting_bins_count.min(10) as f64 - 2.0);
    }

    // Mean residual coupling: placing into a bin whose residual is far below mean
    // (a "straggler" bin) helps consolidate open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current placements are poor.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let new_bin_penalty = 20.0 + 15.0 * progress + 3.0 * openness.sqrt();
        score += new_bin_penalty;
        // But if mean residual is very low (all bins nearly full), opening a bin is fine.
        let mean_norm = mean_residual / cap;
        score -= 25.0 * (-mean_norm * 8.0).exp();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: prefer residuals that are "nice" multiples / small classes
    let post = post_residual;
    let cls = post % 10; // harmonic class modulo 10
    score += match cls {
        0 => -8.0,          // perfectly divisible residual: very reusable
        5 => -4.0,          // half-class: decent
        2 | 4 | 6 | 8 => -1.5, // even classes: moderately reusable
        _ => 3.0,           // odd classes: dead-space risk
    };

    // Integer-division thresholds on post_residual: chunk analysis
    let chunk = post / 20; // 0..5 chunks of size 20
    score -= chunk as f64 * 2.0;

    // Reward tight fits (small post residual)
    if post <= 5 {
        score -= 12.0;
    } else if post <= 10 {
        score -= 6.0;
    } else if post > 40 {
        score += 4.0; // large leftover dead space penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item can fit exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size <= post {
            score -= 4.0;
            // harmonic check: post % next_item_size small remainder
            let r = post % next_item_size.max(1);
            score -= (10 - r.min(10)) as f64 * 0.5;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate handling: neutral-ish score so we only open when fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.1;
        if next_item_size > 0 && next_item_size <= post {
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            // a real last-chance bin exists; make new bin less attractive
            score += 10.0;
        }
        return score;
    }

    // Progress-aware pressure: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post as f64 / cap) * 6.0;

    // Penalize bins far from mean residual (fragmentation avoidance)
    let dev = (post as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small bonus for using fuller bins (best-fit flavor)
    score -= (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0; // worst for gap=1
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 6.0 + 20.0;
    } else {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item can't use the gap -> dead space likely
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Mild penalty for bins far below mean residual (fragmentation avoidance).
    if bin_residual != bin_capacity {
        score += ((mean_residual - bin_residual as f64).abs()) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exhaustive fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size (perfect chain), penalize near-miss dead space.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < f64::EPSILON {
            score -= 600.0;
        } else if post_residual >= next_item_size {
            let diff = post_residual as f64 - next;
            // Smaller leftover after a hypothetical next placement is better.
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
            // Penalize if the next item leaves a hard-to-fill sliver.
            let post2 = diff;
            if post2 > 0.0 && post2 < 10.0 {
                score += 80.0;
            }
        } else {
            // Next item cannot fit here; slight penalty proportional to gap.
            score += 40.0 + (next - post_residual as f64) * 0.5;
        }
    } else {
        // Last item: prefer minimal residual.
        score -= 200.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Early in stream: be more willing to spread into new bins (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized when many bins are open
        // and the stream is late (consolidation phase).
        score += 120.0 * progress + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 30.0; // fresh bin can always chain the next item
        }
    }

    // Prefer filling bins with larger current residual (big item into big gap).
    score -= 0.3 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * tightness * tightness * (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize dead space: post_residual too small for the smallest plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else {
            // penalize wasting space the next item could have used elsewhere
            score += 5.0;
        }
        // If next item is big, prefer conserving roomy bins
        if next_item_size >= 50 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer filling fuller bins
    score += 0.3 * (mean_residual - post_residual as f64);

    // Slight penalty on opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 50.0;
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).min(5.0);
        }
        // late in stream, opening new bins is more acceptable (avoid fragmentation)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
        // If next item is huge and this item is small, a fresh bin is attractive
        if next_item_size >= 60 && item_size <= 20 {
            score -= 20.0;
        }
    }

    // Prefer bins with residuals near multiples that pair well with common sizes
    let r = post_residual as f64;
    if r >= 10.0 {
        let frac = (r / 10.0) - (r / 10.0).round();
        score += 3.0 * frac.abs();
    }

    // Mild preference to use fewer open bins overall
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    let mut score = poly * cap;

    // Reward tight fits (low post_residual) more strongly later in the stream
    score -= (cap - pr) * (0.15 + 0.25 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 0.2 * (pr - nxt).min(20.0);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Coupling with mean residual: prefer bins near the mean
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
