pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (min item size 1, but practically small gaps) are waste.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0; // heavy penalty for unusable slivers
    }

    // Penalize moderate gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Reward bins whose post_residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many open bins unless
    // this placement is a tight fit.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64;
        score += 5.0 + tightness * 0.3; // default penalty; low post_residual elsewhere wins
    }

    // Mild stream-progression bias: later in the stream, prefer tighter packs.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.4;

    // Deviation from mean residual: prefer bins that are already fuller than average.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item size
    if next_item_size > 0 {
        let mismatch = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * mismatch;
        if post_residual == next_item_size {
            score -= 15.0; // perfect 2-step chain
        }
        // penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual waste elsewhere
    if bin_residual == bin_capacity {
        score += 25.0;
        // allow new bin if item is big and no open bin would be tight
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize very small dead residuals (wasted space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that few future items can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { (post_residual as f64).powf(1.3) };
        score += 0.15 * dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Lookahead: bonus if next item can fit into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
        // Chain packing: residual + next fits exactly or leaves small waste
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after == 0 { score -= 25.0; }
        }
    }

    // New-bin candidate handling: only open a new bin when current bin would
    // leave a large awkward gap or when many bins are already open and tight.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // new empty bin baseline: prefer it only if item is large relative to capacity
        score = 100.0 - 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0; // large item: fresh bin is fine
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // room for chaining in fresh bin
        }
    } else {
        // Discard open bins when item fits almost exactly anyway; discourage
        // opening new bins when a decent fit exists.
        if fitting_bins_count > 0 {
            score += 10.0; // mild bias against new bin when alternatives exist
        }
    }

    // Global state coupling: many open bins -> consolidate; few -> flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins deviating below mean (tighter bins)
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Early stream: keep residuals balanced for future flexibility.
    score += (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer minimal post residual (tight packing), scaled non-linearly.
    let mut score = (pr / cap).powi(2) * 100.0;

    // Smooth interaction: as stream progresses, tighten tolerance for leftover space.
    score += 30.0 * (pr / cap) * (0.5 + progress);

    // Dead-space penalty: very small post residual (< next item) is wasted space.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 25.0 * gap * (1.0 + fit_ratio);
    } else if next_item_size > 0 {
        // Reward bins that can also host the lookahead item (smooth coupling).
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening a bin unless residuals are fragmented/high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).powi(2);
        score = 55.0 + 45.0 * fragmentation - 20.0 * progress;
        // Still allow opening when the item is large and would leave tiny waste elsewhere.
        if fit_ratio > 0.7 { score -= 30.0 * (fit_ratio - 0.7); }
    }

    // Mild pressure to consolidate: fewer open bins relative to progress is better.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals divisible by common item sizes
    let pr = post_residual as u32;
    for &m in &[10u32, 20, 25, 50] {
        if pr >= m && pr % m == 0 {
            score -= 6.0;
        }
    }
    // Penalize dead-space classes: residuals in awkward ranges (1..10)
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Fraction-of-capacity thresholds on post_residual
    let frac = post_residual as f64 / cap;
    if frac < 0.1 {
        score += 8.0; // nearly-full bin: good, but only if it was a tight fit
    }
    if frac > 0.6 && frac < 0.75 {
        score -= 3.0; // leaves room for medium items
    }

    // Lookahead coupling: does next_item_size fit the post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // exact harmonic match: post_residual is a multiple of next size
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Integer division thresholds: post_residual / next_item_size
    if next_item_size > 0 {
        let k = post_residual / next_item_size;
        if k >= 2 {
            score -= 2.0 * (k.min(3) as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize opening when
    // mean residual across open bins is still large
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.5 + (open_bins_count as f64) * 0.3;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing fits: must open
        }
    } else {
        // Mild preference for tighter bins as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += frac * 10.0 * (1.0 - progress);
    }

    // Penalize bins far below mean residual (fragmentation avoidance)
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (or the lookahead item) are wasted.
    let min_useful = if next_item_size > 0 && next_item_size <= bin_capacity {
        next_item_size
    } else {
        10
    };

    if post_residual > 0 && post_residual < min_useful {
        // Unusable gap: penalize proportionally to how much space is wasted,
        // scaled by stream progression (late waste is worse).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 30.0 * progress + (min_useful - post_residual) as f64 * 0.5;
    }

    // Reward very tight fits (post_residual near zero is fine if it's a real fill).
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as i64) < (min_useful as i64) / 2 {
        score -= 15.0;
    }

    // If this bin is the last chance to avoid opening a new bin, reward it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already below mean (consolidate small residuals).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    // New-bin candidate handling: an empty bin is attractive only if the item
    // is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 20.0; // large item: fresh bin is fine
        } else if fitting_bins_count > 0 && post_residual >= min_useful {
            score += 35.0; // an open bin could take it decently: penalize new bin
        } else {
            score += 5.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 60.0 + (fitting_bins_count as f64) * 12.0;
        // If next item is large, opening fresh is cheaper.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 35.0;
        }
        return score;
    }

    // Aggressive 2-step lookahead: reward exact / near-exact match with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = post - next;
        if diff == 0.0 {
            score -= 80.0; // perfect 2-chain
        } else if diff > 0.0 {
            // next item fits after this one: reward tighter packing
            score -= (30.0 * next / bin_capacity as f64) - diff * 0.15;
        } else {
            // dead space relative to next item: penalize proportionally
            score += (-diff) * 0.9;
        }
    }

    // Reward tight fits relative to mean residual.
    let mean = if mean_residual > 0.0 { mean_residual } else { 1.0 };
    if (post_residual as f64) < mean {
        score -= (mean - post_residual as f64) * 0.4;
    } else {
        score += (post_residual as f64 - mean) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && post_residual <= 20 {
        score -= 45.0;
    }

    // Penalize very small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 100.0; // perfect closure
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: square the post-residual for emphasis.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space relative to next size.
            score += 0.5 * (nxt - pr) / 100.0;
        }
    } else {
        // Last item: minimize post-residual aggressively.
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: mild penalty to break ties toward best fit only.
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize the new-bin candidate (bin_residual == bin_capacity) unless item is huge
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = 1.0 - (mean_residual / bin_capacity as f64);
        let big_item = (item_size as f64) / bin_capacity as f64;
        score += 12.0 - 10.0 * pressure - 6.0 * big_item;
    } else {
        // Reward using existing bins, scaled by how much residual they still hold.
        score -= 1.5 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: late in the stream, consolidate harder into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with large mean residual -> discourage spreading;
    // few open bins -> slightly favor opening new bins for large items.
    if open_bins_count > 0 {
        let avg = mean_residual / open_bins_count as f64;
        let spread = (bin_residual as f64 - avg).abs();
        score += 0.05 * spread;
        score -= 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual < 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth penalty for very small post residual (dead space) via polynomial term
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Reward tight fits more strongly later in the stream
    score -= 20.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus (only fitting bin): smooth exponential-like polynomial
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits the post residual (smooth)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64) / pr.max(1.0);
        score -= 12.0 * fit_quality * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // penalize leaving residual that cannot host next item
        score += 8.0 * progress;
    }

    // Mean residual coupling: prefer bins close to mean residual (smooth quadratic)
    let dev = norm_pr * cap - mean_residual;
    score += 0.02 * dev * dev / cap;

    // Mild penalty for opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it lives in
    let frac = item_size as f64 / cap; // 0..1
    let harmonic_class = (frac * 10.0).floor() as i64; // 0..9

    // Post-residual harmonic class: dead-space quality after placement
    let post_frac = post_residual as f64 / cap;
    let post_class = (post_frac * 10.0).floor() as i64;

    // Reward placements whose post-residual is a "good" harmonic class
    // (residuals near 0, or in bands known to absorb common item sizes)
    match post_class {
        0 => score -= 25.0,               // near-perfect fill
        1 => score -= 18.0,
        2 => score -= 12.0,
        3 => score -= 8.0,
        4 => score += 3.0,                // awkward mid-band dead space
        5 => score += 5.0,
        6 => score += 4.0,
        7 => score -= 2.0,
        8 => score -= 6.0,                // large residual still usable
        _ => score -= 4.0,
    }

    // Exact modulo match: post_residual divisible by common small sizes
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        else { score += 1.5; }
    }

    // Lookahead coupling: does the next item fit the post-residual exactly or well?
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0; // perfect chain
        } else if slack <= 10 {
            score -= 15.0;
        } else {
            score -= (slack as f64).sqrt() * 2.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize wasting this bin's future
        score += 6.0;
        if post_residual < 10 {
            score -= 4.0; // but tiny dead space is fine
        }
    }

    // Last-chance bin bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when all open bins look bad; scale pressure with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.85 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere, must open
        }
        if next_item_size > 0 && (next_item_size as u32) <= bin_residual {
            score -= 5.0;
        }
        return score;
    }

    // Prefer tighter existing bins: closeness of fit reward
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 10.0;

    // Mild penalty when bin diverges from mean residual (keep bins uniform)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream consolidation: fewer open bins preferred as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (open_bins_count as f64).ln().max(1.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small to fit any plausible item (min size 1..100 unknown,
    // but treat gaps < 10 as near-dead, gaps < 20 as risky).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small relative post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.5 * tightness * tightness * (bin_residual as f64);

    // Penalize creating a gap that exactly fails to fit the lookahead item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }
    // Reward bins whose post_residual still accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strong discount to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins;
    // make the new-bin candidate (full residual) less attractive as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.2 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (filling emptier bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect two-step match: item + next item exactly fills the bin.
        let two_step = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - two_step).abs() < 0.5 {
            score -= 1000.0;
        }
        // Post residual exactly equals next item: ideal follow-up placement.
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Next item fits in the post residual: good chaining.
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight chains, but dead space below next size is wasted.
            score -= 40.0 - slack.min(40.0);
        } else {
            // Post residual is a dead pocket smaller than the next item.
            score += 60.0 + post_residual as f64 * 0.5;
        }
    }

    // Exact fill is always excellent.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual < 10 {
        // Small unusable pocket (min item size is 10 under classic regime,
        // but sizes may go to 1): penalize proportionally.
        score += 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Mild preference for reusing bins when many are open (consolidation).
    score += open_bins_count as f64 * 0.05;

    // Late in the stream, avoid leaving scattered residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.4;

    // Never prefer opening a new bin when this bin would be nearly filled.
    if bin_residual == bin_capacity {
        score += 15.0; // slight bias against new bins unless lookahead is bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers matter more.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += tightness * 30.0;

    // Penalize large dead space if the leftover can't fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / bin_capacity as f64) * 5.0;
        } else {
            score += 4.0; // leftover too small for lookahead item: dead space risk
        }
    }

    // Last-chance bonus: only this bin fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Global residual pressure: if mean residual is high, favor bins below mean
    // (drain the laggards), otherwise prefer bins above mean.
    let delta = mean_residual - bin_residual as f64;
    score += delta * 0.15;

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, aggressively fill whatever is available.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more strongly when alternatives exist
        // and when the item is small relative to capacity.
        score += 18.0
            + (fitting_bins_count as f64) * 4.0
            + (bin_capacity - item_size) as f64 * 0.1;
        // But if no other bin fits, opening is inevitable: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Early stream with large item: opening fresh bins is fine.
        if progress < 0.2 && item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized quantities
    let pr = post_residual as f64 / cap;              // post-residual in [0,1)
    let progress = step_index as f64 / total_items as f64;
    let fit = fitting_bins_count as f64;

    // Non-linear polynomial coupling: waste grows super-linearly with
    // small post-residual, modulated by stream progress.
    let tightness = (1.0 - pr).powi(3);               // near 1 when bin almost full
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize mid-range dead space with a quadratic bump centered around 0.4
    let bump = pr * (1.0 - pr);
    score += 8.0 * bump * bump * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).sqrt() * 0.5 * (pr - mean_residual / cap).abs();

    // Lookahead: reward if next item fits into resulting post-residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual as f64 >= ni {
            score -= 10.0 * (1.0 - ni / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 4.0 * (ni / cap) * (1.0 - progress);
        }
    }

    // Slight preference for keeping residual divisible-friendly (smooth term)
    score += 2.0 * ((pr * std::f64::consts::PI).sin() * 0.5 + 0.5) * bump;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let r = post_residual;
    let r_mod = r % 10;
    // Dead-space classes: residuals that are nearly useless (1..=9 but small)
    if r > 0 && r < 10 {
        score += 12.0; // tiny unusable sliver
    }
    // Perfect fit reward: post_residual zero or exactly matching next item
    if r == 0 {
        score -= 25.0;
    }
    if next_item_size > 0 && r == next_item_size {
        score -= 30.0; // lookahead perfect fit
    }
    // Harmonic quarter classes of capacity fraction
    let frac = r as f64 / bin_capacity as f64;
    let quarter = (frac * 4.0).floor() as i32; // 0..3
    match quarter {
        0 => score += 8.0,      // <25% left: nearly full bin, good
        1 => score += 2.0,
        2 => score -= 1.0,
        _ => score -= 3.0,      // >75% left: mostly empty bin
    }
    // Penalize residuals that cannot fit the next item but are moderately large
    if next_item_size > 0 && r > 0 && r < next_item_size {
        score += (next_item_size - r) as f64 * 0.3;
    }
    // Reward if post_residual still fits next item (keeps bin useful)
    if next_item_size > 0 && r >= next_item_size {
        score -= 6.0;
    }
    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate handling: make it attractive only when fit is poor
    if bin_residual == bin_capacity {
        // opening a new bin costs a fresh bin; penalize unless current fit is bad
        score += 10.0 + mean_residual * 0.05;
        if next_item_size > 0 && item_size <= 20 {
            score -= 5.0; // small items fine anywhere; prefer filling open bins
        }
    }
    // Integer-division harmonic: post_residual / item_size ratio
    if item_size > 0 {
        let div = r / item_size;
        score -= div as f64 * 1.5; // reward bins that could take more copies of this item
    }
    // Progress modulation: late in stream, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;
    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive if no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if fitting_bins_count == 1 {
            score += 20.0;
        } else {
            score += 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: prefer bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Late in stream: consolidate; early: allow some spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.1 * (1.0 - progress);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: post_residual too small for any future item
        if post_residual < 10 {
            score += 200.0;
        }
    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits here afterwards: mild reward proportional to tightness
            score -= 100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize proportional to overshoot
            score += 50.0 + 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose remaining space
    // stays near the average (balanced packing), penalize outliers
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable fit
    if bin_residual == bin_capacity {
        score += 150.0;
        // allow new bin early in stream or when very few bins open
        if open_bins_count < 2 || (total_items > 0 && (step_index as f64) / (total_items as f64) < 0.1) {
            score -= 120.0;
        }
    }

    // Slight preference for tighter bins overall
    score += 0.3 * (bin_capacity - bin_residual) as f64 * -0.0; // no-op guard
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: post residual that is too small to ever be useful
    // (assume min item size ~1, but typical items larger; penalize residuals below 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // New bin attractive if item is large and fits badly elsewhere
        score += 15.0 + 30.0 * (1.0 - fit_ratio);
        if fitting_bins_count > 0 && post_residual >= 0 {
            // discourage new bin when a reasonable fit exists
            let best_possible_waste = fitting_bins_count as f64;
            score += 10.0 * (1.0 / best_possible_waste.sqrt());
        }
        // Late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if next item could use this bin's post residual, reward leaving room
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 12.0;
        } else if post_residual > 0 {
            // post residual too small for next item: mild penalty proportional to waste
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Global state: many open bins with high mean residual -> consolidate, avoid new bins
    let residual_pressure = mean_residual / bin_capacity as f64;
    score += residual_pressure * (open_bins_count as f64) * 2.0;
    if is_new_bin {
        score += open_bins_count as f64 * residual_pressure * 5.0;
    }

    // Favor bins that are already fairly full relative to mean
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Time horizon: early stream, be more exploratory (less penalty for new bins);
    // late stream, pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: early in the stream, tolerate larger residuals slightly more
    score *= 1.0 - 0.15 * progress * (1.0 - norm_pr);

    // Penalize dead space that no plausible next item can use (lookahead coupling)
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let waste = (pr - nx).max(0.0);
        let unusable = if pr < nx { 1.0 } else { 0.0 };
        score += 6.0 * unusable * (1.0 - progress) * (pr / cap);
        score -= 4.0 * (1.0 - waste / cap) * (pr / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Mild pressure toward consolidating into fewer bins
    score += 0.5 * (open_bins_count as f64) * norm_pr;

    // Slight preference relative to mean residual state
    score -= 0.3 * (mean_residual - pr) / cap;

    // New-bin candidate: empty bin gets a smooth opening penalty unless stream is early
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - 0.6 * (1.0 - progress)) + 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 for perfect fit, 1.0 for untouched bin

    // Penalize residual classes that are hard to fill: small nonzero leftovers.
    // Classes: (0,10] near-perfect (good), (10,30] awkward (bad), (30,50] medium, >50 still usable.
    if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly favored
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score += 18.0; // awkward dead zone
    } else if post_residual <= 50 {
        score += 4.0;
    } else {
        score -= 3.0; // large residual keeps flexibility
    }

    // Harmonic coupling: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 && post_residual > 0 {
        let n = next_item_size;
        if n == post_residual {
            score -= 15.0; // exact pairing
        } else if post_residual % n == 0 {
            score -= 8.0; // divides evenly: harmonic class match
        } else if n <= post_residual {
            let rem = post_residual % n;
            if rem <= 10 {
                score -= 4.0;
            } else if rem <= 30 {
                score += 6.0;
            }
        } else {
            score += 10.0; // next item cannot use this bin's leftover at all
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score += 30.0 * (1.0 - crowding);
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits: new bin is necessary
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Mild bonus for tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * tightness;

    // Slight preference to fill bins below mean residual (balance avoidance of stranded space).
    score += 0.15 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1, but
    // realistically >= 10) can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps (10..=20) are usable only by small items; penalize moderately
    // unless the lookahead item can actually use them.
    if post_residual >= 10 && post_residual <= 20 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    }

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 80.0;
    } else {
        // Fractional waste relative to capacity; tight fits get big discount.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness;
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when open bins are fragmented
    // (high mean residual spread) or this is a poor fit situation.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 * 0.5)).abs();
        score += 20.0 * open_bins_count as f64;
        score -= fragmentation;
        // Prefer new bin late in the stream when many bins are nearly full.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
    } else {
        // Prefer filling existing bins whose residual is close to mean (balance).
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

