        score += exact * 0.8;                       // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 30.0;                          // perfect two-item pairing
        }
        // Chain feasibility: if next item also fits after this placement, reward.
        if next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    // Compare bin residual to mean residual: prefer bins that will be "tightened".
    let mean_diff = bin_residual as f64 - mean_residual;
    score += mean_diff * 0.15;                      // prefer fuller-than-average bins

    // Penalize creating small unusable dead space (below typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral residual equals capacity; discourage unless open bins are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        // allow new bin late in stream when residuals are large and fragmented
        if mean_residual > 40.0 {
            score -= 15.0;
        }
    }

    // Slight early-stream preference for opening bins (spread items), later consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

