    score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space that is too small to be useful (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Reward bins whose residual becomes "perfect" for the known next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bonus: only bin that fits; avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins fit, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64).max(1.0);
        score += 30.0 + 25.0 * progress - 10.0 / pressure;
    }

    // Prefer bins deviating from the mean residual (better consolidation).
    score += 0.35 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for fuller bins as stream matures.
    score -= progress * 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild penalty on bin proliferation: keep packing into existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
