    // Aggressive 2-step lookahead: reward when post_residual chains with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills leftover -> strong reward.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Closer match = bigger reward, scaled by tightness.
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit here: penalize wasted potential.
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.2;
    }

    // Tight fits are good: reward small post_residual relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating dead space below the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 1 {
        score += 50.0;
    }

    // Compare against mean residual: prefer bins that are already more filled
    // (post_residual below mean) to consolidate waste.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened when many items remain
        // and current open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = mean_residual / bin_capacity as f64;
        score = 70.0 + 30.0 * progress - 20.0 * crowding;
        // If lookahead chains perfectly with a fresh bin, allow it.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward very tight fits (small leftover) non-linearly.
    score -= 40.0 / (post_residual as f64 + 2.0);

    // Dead-space penalty: leftover too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0 + 0.25 * (post_residual as f64);
    }

    // Lookahead synergy: next item fits into the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.1 * (next_item_size as f64);
    }

    // Last-chance bonus: this is the only bin that can host the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many open bins slightly when residual is plentiful.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 2.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default mild penalty: prefer reusing open bins with decent fits.
        score += 6.0;
        // But if the item barely fits the average open residual, opening a
        // fresh bin avoids fragmenting a nearly-full bin.
        if (item_size as f64) > mean_residual - 5.0 {
            score -= 12.0;
        }
        // Late in the stream, avoid opening bins that will be wasted.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.9 {
            score += 10.0 * progress;
        }
    }

    // Time-horizon modulation: early on, be greedy for tight fits;
    // later, be more conservative about tiny residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping.
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: as the stream progresses, dead space becomes more costly.
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 25.0 * progress_coupling * norm_pr;

    // Penalize residuals that cannot fit the next item (smooth via ratio).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let deficit = (nxt - pr) / cap;
            score += 40.0 * deficit * deficit * cap;
        } else {
            // Reward post-residual that closely matches next item (tight lookahead fit).
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack.min(1.0));
        }
    } else {
        // Last item: strongly favor filling bins completely.
        score -= 50.0 * (1.0 - norm_pr);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits even more.
        score += 5.0 * (fitting_bins_count as f64).ln() * norm_pr;
    }

    // Mean-residual coupling: placing into a bin below mean residual reduces spread.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * cap;
    score -= 8.0 * (mean_residual - pr) / cap * (1.0 - progress);

    // Mild penalty for proliferating bins early.
    score += 2.0 * (open_bins_count as f64).sqrt() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals that are "harmonically useful"
    // (divisible by common item sizes 10,20,25,50) are less dead.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 { 0.0 }
        else if pr % 50 == 0 { 15.0 }
        else if pr % 25 == 0 { 10.0 }
        else if pr % 20 == 0 { 8.0 }
        else if pr % 10 == 0 { 5.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Penalize small dead space that nothing (min size 10... but interface says 1..100) can use:
    // tiny residuals (1..=5) are near-useless -> strong penalty.
    if pr > 0 && pr <= 5 {
        score += 60.0;
    } else if pr > 5 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward keeping room for the next item, scaled by tightness
            let tight = (pr - next_item_size) as f64;
            score -= 25.0 + 20.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize by overflow amount
            score += 10.0 + 0.5 * (next_item_size - pr) as f64;
        }
        // Harmonic match: next_item_size divides pr exactly -> great
        if pr > 0 && next_item_size > 0 && pr % next_item_size == 0 && next_item_size <= pr {
            score -= 20.0;
        }
    } else {
        // last item: prefer filling largest residual least? Actually prefer tightest fit overall
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented
    if bin_residual == bin_capacity {
        // baseline preference for reusing bins: empty bin gets a penalty...
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // ...unless existing bins are highly fragmented late in the stream
        score += 55.0 - 45.0 * fragmentation * (0.5 + 0.5 * progress);
        // if item is large relative to capacity, opening fresh bin is safer
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild preference for bins below mean residual (tighter bins) to consolidate
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold on post_residual quarters
    let quarter = pr / (bin_capacity / 4).max(1);
    score -= quarter as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 40.0;
    }
    // Harsher penalty for gaps below typical small item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead space relative to capacity: nonlinear penalty for wasted fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize if post residual would strand the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Deviation from mean residual: prefer bins that reduce residual variance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // New-bin candidate: penalize mildly so it is chosen only when fits are poor,
    // but relax pressure late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual EXACTLY matches the next item size (perfect chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus scaled by next item size
        let match_bonus = (next_item_size as f64 / 80.0) * (30.0 / (1.0 + diff * 0.5));
        score -= match_bonus;

        // Penalize leaving dead space that neither fits next item nor is small
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.6;
        }
        // Bonus for exact zero-fill
        if post_residual == 0 {
            score -= 25.0;
        }
    } else {
        // Last item: strongly prefer exact fill
        if post_residual == 0 {
            score -= 40.0;
        }
        score += post_residual as f64 * 0.3;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Small penalty for spreading across many open bins when few fit
    if fitting_bins_count > 1 {
        score += fitting_bins_count as f64 * 0.4;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // no open bin offers a good fit (post_residual too small relative to item).
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count > 0 && (post_residual as f64) > mean_residual * 0.9;
        if poor_fit {
            score -= 15.0; // open fresh bin when fits would leave big dead space
        } else {
            score += 18.0; // discourage wasteful new bins
        }
    }

    // Mild stream-progression pressure: tighten packing as stream advances
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: post_residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if next item fits exactly in the post residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can follow here: good chain
            score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else if next_item_size <= bin_residual {
            // next item fits in bin now but not after this placement: slight penalty
            score += 3.0;
        }
        // dead space blocking the next item
        if post_residual > 0 && post_residual < next_item_size {
            score += 2.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bin; relax penalty as stream progresses or many bins open
        let mut new_bin_penalty = 20.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0; // no alternative
        } else if open_bins_count > 4 {
            new_bin_penalty -= 4.0;
        }
        score += new_bin_penalty * (0.5 + 0.5 * (1.0 - progress));
    }

    // Global state coupling: prefer bins below mean residual (keep balance, save fat bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins with less residual overall when many bins open
    score += 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: late in stream, prioritize compactness more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    let mut score = post;

    // Smooth non-linear waste penalty: quadratic in normalized post residual
    score += 12.0 * post_norm * post_norm * cap;

    // Perfect-fit reward (subtracted), stronger as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residual close to next item size (unusable gap vs useful gap)
    if next_item_size > 0 {
        let gap_diff = (post - next_item_size as f64) / cap;
        score += 8.0 * gap_diff * gap_diff * cap;
        // Reward exact match with next item
        score -= 10.0 * (-gap_diff * gap_diff * 400.0).exp();
    }

    // Last-chance bin bonus: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * post_norm;

    // Mild deviation from mean residual: prefer balanced bins
    score += 3.0 * (post - mean_residual).abs() / cap;

    // New-bin candidate: keep it neutral-to-slightly-poor so it only wins for bad fits
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
        score -= 5.0 * post_norm; // baseline for empty bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual via integer division thresholds.
    let tight = (post_residual as f64 / bin_capacity as f64).min(1.0);
    score -= 30.0 * (1.0 - tight * tight);

    // Modulo-class logic on post_residual: residuals that are multiples of small
    // harmonics (e.g. divisible into common item sizes) are more reusable.
    if post_residual > 0 {
        let mut harmonic_bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                harmonic_bonus += 6.0;
            }
        }
        score -= harmonic_bonus;
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 12.0 * (1.0 - (leftover as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize wasting large residuals.
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins have plenty of room and a decent fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 10.0 + 8.0 * pressure * (1.0 - progress);
    }

    // Mild preference for fuller bins among open ones (deviation from mean residual).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Dead-space penalty: residuals in awkward harmonic classes (e.g. 1..9 slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: strongly reward zero waste.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only open bin that fits, prefer it
    // heavily over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Lookahead (k=2): reward leaving room for the next item,
    // penalize leaving a gap the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    if is_new_bin {
        // New-bin candidate: penalize when plenty of open bins already fit,
        // so a new bin only wins when existing fits are poor.
        score += fitting_bins_count as f64 * 20.0;
        // If mean residual across open bins is high, existing bins have room:
        // make opening a new bin more expensive.
        score += mean_residual * 0.3;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    } else {
        // Open-bin pressure: with many open bins, favor consolidating into them.
        score -= open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching:
    // Reward bins whose post_residual exactly matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        if post == nxt {
            // Perfect chain: this bin absorbs current item AND next item fully.
            score -= 60.0;
        } else if post > nxt {
            // Next item fits after this one: reward closeness of the leftover gap.
            let gap = post - nxt;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit in the residual: penalize wasted chain potential.
            let miss = nxt - post;
            score += 8.0 * (miss / 100.0);
        }

        // Bonus if after placing both items the bin is perfectly closed.
        if post >= nxt && post - nxt < 5.0 {
            score -= 15.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0;
    }

    // Relative dead-space penalty: residual far below mean means tight (good) usage;
    // residual far above mean suggests this bin is roomy and could serve bigger items later.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 - 0.2 * post_residual as f64;
    }

    // New-bin candidate handling: penalize opening a new bin, unless current item
    // is huge and would leave tiny unusable residual in any open bin.
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size >= 70 {
            score -= 25.0; // big items deserve a fresh bin
        }
        // Late in the stream, discourage opening bins with poor future utility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for consolidating into fewer open bins.
    score += 0.05 * open_bins_count as f64;

    // Small tie-breaker: exact-fill reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum plausible item size is worthless.
    let min_item = 1.0f64;
    let dead = (post_residual as f64 - min_item).max(0.0);
    score += 0.35 * dead;

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            score += 0.15 * chain_waste as f64;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // Next item would have fit before this placement but not after:
            // mild penalty for blocking the lookahead.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins over emptier ones among open bins.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fullness;

    // Global balance: penalize bins far from the mean residual to keep
    // residuals homogeneous (easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // New-bin candidate handling: opening a bin is attractive only when the
    // item is large relative to capacity or the stream is early (more future
    // items can use the fresh bin).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Late in the stream, new bins are expensive; early, they're fine.
        let time_cost = 30.0 * progress;
        // Large items waste little space in a fresh bin.
        let waste = (bin_capacity - item_size) as f64;
        score = 55.0 + waste * (0.4 + 0.6 * progress) - 20.0 * item_frac + time_cost;
        // If no open bin fits, the new bin must compete only with itself.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), smoothed non-linearly.
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr) * 4.0);

    // Dead-space penalty grows with stream progress (late waste is costlier).
    let dead = if pr > 0.0 { (pr / item_size.max(1) as f64).ln().max(0.0) } else { 0.0 };
    score += 0.35 * dead * (0.5 + progress);

    // Lookahead: reward bins whose post_residual still fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 0.9 * (1.0 - slack).max(0.0) * (1.0 - 0.5 * progress);
        } else {
            score += 0.5 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - norm_pr);
    } else if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64 - 2.0).min(3.0);
    }

    // Mean-residual coupling: avoid bins far from the mean unless very tight.
    let dev = (pr - mean_residual).abs() / cap;
    score += 0.4 * dev * (1.0 - norm_pr);

    // New-bin candidate: penalize mildly, less so when residuals are all large.
    if bin_residual == bin_capacity {
        score += 0.8 - 0.5 * (mean_residual / cap).clamp(0.0, 1.0);
        if next_item_size > 0 && next_item_size as f64 >= cap * 0.5 {
            score -= 0.4;
        }
    }

    // Smooth saturation of open-bin pressure.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (small leftovers that many item sizes can still use).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: leftover too small to fit the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Harmonic class bonus via integer division thresholds on post_residual.
    // Class 0: pr == 0 (perfect fit) -> strong reward.
    // Class 1: pr in [10, 25) -> still broadly usable.
    // Class 2: pr in [25, 50) -> moderately usable.
    // Class 3: pr >= 50 -> large leftover, mild preference anyway.
    let class = pr / 25;
    match class {
        0 => score -= 40.0,
        1 => score -= 10.0,
        2 => score -= 3.0,
        _ => {}
    }

    // Modulo coupling: leftover divisible by common item sizes (10/20/25/50)
    // pairs well with future arrivals.
    if pr % 10 == 0 { score -= 6.0; }
    if pr % 25 == 0 { score -= 4.0; }

    // Lookahead: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // Exact match of next item to leftover is ideal.
            if next_item_size == pr { score -= 15.0; }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when all open bins would leave bad
    // dead space, or when open bins are already crowded relative to capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * progress;
        // If the current item is large, a fresh bin is more attractive.
        score -= (item_size as f64) * 0.15;
        // If mean residual across open bins is small (crowded), fresh bin wins.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 20.0;
        }
    } else {
        // Mild preference for tighter bins overall.
        score += (mean_residual - prf).max(-20.0).min(20.0) * 0.2;
    }

    // Fractional capacity coupling: reward bins whose fill level is a clean
    // fraction of capacity.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    if (fill * 4.0).fract() < 1e-6 { score -= 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

