    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor tight fits
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * post_residual as f64 * 0.15;

    // Lookahead: if next item fits the post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // If next item almost fits (small miss), slightly penalize
    if next_item_size > post_residual as u32 && next_item_size - post_residual as u32 <= 5 && post_residual > 0 {
        score += 15.0;
    }

    // Prefer bins below mean residual (tighter bins) when residuals are small
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only
    // when all open bins would create dead space
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
