    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how close it was.
        let miss = (next_item_size - post_residual) as f64;
        score += 12.0 * (miss / bin_capacity as f64);
    } else {
        // Last item: prefer minimal waste.
        score += 5.0;
    }

    // Penalize dead space below the minimum possible item size (1..100 range, use small threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 4.0 * (mean_residual - post_residual as f64);

    // Last-chance bin boost: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in stream, new bins are cheaper; late, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If lookahead fits perfectly in a fresh bin, soften the penalty.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual).
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that nothing can use (items >= 1).
    if post_residual > 0 && post_residual < 4 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 30.0;
        } else if (post_residual as f64) >= nxt {
            score -= 8.0 * (nxt / post_residual as f64);
        } else {
            // next item won't fit here; penalize large wasted post residual
            score += 0.05 * (post_residual as f64 - nxt).max(0.0);
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let avg_fit_badness = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        let new_bin_score = 60.0
            - 45.0 * pressure
            - 30.0 * avg_fit_badness
            - 10.0 * progress
            - 4.0 * open_bonus;
        return new_bin_score.max(-10.0);
    }

    // Mild penalty for leaving residual far from typical item sizes.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Encourage consolidation when many bins are open.
    score -= 0.5 * (open_bins_count as f64);

    // Slight time decay: early on, prefer balanced fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate waste to spread items;
    // later, penalize residual more aggressively (quadratic in progress).
    score *= 1.0 + 0.8 * progress * progress;

    // Smooth interaction: post_residual vs mean residual deviation
    let dev = norm_pr - mean_residual / cap;
