    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 - norm_pr) * (1.0 - progress * 0.5);

    // Lookahead: reward if next item fits the post-residual (smooth coupling)
    if next_item_size > 0 {
