        let fit_next = (pr - nxs).max(0.0) / cap;
        score += 15.0 * fit_next * fit_next;
        let exact = (1.0 - ((pr - nxs).abs() / cap).min(1.0)) * (1.0 - fit_next * cap / cap);
        score -= 20.0 * exact * (1.0 - progress);
