    // Penalize opening new bins when many bins already exist (smooth in open count)
    let openness = open_bins_count as f64;
    score += 3.0 * (openness / (openness + 10.0)) * (1.0 - norm_pr);

    // Small penalty for very tight fits that leave unusable slivers
    score += 10.0 * (norm_pr * (1.0 - norm_pr)).max(0.0) * (norm_pr > 0.0 && norm_pr < 0.1) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
