    // Prefer bins with below-mean residual (consolidate emptier bins? no —
    // prefer placing into bins with residual below mean to keep large residuals
    // available for large future items).
    if bin_residual as f64 > mean_residual {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in the stream, be more conservative (keep space flexible);
    // later, prioritize closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.25 * post_residual as f64;
    score -= progress * 5.0 * tightness;

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin, reduced when many bins are open
        // or when the current item is large (hard to place later).
        let mut new_bin_cost = 18.0 + 0.1 * open_bins_count as f64;
        if item_size > 60 {
            new_bin_cost -= 6.0;
        }
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        }
        // Late in stream, avoid opening bins unless necessary.
        new_bin_cost += 10.0 * progress;
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping.
    let mut score = 2.0 * norm_pr + 1.5 * norm_pr * norm_pr + 0.8 * norm_pr.powi(3);

    // Smooth coupling: residual waste penalized more as stream progresses.
    score *= 1.0 + 0.6 * progress;

    // Reward bins whose post-residual matches the next item (lookahead fit).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 0.7 * (-gap * 3.0).exp();
        // Penalize leaving a residual slightly too small for the next item.
        if pr < next_item_size as f64 {
            score += 0.5 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else {
        // Mild penalty when many alternatives exist to keep good bins free.
        score += 0.05 * (fitting_bins_count.saturating_sub(1) as f64).ln().max(0.0);
    }

    // Prefer fuller bins relative to the fleet mean residual (smooth term).
    score -= 0.3 * (mean_residual - pr) / cap;

    // Early stream: slight preference to spread into new bins (smooth in progress).
    score += 0.4 * (1.0 - progress) * norm_pr;

    // New-bin candidate: neutral-ish baseline with smooth decay over stream.
    if bin_residual == bin_capacity {
        score = 3.0 - 1.0 * progress + 0.5 * (open_bins_count as f64).sqrt() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual mod capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty for small unusable residuals (below min item size 1..=10 zone)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Classify residual by integer division into harmonic bands
    let band = post_residual / 10; // 0..10 bands
    let band_f = band as f64;
    score -= band_f * 3.0; // reward larger residual classes

    // Modulo-4 arithmetic on post_residual: favor residuals that are nice fractions of capacity
    let m = post_residual % 4;
    let mod_bonus = match m {
        0 => 8.0,  // divisible by quarter-ish granularity
        2 => 4.0,
        _ => 0.0,
    };
    score -= mod_bonus;

    // Lookahead coupling: does next item fit in post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward if next item exactly fills post residual
        if next_item_size == post_residual {
            score -= 40.0;
        }
    } else if next_item_size > post_residual {
        score += 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New bin candidate handling: neutral-ish but penalize slightly when many open bins exist
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins deviating from mean to consolidate
    let dev = pr - mean_residual;
    score -= 0.3 * dev;

    // Waste ratio term
    let waste_frac = pr / c;
    score += 20.0 * waste_frac * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // dead-space penalty
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is highly desirable
    }

    // Reward tight fits relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity && item_size <= bin_capacity;
    if new_bin {
        score += 12.0 + open_bins_count as f64 * 2.5;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Mild alignment with mean residual: prefer bins below-average residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        // Perfect match for the next item is highly desirable.
        let gap = (pr - nxt).abs();
        score += gap * 0.5;
        // Strong reward if next item fits exactly or nearly in the post residual.
        if pr >= nxt {
            let slack = pr - nxt;
            score -= (nxt / 4.0) * (1.0 - slack / 40.0).max(0.0);
        }
        // Penalize dead space that cannot fit the next item.
        if pr < nxt {
            score += (nxt - pr) * 0.35;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Relative residual context: bins with residual near mean are "normal";
    // reward using bins that are already fragmented (low residual) to close them.
    let mr = mean_residual;
    if pr_ok(post_residual) {
        let dev = (post_residual as f64 - mr).abs();
        score += dev * 0.05;
    }

    // Penalize leaving large unusable gaps (dead space under minimum item size).
    let min_item = 1.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_item + 3.0 {
        score -= 2.0; // tiny residual is fine, effectively perfect packing
    } else if pr > 60.0 {
        score += (pr - 60.0) * 0.15; // large leftover wastes capacity
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0; // default penalty: prefer existing bins
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            // empty bin is a fresh start; slight relief
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (spread risk);
    // later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Slight bonus for filling bins very full (small post_residual).
    score -= (bin_capacity as f64 - pr) / bin_capacity as f64 * 0.5;

    score
}

#[inline]
fn pr_ok(_r: u32) -> bool { true }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount for small post_residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space that cannot plausibly fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving exactly room for the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a bin is penalized when any bin fits,
    // but attractive when the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual);
        score += 30.0 + 8.0 * open_bins_count as f64;
        // Large items with little residual elsewhere: allow new bin.
        if item_size as f64 > mean_residual * 0.8 {
            score -= 45.0;
        }
        // Late in the stream, avoid spawning bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        let _ = crowding;
    }

    // Prefer filling bins that are already low-residual (consolidation).
    let frac = (bin_residual as f64) / (bin_capacity as f64);
    score += 15.0 * frac * frac;

    // Lookahead: if next item is large, prefer keeping big-residual bins free.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack slightly (bins stay reusable); late, demand tightness.
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * progress;
    score += 40.0 * poly;

    // Dead-space penalty: very small residuals are wasted capacity, worse late in stream.
    let dead = (1.0 - norm_pr).powi(4);
    score -= 25.0 * dead * (0.5 + 0.5 * progress);

    // Lookahead: reward residual that can host the next item (chained fit).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 8.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 2.0 * open_bins_count as f64 / (1.0 + progress);

    // Compare against mean residual: bins far below mean are more valuable to fill.
    score -= 5.0 * (mean_residual - pr) / cap;

    // New-bin candidate should only win when nothing fits well: penalize empty bin mildly.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-10 buckets
    let post_mod = post_residual % 10;
    let post_div = post_residual / 10;

    // Dead space penalty: small post_residual that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how snugly next item fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * (post_residual as f64 - snug);
        } else {
            // Next item won't fit here; penalize wasted capacity unless residual is large
            let waste = post_residual as f64;
            if waste < 25.0 {
                score += 0.8 * waste;
            }
        }
    }

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Modulo-class coupling between post_residual and next_item_size
    let next_mod = if next_item_size > 0 { next_item_size % 10 } else { 0 };
    if next_item_size > 0 && post_residual > 0 {
        if post_mod == next_mod && post_residual >= next_item_size {
            score -= 15.0; // same harmonic class -> likely good chain
        }
        // Integer-division thresholds: post_residual can host next item with room for a small filler
        let room = post_residual / (next_item_size.max(1));
        if room >= 2 {
            score -= 10.0 * (room as f64).min(3.0);
        }
    }

    // Penalize opening a new bin when decent fit exists and many bins already open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin baseline: slightly worse than a good existing fit
        score += 55.0 + 20.0 * progress;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 5.0 {
            score += 35.0;
        }
        // Late in stream, prefer closing out open bins
        if open_bins_count > 3 {
            score += 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Mild preference for tighter existing bins: reward small residuals that still fit
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if !is_new_bin {
        score -= 10.0 * tightness;
    }

    // Harmonic penalty on post_residual divisible classes creating awkward gaps
    if post_div == 1 && post_mod >= 5 && post_mod <= 9 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftovers (1..=10) are almost unusable for
    // future items, so punish them far beyond their nominal size.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= 40.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize the dead space more.
        score += 15.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (filling the "fuller" bins first keeps many large-residual bins open).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only allow opening a new bin when open-bin pressure is low and the
    // current placement would leave a bad gap; otherwise make it expensive.
    if bin_residual == bin_capacity {
        if open_bins_count > 3 && post_residual as f64 > mean_residual * 0.7 {
            score -= 30.0; // opening fresh bin is attractive
        } else {
            score += 70.0; // prefer existing bins by default
        }
    }

    // Slight stream-progression tilt: later in the stream, consolidate more.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize tiny dead space (< 10) heavily
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score += 25.0; // dead space: unusable for min item size 10
    }

    // Two-step lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // next item exactly fills this bin
        } else if next_item_size <= post_residual {
            // reward proportional fit quality of next item
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * frac;
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (post_residual as f64).min(next_item_size as f64);
            score += 8.0 * (1.0 - gap / 100.0);
        }
    }

    // Relative to mean residual: bins with more room than average are less precious
    if (bin_residual as f64) > mean_residual + 1.0 {
        score -= 6.0;
    } else if (bin_residual as f64) < mean_residual - 1.0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64).min(20.0);
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of residual used by this placement.
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits: subtract proportional to how well the item fills the bin.
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize tiny post-residuals that create dead space unusable by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
            // Perfect chain: next item exactly fills remaining space.
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else if next_item_size >= bin_residual {
            // Next item won't fit here even before placement; this bin is a dead end
            // for the future, mild penalty unless we are the last-chance bin.
            score += 3.0;
        }
    } else {
        // Last item of the stream: prefer fullest packing, new bins are useless.
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global state: many open bins with slack -> discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are crowded or stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 10.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            // Existing bins are too tight on average anyway; new bin less bad.
            score -= 8.0;
        }
    }

    // Mild preference for bins tighter than average (concentrate slack).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.04 * diff;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: post-residual waste, non-linearly scaled (quadratic waste penalty)
    let mut score = post + 0.35 * (post * post) / cap;

    // Smooth polynomial coupling of waste with stream progress:
    // later in the stream, dead space is costlier.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += post * (0.8 * p2 + 0.6 * p3);

    // Tight-fit reward: smooth bump when post_residual is small relative to capacity
    let tightness = 1.0 - post / cap;
    score -= (tightness * tightness) * 12.0;

    // Penalize bins whose residual deviates from the mean residual (fragmentation guard)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward bins that leave room for the next item (smooth interaction)
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_margin = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - fit_margin * fit_margin);
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty grows with progress
        score += 3.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling: empty bin has high post_residual; make it
    // attractive only when open bins are scarce or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let large_item = item_size as f64 / cap;
        score += 18.0 - 14.0 * large_item - 6.0 * progress - (open_bins_count as f64).min(8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;

    // Dead-space penalty: leftover that cannot host typical small items (1..=10 range).
    // Leftovers in (0, 10) are pure waste; class 0 residues are "harmonic" and reusable.
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    }
    score -= residue_class * 0.3; // prefer leftovers that are multiples of 10

    // Integer-division thresholds: how many size-10 units fit in the leftover.
    let units = (pr / 10) as f64;
    score -= units * 2.0;

    // Fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 15.0;

    // Next-item coupling: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 30.0; // perfect lookahead fit
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 / (1.0 + slack * 0.1);
        } else {
            // next item cannot fit here; penalize by gap size
            score += ((next_item_size - pr) as f64) * 0.4;
        }
        // Harmonic class match: next item aligns with leftover modulo class
        if (pr % 10) == (next_item_size % 10) && pr >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual as f64 == cap {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        // High mean residual => open bins have room; penalize new bin.
        score += 10.0 + pressure * 3.0;
        if pr == 0 {
            score += 5.0; // perfect fill of fresh bin (item == capacity)
        }
    }

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold even the
    // smallest future item (assumed min size ~1..10) are wasted capacity.
    // Penalize "unusable" small gaps quadratically.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Tiny dead space: heavily penalize (it's pure waste).
            score += (10.0 - gap) * (10.0 - gap) * 1.5;
        } else if gap < item_size as f64 && gap < next_item_size as f64 {
            // Gap too small for the known next item either: dead space.
            score += gap * 0.8;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage creating more
    // (favor consolidation); when few bins are open, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but relax late in the stream when consolidation matters most.
        score += 10.0 + bin_pressure * 2.0;
    } else {
        // Existing bin: slight reward scaled by pressure to consolidate.
        score -= bin_pressure * 0.3;
    }

    // Prefer bins below mean residual (more filled bins) to keep residuals
    // homogeneous and predictable.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: next item exactly fills this bin afterwards
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement; reward tightness of chain
            let gap = (post_residual - next_item_size) as f64;
            score -= (18.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // Next item cannot follow into this bin: penalize stranded residual
            let waste = post_residual as f64;
            if waste > 0.0 {
                score += 8.0 + 0.35 * waste;
            }
        }
    } else {
        // Last item: just minimize residual
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: only one bin fits the item, use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and fit is reasonable
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // New bin only attractive for large items or when item would leave
            // huge dead space elsewhere (post_residual small is fine in new bin)
            let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
            if big_item {
                score += 5.0;
            } else {
                score += 40.0;
            }
        } else {
            score -= 20.0; // no open bins: opening is mandatory
        }
    }

    // Late-stream tightening: prefer fuller bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to hold any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect chain: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open new bin early in the stream (long horizon amortizes).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins are open with large mean residual, discourage opening another.
        score += 0.15 * open_bins_count as f64;
        score += 0.05 * mean_residual;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
        // If this bin is the last chance overall, opening new bin is bad.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Mild preference for filling bins that are already relatively full.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    // Encourage consolidation when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = post / cap;

    // Base: penalize leftover space, with a convex non-linear squaring so
    // small leftovers are tolerated but large dead space is punished heavily.
    let mut score = post + 40.0 * fit_norm * fit_norm;

    // Smooth coupling with stream progress: late in the stream, compactness
    // matters more (fewer chances to fill leftovers), so amplify post-residual.
    let late = progress * progress;
    score += 60.0 * late * fit_norm * fit_norm;

    // Reward tight fits via a smooth saturating term of item utilization.
    let util = item_size as f64 / cap;
    score -= 25.0 * util * (1.0 - fit_norm);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - late);
    }

    // Penalize bins whose residual deviates from the mean (fragmentation
    // balancing), smoothly via squared deviation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if the next item would fit the post-residual, reward it;
    // smooth quadratic coupling of next-item fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 30.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 15.0 * miss * miss;
        }
    }

    // Mild penalty for spreading across many open bins early on.
    let bins_norm = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 20.0 * bins_norm * (1.0 - late);

    // New-bin candidate: an empty bin has post == cap; make it moderately
    // attractive only when no open bin offers a tight fit (large post there).
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - util) - 20.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (integer division bands) ----
    // Band 0: post_residual == 0  -> perfect fit, huge reward
    // Band 1: 1..=9               -> dead space below min item, mildly bad
    // Band 2: 10..=30             -> awkward leftover, penalize
    // Band 3: 31..=60             -> usable medium, neutral
    // Band 4: 61..=99             -> large leftover, keep flexible
    let band = post_residual / 10; // harmonic decade class
    match band {
        0 => score -= 60.0,                       // perfect fit
        1 => score += 12.0,                       // dead space penalty
        2 => score += 18.0,                       // worst class: unusable chunk
        3 => score -= 4.0,                        // usable
        _ => score -= 8.0,                        // big leftover stays flexible
    }

    // ---- Lookahead coupling: does this bin still fit the next item? ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportionally to how well next item also fits
            score -= 10.0 + 0.15 * (next_item_size as f64);
        } else if next_item_size >= item_size {
            // Next item is bigger; a big leftover matters more
            if post_residual > bin_capacity / 2 {
                score -= 6.0;
            }
        }
    }

    // ---- Last-chance bin: if this is the only bin that fits, strongly prefer ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: open a new bin only when open bins give bad fits.
        score = 55.0;
        // Late in the stream, slightly discourage hoarding new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are open with slack, discourage one more.
        score += 0.3 * (open_bins_count as f64).sqrt();
        // If mean residual is small (bins nearly full), new bin is attractive.
        score -= (mean_residual.max(0.0)).min(50.0);
    }

    // ---- Modular (harmonic) residue class on post_residual vs capacity fraction ----
    // Items 1..100: favor post_residuals that are multiples of common item classes.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 5.0; // leftover aligned to item-size grid is reusable
    } else if post_residual % 3 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual leaves room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space relative to lookahead
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer consolidating when many are open.
    let open_pressure = open_bins_count as f64 * 0.8;
    score -= open_pressure;

    // New-bin candidate: penalize slightly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + open_pressure * 0.5;
    }

    // Prefer bins tighter than average (below-mean residual = good fit).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for fuller bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper; relax the penalty slightly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If no existing bin fits, the new bin is the only option — drop penalty hard.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Perfect fit reward: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Two-step lookahead: if the next item fits exactly into post_residual,
    // this is a chained perfect fit — heavily reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // If next item also fits with small slack, mild reward.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 15.0;
    }

    // Penalize dead space that the next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += dead * 0.3;
    }

    // Penalize leaving residual far below the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the current mean residual (good fits get used first).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.2;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // Mild penalty for creating very large residual (wasteful placement of small item).
    if post_residual as f64 > mean_residual + 30.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score -= 50.0; // perfect closure bonus
    } else if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap penalty
    }

    // Lookahead coupling: if next item fits into post_residual, reward.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).max(0.0);
        }
    } else {
        // last item: strongly prefer closing bins
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let crowding = (open_bins_count as f64) / 20.0;
    score += crowding * (1.0 - progress) * 5.0;

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already fragmented; prefer filling it rather than richer bins.
    let dev = (bin_residual as f64) - mean_residual;
    score -= 0.15 * dev;

    // New-bin candidate handling: empty bin gets a penalty that shrinks when
    // existing bins are very fragmented or the item is huge.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let mut new_bin_penalty = 20.0;
        if fragmentation < 0.35 { new_bin_penalty -= 10.0; }
        if big_item { new_bin_penalty -= 8.0; }
        if progress > 0.8 { new_bin_penalty -= 5.0; }
        score += new_bin_penalty;
    }

    // Slight preference for bins with larger residual among equals (keep small
    // gaps for small items later in the stream).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual shaped by stream progress
    let shape = 1.0 + 0.35 * progress * (norm_post - 0.5) * (norm_post - 0.5) * 4.0
              - 0.25 * (1.0 - progress) * (1.0 - norm_post);
    score *= shape;

    // Cubic penalty for small dead space that grows late in the stream
    score += 0.6 * norm_post * norm_post * norm_post * cap * (0.5 + progress);

    // Favor tight fits: subtract reward proportional to fill ratio, smoothed
    let fill = 1.0 - norm_post;
    score -= cap * 0.45 * fill * fill * (1.0 + 0.5 * progress);

    // Last-chance bin bonus: strongly reward the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 * (1.0 - 0.5 * progress);
    }

    // Penalize bins that leave residual too small for typical future items,
    // but only when many bins are open (fragmentation pressure)
    let frag = (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * progress;
    score += 8.0 * frag * (1.0 - (pr / 10.0).min(1.0));

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
        } else {
            let gap = next_item_size as f64 - pr;
            score += 0.15 * gap * (0.5 + progress);
        }
    }

    // Mild preference for consolidating into bins below mean residual (evening out)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + progress) - 2.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless it is early or nothing fits well
    if bin_residual == bin_capacity {
        let need = (fitting_bins_count == 0) as i32 as f64;
        score += 12.0 - 10.0 * need - 6.0 * progress * (1.0 - need);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "friendly" classes (multiples of 10, or small enough to be nearly full)
    // are preferred since future items (10..80) can reuse them.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -40.0 // perfect fit is always best
    } else if pr <= 10 {
        -25.0 // leftover smaller than min item => effectively sealed bin
    } else if pr % 10 == 0 {
        -12.0 // decadal class: high chance a future item fits exactly
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward residual class, penalize
    };
    score += class_bonus;

    // Integer-division threshold: residual / capacity fraction bands.
    let fill_frac = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    if fill_frac > 0.8 {
        score -= 15.0; // strongly reward high fill
    } else if fill_frac > 0.5 {
        score -= 5.0;
    } else {
        score += 4.0; // sparse bins waste capacity
    }

    // Dead-space penalty: residual that no plausible item can use.
    if pr > 80 {
        score += 6.0; // only tiny items (<=20) fit; weak reuse
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item exactly matches the post residual
    // (harmonic pairing), reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 3.0;
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
        // modulo harmony: next item and post residual share a decadal class
        if pr > 0 && (pr % 10) == (next_item_size % 10) && next_item_size <= pr {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: prefer existing bins unless this one is
    // nearly full or the stream is early (building a stock of bins is fine).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) * (item_size as f64) / bin_capacity as f64;
        // open a new bin only when existing bins are crowded or residual classes mismatch
        score += 18.0 - 10.0 * pressure - 5.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 10.0; // open bins can't absorb the item well
        }
    }

    // Mild entropy term: spread load when many bins are open and mean residual is high.
    if (mean_residual - post_residual as f64).abs() > 30.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item are "dead space". Penalize them heavily.
    let dead_threshold = 10.0; // minimum item size is 10 in classic regime; treat <10 as fully dead
    if (post_residual as f64) < dead_threshold {
        score += 40.0; // completely wasted space
    } else if post_residual <= 20 {
        // small gap: only usable by tiny items; harsh but graded penalty
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    } else if post_residual <= 35 {
        // medium-small gap: mild penalty to prefer tighter fits elsewhere
        score += 8.0;
    } else {
        // large residual: slight reward for keeping bins flexible
        score -= 5.0;
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (penalize choosing the new-bin candidate implicitly by rewarding reuse).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and when the current fit into an open bin would be acceptable.
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin — finishing it off is good (reduces bin count).
    let diff = mean_residual - bin_residual as f64;
    if diff > 15.0 {
        score -= 6.0; // below-mean residual: prefer consolidating this bin
    } else if diff < -15.0 {
        score += 6.0; // above-mean residual: deprioritize sparse bins slightly
    }

    // Stream progression: early on, keep bins flexible (favor larger residuals);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post residual
    // can exactly (or nearly) host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Exact match is a perfect 2-item packing: big reward.
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        // Extra bonus for perfect zero-slack match.
        if slack == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportional to wasted lookahead.
        let deficit = (next_item_size - post_residual) as f64;
        score += 8.0 * (deficit / bin_capacity as f64);
    }

    // Penalize tiny unusable residuals (dead space) relative to smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late in the stream, avoid opening new bins (consolidation pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, softened when current bin would leave bad dead space.
        score += 40.0 - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) == 0 {
            score -= 35.0; // allow opening a bin for a perfect 2-item pairing
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference for filling larger residual bins first when many bins open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, amplify the reward.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that no future small item could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // near-perfect fill bonus
    }
    if post_residual > 50 {
        score += 2.0 * (post_residual as f64 - 50.0) / 50.0;
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
    }
    // If next item almost fits (within 10), slight reward.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score -= 1.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate handling: opening a new bin is wasteful when
    // open bins have enough collective slack or the fit is decent.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut nb = 15.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb -= 6.0 * (1.0 - progress);
        // If many open bins already, discourage yet another one.
        nb += 0.5 * open_bins_count as f64;
        // If mean residual is large, existing bins have slack; discourage new bin.
        nb += mean_residual * 0.15;
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 1 {
            nb -= 10.0;
        }
        // Very large items justify fresh bins.
        if item_size >= bin_capacity / 2 {
            nb -= 3.0;
        }
        score += nb;
    }

    // Slight preference for bins whose residual deviates from mean
    // (fill below-average-residual bins to homogenize leftovers).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = x * x * (2.0 - progress) + x * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream.
    score -= (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Penalize creating dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            score += (gap / cap) * (1.0 + 2.0 * progress) * 8.0;
        } else {
            score -= 0.5 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Mild preference for bins with residual below the mean (consolidation).
    score += 0.3 * ((mean_residual - pr) / cap);

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.2 * progress) - (fitting_bins_count as f64) * 0.1;
    }

    score
}

