pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1
    // is unknown, but typical streams have sizes >= 10; treat gaps < 10 as dead)
    // Penalize unusable small gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that can't fit the next item are semi-dead unless another item may come.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits: small relative leftover.
    let frac_left = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - frac_left) * 20.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 3.0;

    // New-bin candidate: penalize moderately so it's chosen only when open bins
    // are poor fits, but allow it when mean residual is low (nothing useful open).
    if bin_residual == bin_capacity {
        score += 35.0;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit core).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // Slight bonus if bin can also fit the next item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

