        } else if post_residual > next_item_size {
            let chain_slack = post_residual - next_item_size;
            score -= 100.0 - (chain_slack as f64).min(100.0);
            score += (chain_slack as f64) * 0.5;
        } else {
            // Next item cannot fit here afterwards; dead space risk.
            let dead = next_item_size - post_residual;
            score += (dead as f64) * 0.8;
        }
    }

    // Penalize residuals too small to ever hold a plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Compare against mean residual: bins with residual below mean are
    // "tighter" — filling them is good (keeps loose bins available).
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 10.0;
    }

    // Opening a new bin early is wasteful; penalize the empty-bin candidate
    // unless the item is large and nothing tight exists.
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size >= 70 && fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 40.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

