        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            if post_residual > item_size {
                score += 4.0;
            }
        }
    }

    // Last chance: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
