        score += 15.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If mean residual of open bins is small (fragmented), opening new bin less attractive
        score -= mean_residual * 0.15;
    } else {
        // Reward using bins that are already below mean residual (balancing fragmentation).
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // Mild preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, keep bins tight (small post_residual rewarded strongly);
    // late in the stream, residual waste matters less, so ease off.
    let tightness = 1.0 + 1.5 * progress * progress;
    score += tightness * (pr * pr) / cap;

    // Penalize leaving a residual that is too small to hold any future item
    // (dead space), smoothly scaled by how much of the bin it wastes.
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 8.0 * dead * dead;

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward heavily (smooth exponential affinity).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-gap / cap).exp();
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Penalize new-bin candidates (empty bin) mildly, more so early in the
    // stream when consolidation is valuable; relax as progress advances.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 3.0;
    }

    // Slight preference for bins whose residual is already below average
    // (consolidating fragmented bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
