    }

    // New-bin candidate: make it moderately attractive only when open bins
    // would leave large unusable residue; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 30.0;
        // if the item is large relative to capacity, a fresh bin is fine
        let frac = item_size as f64 / cap;
        if frac > 0.6 {
            score -= 20.0;
        }
        // late in the stream, avoid proliferating bins
        let prog = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * prog;
        // if many bins already open, discourage one more
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Prefer filling bins with residual far below the mean (consolidate)
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.1 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward leaving room exactly for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // gap can't serve next item: dead space risk
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (20.0 + 10.0 * open_bins_count as f64 * (0.5 + 0.5 * progress));

    // Mild preference for bins tighter than average (waste consolidation).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can chain into this bin: reward closeness to exact match
            score -= 40.0 * (1.0 - lookahead_gap / bin_capacity as f64);
            if lookahead_gap < 1.0 {
                score -= 35.0; // exact chain: post_residual == next_item_size
            }
        } else {
            // Next item cannot fit after this placement: penalize by gap size
            score += 15.0 + lookahead_gap * 0.3;
        }
    }

    // Tightness relative to mean residual: prefer tighter-than-average outcomes
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Waste penalty grows quadratically with leftover space
    score += 0.002 * (post_residual as f64).powi(2);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Late in stream: consolidate into existing bins rather than opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 25.0 + 40.0 * progress;
        // But if item is huge relative to mean residual, new bin may be right
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 20.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual (good fit) via non-linear shaping
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Dead space penalty: residuals too small for typical items are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward if next item fits into post_residual, penalize otherwise
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are congested or late in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 15.0 - 10.0 * progress - congestion.min(20.0);
        if item_size > bin_capacity / 2 {
            score -= 10.0; // large items like fresh bins
        }
    }

    // Slight preference for bins below mean residual (balance preservation)
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: quadratic penalty shrinking as post_residual -> 0
    let tight = (post / cap).powi(2);
    score += 12.0 * tight;

    // Smooth interaction: tight fits matter more as the stream progresses
    score -= 10.0 * (1.0 - tight) * (progress * progress);

    // Penalize waste relative to mean residual of open bins (smooth coupling)
    score += 0.15 * (post - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize unless residual space is too fragmented
    // (i.e., this bin's residual is much larger than needed but leaves dead space)
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 8.0 + 6.0 * progress;
        // Allow new bin if no open bin fits well and item is large
        let large = item / cap;
        score -= 14.0 * large * (1.0 - (fitting_bins_count.min(4) as f64) / 4.0);
    } else {
        // Reward using existing bins smoothly with openness pressure
        score -= 0.3 * (open_bins_count.min(20) as f64).sqrt();
    }

    // Lookahead: prefer leaving room for the next item (smooth hinge)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 4.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 3.0 * (-gap / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize dead space in the awkward 11..=20 band (hard to fill later).
    if post_residual >= 11 && post_residual <= 20 {
        score += 25.0;
    }
    if post_residual > 50 {
        score += 8.0;
    }

    // Harmonic class: how well the leftover pairs with typical small items.
    let pr = post_residual as u32;
    if pr > 0 {
        let cls = pr % 10;
        if cls == 0 {
            score -= 10.0; // round leftover, easy to fill
        } else if cls <= 3 {
            score -= 5.0;
        } else {
            score += (cls as f64) * 1.5;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            if nxt_res <= 5 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow here; slight penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor or bins are fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 25 || post_residual > item_size;
        let pressure = (open_bins_count as f64) * 4.0 + mean_residual * 0.3;
        if poor_fit {
            score -= 12.0 + pressure * 0.2;
        } else {
            score += 35.0 + pressure * 0.1;
        }
        // Late in the stream, avoid opening new bins too eagerly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.05;
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap that no plausible future item (min size 1, but practically small items)
    // can use is dead space. Penalize gaps below a "dead zone" threshold.
    let dead_zone = 10.0;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Pressure from open_bins_count: with many open bins, prefer filling existing
    // bins rather than fragmenting; add mild penalty scaled by openness.
    let openness = open_bins_count as f64 / ((total_items.max(1) as f64).sqrt() + 1.0);
    score += openness * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which the empty-bin candidate would otherwise win).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty for creating stranded space.
        score += (post_residual as f64) * 0.15;
    }

    // New-bin candidate handling: an empty bin should only win when existing bins
    // fit poorly. Give it a moderate baseline so tight existing fits beat it.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.1;
    }

    // Progression: late in the stream, consolidation matters more; penalize waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // 2-step lookahead: ideal post_residual equals next_item_size (chain the next item perfectly).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += gap * 0.8;
        // Bonus if this placement lets the next item fit exactly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    } else {
        // Last item: reward filling the bin as much as possible.
        score -= item_size as f64 * 0.3;
    }

    // Penalize large residual relative to mean residual (wasteful bin).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // the item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + progress * 10.0;
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Reward using bins that are already fairly full before placement.
    let fill_before = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_before * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post-residuals that are still unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver is worse than perfect fill
    } else if post_residual < item_size {
        // residual below smallest item size is dead space; penalize proportionally
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Later in the stream, or with many open bins, opening new bins is less attractive.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        score += 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty for wasting the pairing
            score += 5.0;
        }
    }

    // Global state coupling: prefer placing into bins with residuals near the mean
    // (keeps bin residuals balanced, preserves flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild preference for bins with larger residuals when many bins are open
    // (consolidate into emptier bins to close tight ones).
    score -= 0.05 * (open_bins_count as f64).min(20.0) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: waste penalty grows quadratically with normalized dead space
    score += 60.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Reward tight fits: cubic decay of bonus as post_residual grows
    score -= 40.0 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Lookahead coupling: penalize if post_residual can't fit next item but is large-ish (dead zone)
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        if gap < 0.0 {
            score += 15.0 * (-gap).powi(2) * (1.0 - progress);
        } else {
            score -= 10.0 * gap * (1.0 - gap);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: prefer it only when post_residual would be large and stream is late
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - norm_item) * (1.0 - progress) - 10.0 * progress * norm_item;
    }

    // Mean residual coupling: discourage bins far below mean residual (fragmenting)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3) * 30.0;

    // Harmonic class logic: classify post_residual into modulo classes of
    // common item sizes (10..=80). Residuals that are multiples of small
    // common sizes are more likely to be filled by future items.
    let harmonic_bonus: f64 = if post_residual == 0 {
        50.0
    } else {
        let mut hb = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
            if post_residual >= m && post_residual % m == 0 {
                hb += 6.0;
            }
        }
        // Residuals in [1,9] are near-unusable dead space: penalize.
        if post_residual < 10 { hb -= 12.0; }
        hb
    };
    score -= harmonic_bonus;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial compatibility reward scaled by how much slack remains
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64));
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual - post_residual) as f64 * 0.05;

    // New-bin candidate handling: an empty bin should only win when the fit
    // in existing bins is poor. Penalize the fresh bin moderately so it is
    // chosen only for large items or bad fits.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Large items benefit from a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 22.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    // Nudge toward bins whose residual deviates favorably from the mean.
    score += 0.05 * (mean_residual - bin_residual as f64).abs().signum() * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

