        if gap < 10 {
            score -= 20.0 - 2.0 * gap as f64;
        } else {
            score -= 5.0;
        }
    }

    // Slight preference for opening new bins early in the stream (uncertainty is high).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate: default cost, adjusted by how bad the best alternative fit is.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Opening a new bin is attractive if the item is large and fit is loose elsewhere.
        if fit_ratio < 0.5 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post_residual exactly matches the next item,
    // creating a perfect fit on the following step.
    if next_item_size > 0 && post_residual >= next_item_size {
