    }

    // Prefer tight fits relative to current residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio;

    // Deviation from mean residual: keep residuals balanced.
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables
    // a perfect two-item pairing or few bins exist / late stream.
    if bin_residual == bin_capacity {
        let pair = if next_item_size > 0 && post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            bin_capacity as f64
        };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - 0.5 * open_bins_count as f64 - 20.0 * (1.0 - pair / bin_capacity as f64) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward residuals that can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // dead space relative to lookahead item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large dead space that nothing small can use (wasted capacity)
    let waste = post_residual as f64;
    score += 0.3 * waste * (waste / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins that are already tight relative to the fleet mean
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate more aggressively (fewer bins matter more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.2 * (bin_capacity - post_residual) as f64;

    // Slight penalty when many bins are open: encourage reusing existing bins
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large or the fit elsewhere would be terrible
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = score.max(0.0) + 60.0 - 40.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += (pr_norm * pr_norm) * 30.0 * (1.0 - progress);
    score -= (pr_norm * pr_norm * pr_norm) * 25.0 * progress;

    // Reward tight fits with smooth quadratic term
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * 20.0;

    // Penalize dead space too small for the smallest possible item (1..100 unknown, use item_size-based)
    let dead_threshold = (item_size as f64).min(20.0);
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr as f64) * 3.0;
    }

    // Lookahead coupling: smooth interaction between post_residual and next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (gap / bin_capacity as f64) * 15.0 * (0.5 + progress);
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean residual pressure: smooth non-linear term
    let mr_norm = mean_residual / bin_capacity as f64;
    score += (mr_norm * mr_norm) * 12.0 * (1.0 - progress);

    // Open bins count pressure, growing over the stream
    score += (open_bins_count as f64).powf(1.2) * 0.3 * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact residue classes modulo common item sizes
    let pr = post_residual;
    // Perfect fit: strong reward
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Usability classes: residual divisible by small common sizes is more reusable
        let mut usable_bonus = 0.0;
        if pr % 10 == 0 { usable_bonus += 30.0; }
        if pr % 20 == 0 { usable_bonus += 15.0; }
        if pr % 25 == 0 { usable_bonus += 10.0; }
        if pr % 50 == 0 { usable_bonus += 10.0; }
        // Small dead-space classes (pr < 10) are nearly unusable
        if pr < 10 { usable_bonus -= 60.0; }
        score -= usable_bonus;

        // Lookahead coupling: does next item fit into post_residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                // Harmonic match: next item divides or nearly divides residual
                let slack = pr - next_item_size;
                score -= 40.0 - (slack as f64).min(40.0);
                if slack == 0 { score -= 60.0; }
                if next_item_size % 10 == 0 && pr % next_item_size == 0 { score -= 15.0; }
            } else {
                // Next item won't fit here: penalize wasting residual on classes
                let class = pr % 10;
                score += 10.0 + class as f64;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current residual is tiny
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual; // average leftover across open bins
        score = 100.0 + waste * 0.5 + progress * 20.0;
        if item_size > 60 { score += 15.0; } // big items prefer fresh bins slightly less penalized
        if pr == 0 { score -= 30.0; }
    }

    // Mild preference for tighter bins as stream progresses
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0; // semi-dead zone
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // (avoids opening a new bin for an item that fits here).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // and penalize creating more fragmentation.
    let pressure = open_bins_count as f64;
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward;
    // if next item cannot fit, post-residual is truly dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 8.0; // dead space relative to lookahead
        } else {
            score -= 5.0; // next item still fits
        }
    }

    // Mean-residual coupling: if this bin's residual is far below average, it is an outlier
    // fragment; prefer bins near the mean to keep residuals uniform and reusable.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: empty bin has large post_residual; only allow it when existing
    // bins are very fragmented (many open bins with small residuals) or nothing fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + 1.5 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain match: strong reward.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to tightness of the chain.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * chain_tightness;
        } else {
            // Next item won't fit: penalize wasted residual that likely becomes dead space.
            let overflow_gap = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow_gap;
        }
    } else {
        // Last item: pure tightness packing.
        score += 5.0;
    }

    // Penalize residuals too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: prefer bins that keep residual near the mean
    // (balanced load), penalize outliers creating fragmented capacity.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless residual fragmentation is severe.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64 * 0.5);
        // But if this is the last item, opening a bin is irrelevant.
        if next_item_size == 0 {
            score -= 10.0;
        }
    }

    // Early in stream: slight preference to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual quadratically.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that cannot fit a typical item (<= post_residual unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here; penalize more if we waste a lot of space.
            score += (post_residual as f64) * 0.3;
        }
        // If next item is large, prefer bins with small residuals anyway.
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Global state coupling: many open bins -> prefer filling existing ones.
    let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
    score += open_frac * 10.0;

    // Mean residual coupling: if this bin is below mean residual (tighter than average), favor it.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Time horizon: early in stream, be more willing to open new bins (keep flexibility);
    // late in stream, squeeze everything into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 15.0 * (1.0 - t);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus time-dependent bias.
        score = bin_capacity as f64 * 0.5 + new_bin_bias;
        // Opening a new bin is more attractive if no open bin fits well
        // (post_residual large relative to item) or many bins already open.
        if post_residual as f64 > item_size as f64 {
            score -= 5.0;
        }
        score += open_bins_count as f64 * 0.2;
    } else {
        // Existing-bin placement gets a modest structural discount late in the stream.
        score -= 8.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize residual, with non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial shaping of residual: reward tight fits (small pr),
    // extra reward for near-zero residual via quadratic dip.
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize residuals that are too small to fit typical future items,
    // smoothly coupled with lookahead size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (ni - pr).max(0.0);
        score += 0.6 * waste * waste / cap;
        // Reward bins that can also fit the next item (smooth gate).
        let fit_next = 1.0 / (1.0 + ((pr - ni) / 10.0).abs());
        score -= 12.0 * fit_next;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Mean residual context: penalize adding to already-loose bins.
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate: mild penalty early, decaying with progress,
    // so late in the stream we prefer consolidating into open bins.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 4.0 * progress;
    }

    // Small smooth regularization against large open-bin count.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 10
    // (capacity granularity). Residuals in low classes (1..10) are near-dead.
    let cls = post_residual % 10;
    let div = post_residual / 10;

    // Penalize tiny unusable leftovers strongly (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward exact fit.
    if post_residual == 0 {
        score -= 20.0;
    }
    // Class-based coupling: residual divisible into coarse blocks is more reusable.
    score += (cls as f64) * 0.4;

    // Lookahead harmony: can next_item_size fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if next item divides the leftover into good classes.
            let ncls = (post_residual - next_item_size) % 10;
            score -= 6.0 - 0.5 * (ncls as f64);
            // Extra reward for near-exact chain fit.
            let gap = post_residual - next_item_size;
            if gap < 10 { score -= 5.0; }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot class.
            let over = next_item_size - post_residual;
            score += 3.0 + 0.3 * (over % 10) as f64;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all too fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score = (bin_capacity as f64) * (1.0 + 0.2 * progress);
        // Allow new bin if mean residual of open bins is small (fragmented).
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 0 {
            score -= 30.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins is better for equal fits.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residuals too small for the smallest item (1..=10)
    // are unusable; the smaller the gap, the harsher the penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    } else if post_residual > 10 && post_residual <= 20 {
        // Risky zone: only useful if the lookahead item can use it.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 6.0;
        } else {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward gaps that exactly or nearly fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 10.0 - slack.min(10.0);
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless it creates dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin when a fitting bin exists,
    // unless that bin would leave unusable dead space.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual <= 10 { 0.0 } else { 20.0 };
        score += 25.0 + open_bins_count as f64 * 0.5 - dead_space_penalty;
        // Favor new bin for large items that fill it well.
        score -= item_size as f64 * 0.15;
    }

    // Slight progression scaling: later in the stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fits the post-residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain: this bin will be closed next step
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 8.0; // dead space relative to lookahead item
        }
    }

    // Compare post_residual against mean residual of open bins.
    let pr = post_residual as f64;
    let mean_gap = pr - mean_residual;
    score += 0.15 * mean_gap;

    // Penalize creating very small unusable residuals.
    if pr > 0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let tight = mean_residual < 25.0;
        score += if tight { 60.0 } else { 10.0 };
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual already does this); amplify super-tight fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 25 {
        score -= 5.0;
    }

    // Penalize dead space relative to smallest plausible item (1..100 unknown, use 10 floor).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin
    // (chaining placements); otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else {
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open/spread across bins
    // (favor tight fits less aggressively); late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Global state coupling: if mean residual is high (lots of slack), penalize
    // leaving this bin's residual far from the mean (encourage balancing).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Penalize opening a new bin when many bins already exist and progress is late.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 10.0) + progress * 15.0;
        score += 20.0 + pressure;
        // But if nothing fits well anywhere, opening a new bin is fine:
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early stream with few bins: new bins are cheap.
        if open_bins_count <= 2 && progress < 0.3 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late in the stream, penalize wasted space more strongly.
    let progress_coupling = pr * (0.4 + 1.6 * progress * progress);
    score += progress_coupling * norm_pr;

    // Dead-space penalty: post residual too small for typical future items
    let dead = if pr > 0.0 { (10.0 - pr.min(10.0)).abs() } else { 0.0 };
    score += 3.0 * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poorly matched (large post_residual everywhere).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64 - 20.0 * (1.0 - norm_pr);
        // lookahead: if next item also fits a fresh bin's likely residual, less penalty
        if next_item_size > 0 && (bin_capacity as u32 - post_residual) >= next_item_size {
            score -= 8.0;
        }
    }

    // Lookahead synergy: reward bins whose post residual accommodates next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap) * (0.5 + progress);
    }

    // Mild spread penalty relative to mean residual (avoid fragmenting)
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets dead-space quality
    let pr = post_residual as u32;
    let class = pr % 10;
    score -= match class {
        0 => 12.0,                 // perfectly reusable decade residual
        1 | 9 => 4.0,
        2 | 8 => 1.0,
        3 | 7 => 0.0,
        4 | 6 => -2.0,             // awkward slivers
        _ => -4.0,                 // worst: 5-ish dead space
    };

    // Zero residual is ideal (bin perfectly closed)
    if pr == 0 {
        score -= 30.0;
    } else if pr < 10 {
        // unusable dead space (min item is 1, but small slivers rarely filled)
        score += (10 - pr) as f64 * 0.5;
    }

    // Coupling with next item: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact/near-exact chain fit is gold
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            if pr % next_item_size.max(1) == 0 {
                score -= 6.0; // harmonic divisibility bonus
            }
        } else {
            // next item won't chain here: penalize proportionally to overflow
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin; offset by tight fit of item
        score = 55.0 - (item_size as f64) * 0.35;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // next item complements this one to near-full
        }
        if fitting_bins_count > 0 && post_residual < 15 {
            score += 25.0; // don't open when an open bin fits tightly
        }
    }

    // Late in stream: consolidate, avoid fragmentation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.05;

    // Many open bins: prefer filling existing ones over spreading
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.02;

    // Relative fit quality: reward tight fill vs current residual
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 10.0;
    }

    // Mean-residual anchor: bins far below mean residual are poor targets
    score += ((mean_residual - post_residual as f64).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold the smallest plausible item are worthless.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size.min(bin_capacity)) && post_residual > 0 {
        score += 40.0 + (min_item - post_residual) as f64 * 2.0;
    }
    // Strongly penalize very small unusable gaps (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.5 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate handling: empty bin gets a baseline cost so it only wins
    // when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
        // Late in the stream, opening fresh bins is less attractive.
        score += 30.0 * progress;
    } else {
        // Reward bins whose residual is close to the mean (balanced usage),
        // penalize outliers creating fragmented state.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave another dead gap, mild penalty.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well (leaves a usable gap).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as u64 >= next_item_size as u64 {
            // Next item fits in the leftover gap: reward tight match.
            let gap = post_residual as f64 - next;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize proportionally to wasted gap.
            score += 10.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Penalize dead space that is too small to ever be useful
    // (items are at least 1, but small slivers < 10 are hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (best-fit tendency), with a soft non-linear weight.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 3.0 * (mean_gap / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when the current item is large relative to capacity
    // or no open bin fits well. Penalize opening new bins mildly otherwise.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bins more attractive early and for large items.
        score += 8.0 - 10.0 * frac - 4.0 * (1.0 - progress);
        // If the item fills the new bin almost exactly, strong reward.
        score -= 20.0 * frac * frac;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
