pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, smoothed polynomial in progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear coupling: waste penalty grows quadratically as stream progresses
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Tight fits rewarded more later in the stream
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bin bonus (only fitting bin)
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: penalize if next item won't fit post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for bins below mean residual (balance residuals)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: encourage only when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).sqrt();
        score += 5.0 + fragmentation - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction classes. Leftovers in low classes (tiny slivers) are
    // dead space; leftovers that are "friendly" multiples of common item
    // sizes are valuable.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Class boundaries via integer division on post_residual (harmonic bins of 10)
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => score += 60.0,        // unusable sliver (0..10): heavy penalty
        1 => score += 25.0,        // 10..20: only fits tiny items
        2 => score += 10.0,        // 20..30
        3 => score -= 5.0,         // 30..40: decent
        4 | 5 => score -= 12.0,    // 40..60: sweet spot
        6 => score -= 6.0,
        7 | 8 => score += 0.0,
        _ => {}                    // 90+: nearly empty bin
    }

    // Exact-fit modulo bonus: post_residual divisible by common item granules
    // (10/20/25/50) suggests the leftover can be filled by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    } else {
        // Perfect fill is ideal
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how tight the next fit would be
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty if leftover is small
            if post_residual < next_item_size && post_residual < 20 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when current residuals are poor
    // (large mean residual spread toward dead space) or many bins fit anyway.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // but if existing bins are fragmented (low mean residual relative to
        // what's needed) or many bins already fit, opening fresh is fine
        if mean_residual < 25.0 {
            score -= 15.0;
        }
        if fitting_bins_count >= 3 {
            score -= 10.0;
        }
    }

    // Stream progression: early in the stream, be more willing to open bins
    // (future flexibility); late in the stream, squeeze existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Mild tie-break: prefer bins whose residual is close to the mean
    // (keeps population homogeneous, easier future packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Tightness reward: fraction of residual consumed.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Lookahead synergy: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins, more early in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 4.0 * open_bins_count as f64 + 20.0 * (1.0 - progress);
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins far from the mean (more extreme utilization).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // perfect chain match
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover dead space after the lookahead item
            score += slack * 0.5;
            // bonus if chain residual becomes small/unusable (tight packing)
            if post_residual - next_item_size <= 10 {
                score -= 40.0;
            }
        } else {
            // next item cannot follow: post residual is potential dead space
            score += (post_residual as f64) * 0.3;
        }
    } else {
        // last item: just minimize waste
        score += (post_residual as f64) * 0.2;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.4;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral baseline plus penalty scaled by open bins
        score += 25.0 + open_bins_count as f64 * 2.0;
        // but if the item is large relative to capacity, new bin is fine
        if item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 30.0;
        }
        // lookahead: a fresh bin can host both item and next item
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Slight late-stream conservatism: keep bins open longer
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * (0.1 + 0.1 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste of the bin's space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if post-residual closely matches next item.
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // Prefer bins with residual below the mean residual (use the emptier space elsewhere).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (flexibility matters later); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when the item is huge and
        // no open bin gives a good fit, or when few fitting bins exist.
        score -= 22.0 * (1.0 - progress);
        if item_size >= 60 { score -= 10.0; }
        if fitting_bins_count <= 2 { score -= 12.0; }
        if post_residual < 20 { score += 25.0; } // huge item in fresh bin -> tiny waste is fine
        // Penalize opening new bins when open bins already fit well.
        if fit_ratio > 0.8 { score += 30.0; }
    } else {
        // Late stream: reward tight packing even more.
        score -= 8.0 * progress * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them harder.
    let progress_coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += progress_coupling * 0.3;

    // Cubic term: strongly punish near-full waste late in the stream
    score += norm_pr * norm_pr * norm_pr * cap * (progress * 1.5 + 0.25);

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + progress);
    } else if next_item_size > 0 {
        // penalize residual that wastes space relative to next item
        score += 4.0 * ((pr - next_item_size as f64).abs() / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Prefer bins with residual below mean (consolidation)
    score += 2.0 * (pr - mean_residual).max(-50.0).min(50.0) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: small residues are dead space.
    let r_mod = post_residual % 10;
    let r_div = post_residual / 10;
    match r_mod {
        0 => score -= 6.0,                       // perfect fit class
        1 | 2 => score += 5.0,                   // near-useless slivers
        3 | 4 => score += 2.0,
        8 | 9 => score -= 1.5,                   // roomy class, likely reusable
        _ => {}
    }
    // Integer-division thresholds on post_residual
    if r_div == 0 { score += 12.0; }             // post_residual < 10: dead bin
    if post_residual >= 50 { score -= 3.0; }     // still half-full after placement

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic if next % 10 matches residual class
            let n_mod = next_item_size % 10;
            if n_mod == r_mod { score -= 9.0; }
            else if post_residual - next_item_size < 10 { score += 3.0; } else { score -= 2.0; }
        } else {
            score += 4.0;                        // next item won't fit here
        }
        if next_item_size >= 70 { score -= 1.0; } // large next item: keep big bins open
    } else {
        score -= 5.0;                            // last item: any fit is fine
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening fresh bins is costly unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.05 * open_bins_count as f64;
        if post_residual < 10 { score -= 25.0; } // huge item only fits new bin
    }

    // Stream progression: early on, be greedy about tightness; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);
    score += progress * 1.5 * (mean_residual - post_residual as f64).abs() / 50.0;

    // Prefer bins already below mean residual (consolidating small leftovers).
    if (post_residual as f64) < mean_residual { score -= 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap = wasted space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else {
        // penalize residual that no plausible item (1..=100) can use well
        let dead = (post_residual as f64).ln() * 3.0;
        score += dead;
    }

    // Reward bins whose residual exactly matches a "nice" gap usable by next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // next item can still fit here
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0; // blocks the lookahead item
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * open_bins_count as f64;
        // but if all open bins would leave big dead space, allow new bin
        if post_residual == bin_capacity {
            let avg_dead = mean_residual - item_size as f64;
            if avg_dead > 25.0 {
                score -= 45.0;
            }
        }
    } else {
        // prefer tighter bins (small residual before placement)
        score += (bin_residual as f64) * 0.1;
        score -= mean_residual * 0.05;
    }

    // Mild stream-progression pressure: later in stream, tighten up
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small post-residual is good, but penalize dead space below minimum item size
        if post_residual < 10 {
            score += 500.0;
        }
        // Tightness reward: relative fill
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits: reward proportional to how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 2.0;
        } else {
            // next item won't fit here: penalize leaving a gap next item can't use
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (consolidate fullness)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge
    if bin_residual == bin_capacity {
        score += 150.0 - (item_size as f64 * 1.2);
    }

    // Late in stream: be more aggressive about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;

    // Many open bins: encourage closing them out
    score += open_bins_count as f64 * post_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 15.0 * chain_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving a stranded gap.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins below mean residual (keeps residual distribution balanced).
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize placing into open bins slightly); late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (30.0 - 55.0 * progress);

    // When many bins are open, favor consolidation into existing bins.
    score += new_bin * 0.15 * (open_bins_count as f64);

    // Slight preference for fuller bins overall.
    score -= 0.1 * ((bin_capacity - bin_residual) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: post residual weighted by stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 20.0 * poly;

    // Penalize dead space that cannot fit the next item (smoothly)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let wasted = gap / cap;
        score += 15.0 * wasted * wasted * (0.5 + progress);
        // Reward if next item fits snugly
        let snug = (next_item_size as f64 - pr).abs() / cap;
        score -= 10.0 * (1.0 - snug * snug);
    }

    // Last-chance bonus: avoid opening new bins when only one bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Smooth alignment with mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that partition capacity
    // into useful modular slots (multiples of 10, 25, 50 are "friendly").
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, ideal
    } else {
        let class_bonus: f64 = if pr % 50 == 0 {
            12.0
        } else if pr % 25 == 0 {
            9.0
        } else if pr % 10 == 0 {
            6.0
        } else if pr % 5 == 0 {
            3.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Penalize tiny dead space (unusable for typical items)
        if pr < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0 + (pr - next_item_size) as f64 * 0.2;
    } else if next_item_size > pr && pr > 0 {
        score += 5.0; // dead space for the known next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: prefer it only when it's early or open bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_pressure = (item_size as f64) / cap;
        // opening fresh bins is cheap early / when mean residual is small
        score -= 10.0 * (1.0 - progress) + 20.0 * (1.0 - mean_residual / cap);
        score += 30.0 * avg_pressure * progress;
    }

    // Mild preference to consolidate into bins below mean residual (filler logic)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_useful = 10u32;
    if post_residual < min_useful {
        score += 40.0; // unusable sliver -> strong penalty
    } else if post_residual <= 20 {
        score += 12.0; // very tight gap, low utility
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual >= min_useful {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item can't use the leftover: mild penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Open-bin pressure: prefer reusing bins when many are open, to consolidate.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make empty bins moderately attractive only when the current
    // item is large and would leave a big residual anyway, or when fits are scarce.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        if big_item || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 25.0; // discourage spreading into fresh bins
        }
    }

    // Slight preference for bins below mean residual (consolidating emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the NEXT item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to tightness of that fit
            let second_fit = post_residual - next_item_size;
            score -= 100.0 - (second_fit as f64).min(100.0);
        } else {
            // next item cannot use this residual: penalize dead space
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.8;
        }
    } else {
        // last item: strongly prefer minimal post residual
        score += 0.0;
    }

    // Penalize post_residual far below typical smallest item (dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Relative to mean residual: prefer bins with residual close to mean (balanced)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit; penalize new bins mildly so tight fits win
    if bin_residual == bin_capacity {
        score += 60.0;
        // late in the stream, opening bins is less useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // the item is large relative to residual or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 20.0 - 10.0 * fragmentation - 12.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins below mean residual when open-bin count is high (balance load).
    if open_bins_count > 3 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress) - 0.3 * pr_norm * pr * progress;

    // Reward tight fits more strongly as stream progresses
    score -= 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        let ns = next_item_size as f64;
        if (post_residual as f64) < ns {
            score += (ns - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * pr_norm;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Penalize spreading across many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Prefer bins below mean residual slightly (consolidation)
    score += 0.1 * (pr - mean_residual);

    // New-bin candidate: neutral baseline with mild late-stream penalty
    if bin_residual == bin_capacity {
        score = cap * (0.8 + 0.4 * progress) - 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create "dead zones"
    let residue_class = post_residual % 10;
    // Small non-zero residues are nearly unusable dead space -> penalize
    if post_residual > 0 && residue_class <= 3 {
        score += (4 - residue_class) as f64 * 2.0;
    }
    // Zero residue (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Integer-division thresholds on post_residual
    let half = bin_capacity / 2;
    if post_residual <= half / 2 {
        score += 6.0; // residual below quarter capacity: risky
    } else if post_residual >= half {
        score -= 4.0; // residual still large: flexible bin
    }

    // Coupling with next item: does the leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size.min(post_residual)) as f64 * 0.15;
            // harmonic bonus: next item leaves a zero-residue class again
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize small leftovers harder
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer it only when it's early or many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 8.0 + 10.0 * progress
            + (open_bins_count as f64).sqrt() * 2.0;
        // but if mean residual is small, reusing open bins is better
        score += (mean_residual / bin_capacity as f64) * 5.0;
    }

    // Mild preference for tighter bins overall
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
