    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Prefer bins tighter than the mean residual (best-fit leaning).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Early stream: be slightly more open to new bins to build structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
