    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            open_penalty += 100.0; // an empty bin wastes the lookahead opportunity
        }
        if post_residual > 20 && progress > 0.5 && open_bins_count > 3 {
            open_penalty -= 60.0; // poor fit late in stream: new bin more acceptable
        }
        score += open_penalty;
    }

    // Slight preference for bins with larger residuals when item is large
    // (safety against overflow-like tight fits), small effect.
    score += (item_size as f64 / bin_capacity as f64) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dynamic time horizon: progress through the stream in [0, 1].
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let is_new_bin = bin_residual == bin_capacity;
    let item_frac = item_size as f64 / bin_capacity as f64;

    // Perfect fit: strong reward for completely filling a bin.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin (scaled by how much of the bin we consume).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 15.0 * item_frac;
    }

    // Lookahead (k=2): reward leaving room for the next item,
    // penalize stranding dead space that the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 6.0 + 0.15 * nxt;
        } else if post_residual > 0 {
            // Dead space is worse early (long horizon ahead), milder late.
            score += 0.10 * post_residual as f64 * (1.0 - progress);
        }
    }

    // New-bin candidate logic: opening a new bin is justified for large items
    // or when nothing fits, but penalized when decent open bins exist.
    if is_new_bin {
        let large_item_bonus = 40.0 * item_frac;
        let poor_fit_penalty = if fitting_bins_count == 0 {
            0.0
        } else {
            30.0 + 2.0 * open_bins_count as f64
        };
        let late_penalty = 20.0 * progress; // late in stream, consolidate instead
        score += 10.0 + poor_fit_penalty + late_penalty - large_item_bonus;
    }

    // Favor bins that are already substantially filled (keeps bins "hot").
    if !is_new_bin {
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Global state coupling: when mean residual across open bins is high,
    // there is slack in the system — slightly discourage dumping into any bin early.
    score += 0.02 * mean_residual * (1.0 - progress);

    // Mild pressure against proliferating open bins early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = (pr / c).clamp(0.0, 1.0);

    // Base: waste after placement, non-linearly penalized.
    let mut score = pr * (1.0 + 0.6 * fit * fit);

    // Smooth coupling: waste matters more as stream progresses.
    score += 12.0 * progress * (pr / c).powi(3) * c * 0.1;

    // Reward tight fits (small post_residual) via smooth saturation.
    score -= 15.0 * (-(pr * pr) / (0.25 * c * c)).exp();

    // Dead-space penalty: residual too small for any plausible item.
    let min_item = 1.0f64;
    if pr < min_item * 9.0 {
        score += 20.0 * (1.0 - pr / (min_item * 9.0)).powi(2);
    }

    // Lookahead: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64) / pr.max(1.0)).abs().min(1.0);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty scaled by how close it was.
        score += 4.0 * (1.0 - (pr / (next_item_size as f64)).clamp(0.0, 1.0));
    }

    // Last-chance bonus: only fitting bin => strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference for bins below mean residual (balance load smoothly).
    score += 2.0 * ((bin_residual as f64) - mean_residual) / c;

    // New-bin candidate: penalize opening new bins early, allow late in stream
    // or when few bins fit the item.
    if bin_residual == bin_capacity {
        let openness = progress * progress;
        score += 30.0 * (1.0 - openness) - 10.0 * openness;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band does the leftover fall in?
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward small post_residual (tight fit), with a harmonic ladder.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < eighth {
        score -= 25.0;
    } else if post_residual < quarter {
        score -= 10.0;
    } else if post_residual < bin_capacity / 2 {
        score += 5.0;
    } else {
        score += 20.0; // more than half wasted
    }

    // Modulo-10 dead-space class: leftovers in [1..10] are nearly unusable for 10..80 items.
    let m = post_residual % 10;
    if m > 0 && post_residual < 10 {
        score += 15.0; // dead space < 10
    }
    if post_residual > 0 && post_residual <= 20 {
        score += 8.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / c);
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 6.0 * ((next_item_size - post_residual) as f64 / c);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish, but avoid opening new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.15 * open_bins_count as f64;
        // but if the item is large and nothing tight exists, new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer fuller bins relative to mean residual.
    score += 0.3 * (mean_residual - (bin_residual as f64));

    // Stream progression: later in the stream, be greedier about tight fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (1.0 - pr / c);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than moderate leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward exact/tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // If the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }

    // Pressure from number of open bins: encourage consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize relative to current mean residual so that
    // opening a bin only wins when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.5;
    }

    // Mild trend: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post residual matches next item size exactly (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 60.0; // perfect 2-step fit
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to how much dead space remains.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize residual far above the mean residual of open bins (fragmentation signal).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: reward strongly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tightness = if next_item_size > 0 && post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            item_size as f64
        };
        score += 15.0 + 0.4 * tightness;
    }

    // Mild late-stream tightening: prefer fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual < next_item_size / 2 {
            score += 8.0; // post_residual likely wasted given lookahead
        }
    }

    // Favor bins with residual below mean residual (more filled bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in the stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;
    score += open_bins_count as f64 * 0.2 * progress;

    // New bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 15.0 - progress * 5.0;
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // waste in early bins costs more later (compounding dead space).
    let progress_coupling = norm_pr * norm_pr * (0.5 + progress);
    score += 30.0 * progress_coupling;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = (-norm_pr * 6.0).exp() - 1.0;
    score -= 20.0 * tightness * (1.0 - progress);

    // Penalize post_residual that cannot fit the lookahead item smoothly.
    let next_fits = (norm_next - norm_pr).max(0.0);
    score += 15.0 * next_fits * next_fits * (1.0 + progress);

    // Reward post_residual that exactly accommodates the next item (smooth gaussian-like).
    let gap = (norm_pr - norm_next).abs();
    score -= 12.0 * (-gap * gap * 40.0).exp() * (1.0 - progress);

    // Penalize deviating far from mean residual (fragmentation pressure), smooth quadratic.
    let dev = norm_pr - mean_norm;
    score += 8.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many bins relative to progress.
    score += 0.5 * open_bins_count as f64 * norm_item * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals divisible by common small item sizes (or near capacity fractions) are valuable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals below the smallest plausible item are worthless.
    if post_residual < 10 {
        score += 60.0 - post;
    }

    // Harmonic reward: post_residual divisible by 50, 25, 20, 10 leaves room for standard items.
    if post_residual > 0 {
        if post_residual % 50 == 0 { score -= 12.0; }
        else if post_residual % 25 == 0 { score -= 8.0; }
        else if post_residual % 20 == 0 { score -= 6.0; }
        else if post_residual % 10 == 0 { score -= 4.0; }
        else if post_residual % 5 == 0 { score -= 2.0; }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 - gap * 0.2;
        if next_item_size == post_residual { score -= 10.0; }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty for wasting large residual.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or open bins are crowded/tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 1.2;
        if tight || item_size >= 60 || open_bins_count == 0 {
            score -= 5.0 + progress * 5.0;
        } else {
            score += 10.0; // discourage opening bins when existing ones are roomy
        }
    }

    // Slight preference for bins with residual close to item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 8.0;

    // Prefer fuller bins on average.
    score -= (bin_capacity as f64 - bin_residual as f64) / cap * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small to ever hold
    // another item are pure waste. Penalize them quadratically.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        // gap in [1,9] is nearly unusable dead space
        score += 60.0 + (10 - post_residual as i32 as f64) * 8.0;
    } else if post_residual < 20 {
        // small-but-usable gap: mild penalty to prefer tighter fits elsewhere
        score += 12.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Open-bins pressure: discourage spreading across many bins when
    // existing bins fit well; encourage opening a new bin when this bin
    // is the only fit (last-chance) and the fit is bad.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last chance: strongly prefer using this bin over a new one
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive when
    // the next item is large relative to this bin's post_residual, or when
    // the fit here would be very loose.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: slightly above a good fit
        score = bin_capacity as f64 * 0.55;
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else if next_item_size > 0 {
        // If the next item can't use this bin's post_residual anyway,
        // loosen the penalty for a loose fit here.
        if next_item_size > post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            // next item could slot into the leftover: reward leaving a usable gap
            let gap_diff = post_residual as i32 - next_item_size as i32;
            if gap_diff <= 5 {
                score -= 15.0;
            }
        }
    }

    // Mean-residual coupling: if average leftover across bins is high,
    // be pickier (penalize loose fits) to consolidate.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score += (mean_residual - 30.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: penalize leftover after the pair
        let post2 = post_residual - next_item_size;
        score -= 100.0 - post2 as f64 * 0.5;
    } else if next_item_size > post_residual && next_item_size <= bin_capacity {
        // next item won't fit here; prefer small post_residual (usable dead space)
        score += post_residual as f64 * 0.3;
    }

    // Relative to mean residual: avoid wasting large-residual bins on small items
    score += (mean_residual - post_residual as f64) * 0.2;

    // Last chance bonus: if this is the only fitting bin, strongly prefer it over new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate penalty: only open a new bin when item is large relative to residuals
    if bin_residual == bin_capacity {
        score += 250.0 - item_size as f64 * 2.0;
        // avoid opening new bin if many open bins could fit
        score += fitting_bins_count as f64 * 50.0;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Lookahead: penalize if next item cannot fit into post_residual (creates pressure),
    // reward if it can (chaining placements).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score -= pressure * (0.5 + progress);

    // New-bin candidate handling: empty bin gets base cost so it's chosen only when
    // no open bin offers a good fit; make it more attractive early, less late.
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - 0.5 * progress) + 0.15 * open_bins_count as f64;
    }

    // Mild penalty for leaving residual near awkward mid-range values.
    let mid = (post_residual as f64 - 50.0).abs();
    score += 0.08 * mid;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: reward tight fits via smooth polynomial in post_residual
    let mut score = post * (1.0 + 0.5 * post_norm * post_norm);

    // Non-linear coupling with stream progress: late in the stream,
    // tighten preference for low post_residual (dead space is costlier).
    score += 40.0 * post_norm * post_norm * (progress * progress);

    // Penalize bins whose residual is far from the mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0 + 30.0 * progress;
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 20.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Smoothly penalize leaving post_residual that cannot host next item
        score += 10.0 * ((post - next_item_size as f64) / cap).abs();
    }

    // New-bin candidate: prefer opening a new bin only when no tight fit exists
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) && (item_size as u64 <= bin_capacity as u64);
    if is_new_bin {
        // Penalize new bin mildly; the polynomial terms above make tight fits win
        score += 55.0 - 25.0 * progress - 0.2 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= (bin_residual - item_size) as f64 {
            score -= 30.0; // fresh bin can host both current and next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes.
    // Class 0: post_residual == 0 (perfect fill) -> big reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class small (<= 10): near-perfect fill, mild reward.
        if post_residual <= 10 {
            score -= 12.0;
        }
        // Harmonic residue classes: post_residual % 25, % 10, % 5
        let r25 = post_residual % 25;
        let r10 = post_residual % 10;
        let r5 = post_residual % 5;
        if r25 == 0 {
            score -= 6.0; // multiples of 25 are reusable by quarter-size items
        }
        if r10 == 0 {
            score -= 4.0;
        } else if r5 == 0 {
            score -= 2.0;
        }
        // Penalize dead-space classes: residuals in (10, 20) are hard to fill
        // since typical items are >= 10.
        if post_residual > 10 && post_residual < 20 {
            score += 14.0;
        }
        // Integer-division thresholds on post_residual
        let q = post_residual / 20; // coarse harmonic band
        score += q as f64 * 1.5; // prefer smaller bands
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // exact harmonic match with next item
            if post_residual == next_item_size {
                score -= 10.0;
            } else if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; make it attractive only when
    // existing fits are poor. Empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = 100.0;
        // cheaper to open new bin late in stream? slightly more conservative early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // if next item is large, fresh bin is valuable
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Congestion: many open bins -> prefer consolidating into existing bins
    // (applies to non-empty bins only, since empty-bin case already reset score).
    if bin_residual != bin_capacity {
        let congestion = open_bins_count as f64;
        score -= 0.3 * congestion;
        // mean residual coupling: if this bin's residual is far below mean,
        // it's a tight fit -> favor it.
        let diff = mean_residual - post_residual as f64;
        score -= 0.2 * diff;
    }

    // Slight preference for tighter fits overall
    score += 0.05 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize unusable small gaps nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize large leftover gaps only mildly (still usable), scaled by tightness.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Last-chance bonus: only fitting bin, avoid opening new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead coupling: if next item fits post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item nearly fits, slight penalty for leaving a tempting-but-broken gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded/tight.
    if bin_residual == bin_capacity {
        score -= 20.0;
        if open_bins_count as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Late in stream: prefer packing tighter into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual == 0 as u32 as bool) as u32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chaining of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect two-item fill: heavily reward
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item still fits: reward proportional to tightness of the chain
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 - chain_waste * 0.4;
        } else {
            // Next item cannot follow: penalize relative to the overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    } else {
        // Last item: prefer minimal final residual
        score += 5.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual far below mean creates isolated dead space.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05; // slight reward for being below mean (tighter bin)
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
        // but allow new bin if item is large and would leave a bad fit elsewhere
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Small progression bias: later in stream, tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}
